def color_scheme(name: str) -> dict[str, str]:
    return COLOR_SCHEMES.get(name, COLOR_SCHEMES["light"])


def lock_indicator_segment(mode: str, left: float, width: float, top: float,
                           height: float, inset: float, tab_style: str):
    """Return one solid, space-free edge marker for a tab lock mode."""
    if mode == "locked":
        return (left + max(2, inset / 2), top + 4,
                left + width - max(2, inset / 2), top + 4)
    if mode == "reset":
        start_y = top + (max(4, inset / 2) if tab_style == "rounded" else 3)
        return (left + 4, start_y, left + 4, height - 2)
    return None


def contrasting_edge_color(background: str) -> str:
    """Choose a crisp lock marker for both theme and custom tab colours."""
    value = background.lstrip("#")
    if len(value) != 6:
        return "#17232c"
    red, green, blue = (int(value[index:index + 2], 16) for index in (0, 2, 4))
    luminance = (0.2126 * red + 0.7152 * green + 0.0722 * blue) / 255
    return "#17232c" if luminance >= 0.52 else "#f7fbff"


def configure_ttk_theme(root, palette: dict[str, str]) -> None:
    """Apply one coherent palette to all ttk controls in this interpreter."""
    style = ttk.Style(root)
    try:
        style.theme_use("clam")
    except tk.TclError:
        pass
    common = {"background": palette["window"], "foreground": palette["text"]}
    style.configure(".", **common)
    style.configure("TFrame", background=palette["window"])
    style.configure("TLabel", background=palette["window"], foreground=palette["text"])
    style.configure("TButton", background=palette["button"], foreground=palette["text"],
                    bordercolor=palette["border"], lightcolor=palette["button"],
                    darkcolor=palette["border"])
    style.map("TButton", background=[("active", palette["button_active"]),
                                     ("pressed", palette["selection"])],
              foreground=[("pressed", "#ffffff")])
    for name in ("TCheckbutton", "TRadiobutton"):
        style.configure(name, background=palette["window"], foreground=palette["text"])
        style.map(name, background=[("active", palette["window"])],
                  foreground=[("disabled", palette["muted"])])
    style.configure("TEntry", fieldbackground=palette["entry"], foreground=palette["text"],
                    insertcolor=palette["text"], bordercolor=palette["border"])
    style.configure("TCombobox", fieldbackground=palette["entry"], background=palette["button"],
                    foreground=palette["text"], arrowcolor=palette["text"],
                    bordercolor=palette["border"])
    style.map("TCombobox", fieldbackground=[("readonly", palette["entry"])],
              foreground=[("readonly", palette["text"])])
    style.configure("Treeview", background=palette["surface"], fieldbackground=palette["surface"],
                    foreground=palette["text"], bordercolor=palette["border"])
    style.configure("Treeview.Heading", background=palette["surface_alt"], foreground=palette["text"],
                    bordercolor=palette["border"])
    style.map("Treeview.Heading", background=[("active", palette["button_active"])])
    for name, selected in (("Active.Treeview", palette["selection"]),
                           ("Inactive.Treeview", palette["inactive_selection"]),
                           ("PFCSearch.Treeview", palette["selection"]),
                           ("PFCCompare.Treeview", palette["selection"])):
        style.configure(name, background=palette["surface"], fieldbackground=palette["surface"],
                        foreground=palette["text"], bordercolor=palette["border"])
        style.map(name, background=[("selected", selected)],
                  foreground=[("selected", "#ffffff")])
        style.configure(name + ".Heading", background=palette["surface_alt"],
                        foreground=palette["text"], bordercolor=palette["border"])
    style.configure("TNotebook", background=palette["tab_bar"], bordercolor=palette["border"])
    style.configure("TNotebook.Tab", background=palette["tab_default"], foreground=palette["tab_text"])
    style.configure("TScrollbar", background=palette["button"], troughcolor=palette["surface_alt"],
                    arrowcolor=palette["text"], bordercolor=palette["border"])


def add_scaled_cascade(menu: tk.Menu, label: str, submenu: tk.Menu) -> None:
    """Keep a native menu model; PFC draws header cascades itself."""
    menu.add_cascade(label=label, menu=submenu)


def align_scaled_cascade_arrows(menu: tk.Menu) -> None:
    """Compatibility no-op for the native menu model."""


def _refresh_scaled_indicators(menu: tk.Menu) -> None:
    for index, variable, value in getattr(menu, "_pfc_scaled_indicators", ()):
        selected = bool(variable.get()) if value is None else variable.get() == value
        menu.entryconfigure(index, accelerator="✓" if selected else "")


def _register_scaled_indicator(menu: tk.Menu, variable, value) -> None:
    if not hasattr(menu, "_pfc_scaled_indicators"):
        menu._pfc_scaled_indicators = []
        menu.configure(postcommand=lambda target=menu: _refresh_scaled_indicators(target))
    menu._pfc_scaled_indicators.append((menu.index("end"), variable, value))
    _refresh_scaled_indicators(menu)


def add_scaled_checkbutton(menu: tk.Menu, label: str, variable, command=None) -> None:
    menu.add_checkbutton(label=label, variable=variable, command=command, indicatoron=False)
    _register_scaled_indicator(menu, variable, None)


def add_scaled_radiobutton(menu: tk.Menu, label: str, value, variable, command=None) -> None:
    menu.add_radiobutton(label=label, value=value, variable=variable, command=command,
                         indicatoron=False)
    _register_scaled_indicator(menu, variable, value)


class HeaderPopupController:
    """Draw scalable, keyboard-accessible header menus without native glyphs."""

    def __init__(self, owner, descriptions=None):
        self.owner = owner
        self.descriptions = descriptions or {}
        self.popups = []
        self.tooltip = None
        self.tooltip_job = None

    def show(self, button, menu) -> None:
        self.close_all()
        popup = _HeaderPopup(self, menu, None)
        self.popups = [popup]
        popup.show(button.winfo_rootx(), button.winfo_rooty() + button.winfo_height())
        popup.top.grab_set_global()
        popup.canvas.focus_force()

    def open_child(self, parent, index) -> None:
        depth = self.popups.index(parent)
        self._close_from(depth + 1)
        submenu_name = parent.menu.entrycget(index, "menu")
        if not submenu_name:
            return
        submenu = parent.menu.nametowidget(submenu_name)
        child = _HeaderPopup(self, submenu, parent)
        self.popups.append(child)
        row_top = parent.row_bounds[index][0]
        x = parent.top.winfo_rootx() + parent.width - 1
        y = parent.top.winfo_rooty() + row_top
        left, _top, width, _height = virtual_screen_bounds(child.top)
        if x + child.width > left + width:
            x = parent.top.winfo_rootx() - child.width + 1
        child.show(x, y)
        child.canvas.focus_force()

    def close_child(self, popup) -> None:
        depth = self.popups.index(popup)
        parent = popup.parent
        self._close_from(depth)
        if parent is not None:
            parent.canvas.focus_force()

    def close_all(self) -> None:
        self._hide_tooltip()
        if self.popups:
            try:
                self.popups[0].top.grab_release()
            except tk.TclError:
                pass
        self._close_from(0)

    def _close_from(self, depth: int) -> None:
        self._hide_tooltip()
        for popup in reversed(self.popups[depth:]):
            try:
                popup.top.destroy()
            except tk.TclError:
                pass
        del self.popups[depth:]

    def pointer_inside(self, x: int, y: int) -> bool:
        return any(p.top.winfo_exists() and p.top.winfo_rootx() <= x < p.top.winfo_rootx() + p.width
                   and p.top.winfo_rooty() <= y < p.top.winfo_rooty() + p.height
                   for p in self.popups)

    def schedule_tooltip(self, popup, index) -> None:
        self._hide_tooltip()
        self.tooltip_job = self.owner.after(5000, lambda: self._show_tooltip(popup, index))

    def _show_tooltip(self, popup, index) -> None:
        self.tooltip_job = None
        if popup not in self.popups:
            return
        label = popup.menu.entrycget(index, "label")
        text = self.descriptions.get(label, label)
        tip = tk.Toplevel(self.owner)
        tip.overrideredirect(True)
        tip.attributes("-topmost", True)
        x, y = self.owner.winfo_pointerxy()
        tip.geometry(f"+{x + 14}+{y + 18}")
        palette = getattr(self.owner, "palette", COLOR_SCHEMES["light"])
        tk.Label(tip, text=text, justify="left", background=palette["tooltip"],
                 foreground=palette["tooltip_text"],
                 relief="solid", borderwidth=1, padx=7, pady=4,
                 font=tkfont.nametofont("TkDefaultFont")).pack()
        self.tooltip = tip

    def _hide_tooltip(self) -> None:
        if self.tooltip_job is not None:
            try:
                self.owner.after_cancel(self.tooltip_job)
            except tk.TclError:
                pass
            self.tooltip_job = None
        if self.tooltip is not None:
            try:
                self.tooltip.destroy()
            except tk.TclError:
                pass
            self.tooltip = None


class _HeaderPopup:
    BG, FG, DISABLED, ACTIVE_BG, ACTIVE_FG, BORDER = (
        "#f0f0f0", "#101010", "#808080", "#087bdc", "#ffffff", "#8a8a8a")

    def __init__(self, controller, menu, parent):
        self.controller, self.menu, self.parent = controller, menu, parent
        palette = getattr(controller.owner, "palette", COLOR_SCHEMES["light"])
        self.BG, self.FG = palette["menu"], palette["menu_text"]
        self.DISABLED, self.ACTIVE_BG = palette["menu_disabled"], palette["menu_active"]
        self.ACTIVE_FG, self.BORDER = palette["menu_active_text"], palette["border"]
        self.SEPARATOR = palette["separator"]
        self.top = tk.Toplevel(parent.top if parent is not None else controller.owner)
        self.top.withdraw()
        self.top.overrideredirect(True)
        self.top.attributes("-topmost", True)
        self.font = tkfont.nametofont("TkMenuFont")
        self.selected = None
        self.items = []
        self.row_bounds = {}
        self._run_postcommand()
        self._measure()
        self.canvas = tk.Canvas(self.top, width=self.width, height=self.height, background=self.BG,
                                highlightthickness=1, highlightbackground=self.BORDER, takefocus=True)
        self.canvas.pack()
        self.canvas.bind("<Motion>", self._motion)
        self.canvas.bind("<Leave>", lambda _event: self.controller._hide_tooltip())
        self.canvas.bind("<ButtonRelease-1>", self._click)
        self.canvas.bind("<ButtonPress-1>", self._outside_click)
        self.top.bind("<ButtonPress-1>", self._outside_click, add="+")
        self.canvas.bind("<Down>", lambda _event: self._move(1))
        self.canvas.bind("<Up>", lambda _event: self._move(-1))
        self.canvas.bind("<Right>", lambda _event: self._open_selected())
        self.canvas.bind("<Left>", lambda _event: self._left())
        self.canvas.bind("<Return>", lambda _event: self._invoke_selected())
        self.canvas.bind("<space>", lambda _event: self._invoke_selected())
        self.canvas.bind("<Escape>", lambda _event: self._escape())
        self._draw()

    def _run_postcommand(self) -> None:
        command = self.menu.cget("postcommand")
        if command:
            try:
                self.menu.tk.eval(command)
            except tk.TclError:
                pass

    def _measure(self) -> None:
        end = self.menu.index("end")
        label_width = accelerator_width = 0
        line = self.font.metrics("linespace")
        self.row_height = max(24, line + max(8, line // 3))
        y = 3
        for index in range(end + 1 if end is not None else 0):
            kind = self.menu.type(index)
            if kind == "tearoff":
                continue
            if kind == "separator":
                height = max(7, line // 3)
                self.items.append((index, kind, "", "", "normal"))
            else:
                label = self.menu.entrycget(index, "label")
                accelerator = self.menu.entrycget(index, "accelerator")
                state = self.menu.entrycget(index, "state")
                label_width = max(label_width, self.font.measure(label))
                if accelerator != "✓":
                    accelerator_width = max(accelerator_width, self.font.measure(accelerator))
                height = self.row_height
                self.items.append((index, kind, label, accelerator, state))
            self.row_bounds[index] = (y, y + height)
            y += height
        marker = max(line, self.font.measure("▶"), self.font.measure("✓"))
        self.left_pad = max(10, line // 2)
        self.label_x = self.left_pad
        self.marker_width = marker + self.left_pad
        gap = max(18, line)
        self.width = self.left_pad + label_width + gap + accelerator_width + self.marker_width
        self.height = y + 3
        self.accelerator_x = self.width - self.marker_width - self.left_pad
        self.marker_x = self.width - self.left_pad

    def show(self, x: int, y: int) -> None:
        x, y = clamp_popup_position(
            x, y, self.width, self.height, virtual_screen_bounds(self.top))
        self.top.geometry(f"{self.width}x{self.height}+{x}+{y}")
        self.top.deiconify()
        self.top.lift()

    def _draw(self) -> None:
        self.canvas.delete("all")
        for index, kind, label, accelerator, state in self.items:
            top, bottom = self.row_bounds[index]
            if kind == "separator":
                y = (top + bottom) // 2
                self.canvas.create_line(self.left_pad, y, self.width - self.left_pad, y,
                                        fill=self.SEPARATOR)
                continue
            active = index == self.selected and state != "disabled"
            bg = self.ACTIVE_BG if active else self.BG
            fg = self.ACTIVE_FG if active else (self.DISABLED if state == "disabled" else self.FG)
            self.canvas.create_rectangle(1, top, self.width - 1, bottom, fill=bg, outline="")
            self.canvas.create_text(self.label_x, (top + bottom) // 2, text=label, anchor="w",
                                    fill=fg, font=self.font)
            if accelerator and accelerator != "✓":
                self.canvas.create_text(self.accelerator_x, (top + bottom) // 2, text=accelerator,
                                        anchor="e", fill=fg, font=self.font)
            marker = "▶" if kind == "cascade" else ("✓" if accelerator == "✓" else "")
            if marker:
                self.canvas.create_text(self.marker_x, (top + bottom) // 2, text=marker,
                                        anchor="e", fill=fg, font=self.font)

    def _index_at(self, y):
        for index, (top, bottom) in self.row_bounds.items():
            if top <= y < bottom and self.menu.type(index) != "separator":
                return index
        return None

    def _select(self, index) -> None:
        if index == self.selected:
            return
        self.selected = index
        self._draw()
        if index is not None:
            self.controller.schedule_tooltip(self, index)
            if self.menu.type(index) == "cascade" and self.menu.entrycget(index, "state") != "disabled":
                self.controller.open_child(self, index)
            else:
                self.controller._close_from(self.controller.popups.index(self) + 1)

    def _motion(self, event) -> None:
        self._select(self._index_at(event.y))

    def _outside_click(self, event) -> str | None:
        if not self.controller.pointer_inside(event.x_root, event.y_root):
            self.controller.close_all()
            return "break"
        return None

    def _click(self, event) -> str:
        index = self._index_at(event.y)
        if index is not None:
            self._select(index)
            self._invoke(index)
        return "break"

    def _enabled_indexes(self):
        return [index for index, kind, _label, _accelerator, state in self.items
                if kind != "separator" and state != "disabled"]

    def _move(self, direction: int) -> str:
        indexes = self._enabled_indexes()
        if not indexes:
            return "break"
        if self.selected not in indexes:
            target = indexes[0 if direction > 0 else -1]
        else:
            target = indexes[(indexes.index(self.selected) + direction) % len(indexes)]
        self._select(target)
        return "break"

    def _open_selected(self) -> str:
        if self.selected is not None and self.menu.type(self.selected) == "cascade":
            self.controller.open_child(self, self.selected)
            self.controller.popups[-1]._move(1)
        return "break"

    def _invoke_selected(self) -> str:
        if self.selected is not None:
            self._invoke(self.selected)
        return "break"

    def _invoke(self, index) -> None:
        if self.menu.entrycget(index, "state") == "disabled":
            return
        if self.menu.type(index) == "cascade":
            self.controller.open_child(self, index)
            self.controller.popups[-1].canvas.focus_force()
            return
        menu, controller = self.menu, self.controller
        controller.close_all()
        menu.invoke(index)

    def _left(self) -> str:
        if self.parent is not None:
            self.controller.close_child(self)
        return "break"

    def _escape(self) -> str:
        if self.parent is not None:
            self.controller.close_child(self)
        else:
            self.controller.close_all()
        return "break"


class ChamferNotebook(ttk.Frame):
    """A small Notebook-compatible container with canvas-drawn colored tabs."""

    def __init__(self, master, on_color_changed=None, on_lock_changed=None,
                 on_tabs_reordered=None, on_tab_drag=None,
                 tab_style="right_skirt", **kwargs):
        super().__init__(master, **kwargs)
        self.on_color_changed = on_color_changed or (lambda _child, _color: None)
        self.on_lock_changed = on_lock_changed or (lambda _child, _mode: None)
        self.on_tabs_reordered = on_tabs_reordered or (lambda: None)
        self.on_tab_drag = on_tab_drag or (lambda _action, _tabs, _child, _event: False)
        self._tabs = []
        self._texts = {}
        self._colors = {}
        self._locks = {}
        self._selected = None
        if tab_style == "compact":
            tab_style = "right_skirt"
        self._tab_style = tab_style if tab_style in TAB_STYLES else "right_skirt"
        self._hitboxes = []
        self._drag_tab = None
        self._drag_start_x = 0
        self._drag_original_order = ()
        self._drag_moved = False
        self._drag_external = False
        self._drop_position = None
        self.bar = tk.Canvas(self, height=34, takefocus=True, highlightthickness=2,
                             highlightbackground="#71879a", highlightcolor="#0078d4",
                             background="#9eafbd")
        self.bar.pack(fill="x", side="top")
        self.bar.bind("<ButtonPress-1>", self._tab_press)
        self.bar.bind("<FocusIn>", lambda _event: self.bar.configure(highlightthickness=2))
        self.bar.bind("<B1-Motion>", self._tab_motion)
        self.bar.bind("<ButtonRelease-1>", self._tab_release)
        self.bar.bind("<Button-3>", self._popup)
        self.bar.bind("<Configure>", lambda _e: self._draw())
        self.palette = COLOR_SCHEMES["light"]

    def add(self, child, text="", color="default", lock="unlocked", position=None, **_kwargs):
        if child not in self._tabs:
            if position is None:
                self._tabs.append(child)
            else:
                self._tabs.insert(max(0, min(position, len(self._tabs))), child)
        self._texts[child] = text
        self._colors[child] = normalize_tab_color(color)
        self._locks[child] = lock if lock in {"unlocked", "locked", "reset"} else "unlocked"
        self.select(child)

    def tabs(self):
        return tuple(str(child) for child in self._tabs)

    def select(self, tab=None):
        if tab is None:
            return str(self._selected) if self._selected is not None else ""
        child = self._resolve(tab)
        if child is self._selected:
            return str(child)
        if self._selected is not None:
            self._selected.pack_forget()
        self._selected = child
        child.pack(fill="both", expand=True, side="top")
        self._draw()
        self.event_generate("<<NotebookTabChanged>>")
        return str(child)

    def forget(self, tab):
        child = self._resolve(tab)
        was_selected = child is self._selected
        child.pack_forget()
        self._tabs.remove(child)
        self._texts.pop(child, None); self._colors.pop(child, None); self._locks.pop(child, None)
        if was_selected:
            self._selected = None
            if self._tabs:
                self.select(self._tabs[min(len(self._tabs) - 1, 0)])
        self._draw()

    def tab(self, tab, **options):
        child = self._resolve(tab)
        if "text" in options:
            self._texts[child] = options["text"]; self._draw()
        return {"text": self._texts.get(child, "")}

    def index(self, tab):
        return self._tabs.index(self._resolve(tab))

    def reorder(self, tab, position, notify=True):
        child = self._resolve(tab)
        old_position = self._tabs.index(child)
        new_position = max(0, min(int(position), len(self._tabs) - 1))
        if old_position == new_position:
            return False
        self._tabs.pop(old_position)
        self._tabs.insert(new_position, child)
        self._draw()
        if notify:
            self.on_tabs_reordered()
            self.event_generate("<<NotebookTabsReordered>>")
        return True

    def insertion_index_at(self, x_root, y_root):
        """Return a tab insertion index when a screen point is over this tab bar."""
        if not self.bar.winfo_viewable():
            return None
        left, top = self.bar.winfo_rootx(), self.bar.winfo_rooty()
        if not (left <= x_root < left + self.bar.winfo_width() and
                top <= y_root < top + self.bar.winfo_height()):
            return None
        x = x_root - left
        insertion = 0
        for tab_left, tab_right, _child in self._hitboxes:
            if x > (tab_left + tab_right) / 2:
                insertion += 1
        return insertion

    def _event_root(self, event):
        return (getattr(event, "x_root", self.bar.winfo_rootx() + event.x),
                getattr(event, "y_root", self.bar.winfo_rooty() +
                        getattr(event, "y", max(1, self.bar.winfo_height() // 2))))

    def set_drop_position(self, position=None):
        self._drop_position = position
        self._draw()

    def set_color(self, tab, color, notify=True):
        child = self._resolve(tab)
        self._colors[child] = normalize_tab_color(color)
        self._draw()
        if notify:
            self.on_color_changed(child, self._colors[child])

    def set_lock(self, tab, mode, notify=True):
        child = self._resolve(tab)
        self._locks[child] = mode if mode in {"unlocked", "locked", "reset"} else "unlocked"
        self._draw()
        if notify:
            self.on_lock_changed(child, self._locks[child])

    def redraw(self):
        self._draw()

    def set_style(self, style):
        if style == "compact":
            style = "right_skirt"
        self._tab_style = style if style in TAB_STYLES else "right_skirt"
        self._draw()

    def set_theme(self, palette):
        self.palette = palette
        self.bar.configure(background=palette["tab_bar"],
                           highlightbackground=palette["border"],
                           highlightcolor=palette["selection"])
        self._draw()

    def _resolve(self, tab):
        if tab in self._tabs:
            return tab
        return self.nametowidget(tab)

    def _draw(self):
        self.bar.delete("all"); self._hitboxes.clear()
        font = tkfont.nametofont("TkDefaultFont")
        right_skirt = self._tab_style == "right_skirt"
        height = max(30, font.metrics("linespace") + 13)
        self.bar.configure(height=height)
        overlap = {"right_skirt": -2, "rounded": 2, "squarish": 0}[self._tab_style]
        x = 3
        drawings = []
        for child in self._tabs:
            text = self._texts.get(child, "")
            lock = self._locks.get(child, "unlocked")
            selected = child is self._selected
            padding = 20 if right_skirt else 28
            width = max(52 if right_skirt else 58, font.measure(text) + padding + (10 if selected else 0))
            key = normalize_tab_color(self._colors.get(child, "default"))
            color = self.palette["tab_default"] if key == "default" else TAB_COLORS[key][1]
            top = 0 if selected else max(4, round(height * 0.22))
            bottom = height if selected else height - 3
            corner = max(6, round(height * 0.28))
            if self._tab_style == "rounded":
                half_corner = round(corner * 0.45)
                points = (x, bottom,
                          x, top + corner,
                          x + 1, top + half_corner,
                          x + half_corner, top + 1,
                          x + corner, top,
                          x + width - corner, top,
                          x + width - half_corner, top + 1,
                          x + width - 1, top + half_corner,
                          x + width, top + corner,
                          x + width, bottom)
                smooth, inset = False, corner
            elif self._tab_style == "right_skirt":
                tail = max(9, round(height * 0.32))
                skirt_height = max(12, round(height * 0.42))
                points = (x, bottom, x, top,
                          x + width - 5, top, x + width, top + 5,
                          x + width, bottom - skirt_height,
                          x + width + 1, bottom - 8,
                          x + width + 4, bottom - 4,
                          x + width + tail, bottom)
                smooth, inset = False, 5
            else:
                points = (x, bottom, x, top, x + width, top, x + width, bottom)
                smooth, inset = False, 4
            text_color = self.palette["tab_text"] if key == "default" else "#10202c"
            drawings.append((selected, points, color, text, text_color, x, width, top,
                             child, lock, inset, smooth))
            self._hitboxes.append((x, x + width, child))
            x += width - overlap
        # Paint the selected polygon last so its edges sit in front of
        # both neighbours instead of being covered by the tab to its right.
        for selected, points, color, text, text_color, left, width, top, child, lock, tab_inset, smooth in sorted(
                drawings, key=lambda item: item[0]):
            self.bar.create_polygon(points, fill=color,
                                    outline=self.palette["text"] if selected else self.palette["border"],
                                    width=3 if selected else 1, smooth=smooth, splinesteps=18)
            lock_segment = lock_indicator_segment(lock, left, width, top, height,
                                                  tab_inset, self._tab_style)
            if lock_segment is not None:
                self.bar.create_line(*lock_segment, fill=contrasting_edge_color(color),
                                     width=max(5, round(height * 0.15)), capstyle="round")
            if selected:
                self.bar.create_line(left + 2, height - 2, left + width - 2, height - 2,
                                     fill=color, width=4)
            self.bar.create_text(left + width / 2, (top + height) / 2 + 1, text=text, font=font,
                                 fill=text_color)
        if self._drop_position is not None:
            if not self._hitboxes or self._drop_position <= 0:
                marker_x = self._hitboxes[0][0] if self._hitboxes else 3
            elif self._drop_position >= len(self._hitboxes):
                marker_x = self._hitboxes[-1][1]
            else:
                marker_x = self._hitboxes[self._drop_position][0]
            self.bar.create_line(marker_x, 2, marker_x, height - 2,
                                 fill="#0067c0", width=max(3, round(height * 0.11)))
        self.bar.configure(scrollregion=(0, 0, max(x + overlap, self.bar.winfo_width()), height))

    def _at(self, x):
        if self._selected is not None:
            for left, right, child in self._hitboxes:
                if child is self._selected and left <= x <= right:
                    return child
        for left, right, child in reversed(self._hitboxes):
            if left <= x <= right:
                return child
        return None

    def _tab_press(self, event):
        child = self._at(event.x)
        if child is not None:
            self.select(child)
            self._drag_tab = child
            self._drag_start_x = event.x
            self._drag_original_order = tuple(self._tabs)
            self._drag_moved = False
            self._drag_external = False

    def _tab_motion(self, event):
        child = self._drag_tab
        if child is None:
            return
        if not self._drag_moved and abs(event.x - self._drag_start_x) < 5:
            return
        self._drag_moved = True
        x_root, y_root = self._event_root(event)
        synthetic_local = not hasattr(event, "x_root") or not hasattr(event, "y_root")
        own_bar = synthetic_local or self.insertion_index_at(x_root, y_root) is not None
        if not own_bar:
            self._drag_external = True
            accepted = self.on_tab_drag("motion", self, child, event)
            self.bar.configure(cursor="hand2" if accepted else "fleur")
            return
        if self._drag_external:
            self.on_tab_drag("cancel", self, child, event)
            self._tabs[:] = [tab for tab in self._drag_original_order if tab in self._tabs]
            self._draw()
            self._drag_external = False
        self.bar.configure(cursor="fleur")
        insertion = 0
        for left, right, _candidate in self._hitboxes:
            if event.x > (left + right) / 2:
                insertion += 1
        current = self._tabs.index(child)
        if insertion > current:
            insertion -= 1
        self.reorder(child, insertion, notify=False)

    def _tab_release(self, event):
        if self._drag_tab is None:
            return
        child = self._drag_tab
        x_root, y_root = self._event_root(event)
        synthetic_local = not hasattr(event, "x_root") or not hasattr(event, "y_root")
        external = self._drag_external or (not synthetic_local and
                                            self.insertion_index_at(x_root, y_root) is None)
        if external:
            self._tabs[:] = [tab for tab in self._drag_original_order if tab in self._tabs]
            self._draw()
            self.on_tab_drag("drop", self, child, event)
        changed = self._drag_moved and tuple(self._tabs) != self._drag_original_order
        self._drag_tab = None
        self._drag_original_order = ()
        self._drag_moved = False
        self._drag_external = False
        self.bar.configure(cursor="")
        if changed and not external:
            self.on_tabs_reordered()
            self.event_generate("<<NotebookTabsReordered>>")

    def _popup(self, event):
        child = self._at(event.x)
        if child is None:
            return
        self.select(child)
        menu = tk.Menu(self, tearoff=False, font=tkfont.nametofont("TkMenuFont"))
        for key, (label, _color) in TAB_COLORS.items():
            menu.add_command(label=tr(label), command=lambda value=key: self.set_color(child, value))
        menu.add_separator()
        lock_mode = tk.StringVar(value=self._locks.get(child, "unlocked"))
        for label, value in (("Unlocked", "unlocked"),
                             ("Lock (open folder in new tab)", "locked"),
                             ("Lock (open folder is allowed)", "reset")):
            add_scaled_radiobutton(menu, tr(label), value, lock_mode,
                                   command=lambda mode=value: self.set_lock(child, mode))
        menu.tk_popup(event.x_root, event.y_root)


import tkinter as tk
from tkinter import ttk


BUTTON_HELP = {
    "↑": "Go to the parent folder.", "⌂": "Go to your home folder.",
    "F2 Rename": "Rename the selected item.", "F3 Preview": "Open the selected item in PFC Preview.",
    "F4 Search": "Search for files and folders below the current path.",
    "F5 Copy": "Copy selected items to the destination panel shown on F5.",
    "F6 Move": "Move selected items to the opposite panel.", "F7 New folder": "Create a folder here.",
    "F8": "Reserved for a future action.", "F9 Compare": "Compare selected files or folders.",
    "F11 Copy Path": "Copy all selected full paths as text.",
    "F12 Change Path": "Focus and select the path bar for direct paste.",
    "File <<": "Preview the previous item.", "File >>": "Preview the next item.",
    "Find Prev": "Go to the previous search match.", "Find Next": "Go to the next search match.",
    "F7 Diff <<": "Go to the previous difference.", "F8 Diff >>": "Go to the next difference.",
    "Previous": "Go to the previous item.", "Next": "Go to the next item.",
    "Files": "Open file operations.", "View": "Open display settings.", "OK": "Close this window.",
}


class ToolTip:
    def __init__(self, widget, text, delay=5000):
        self.widget, self.text, self.delay = widget, text, delay
        self.job = self.popup = None
        widget.bind("<Enter>", self._enter, add="+")
        widget.bind("<Leave>", self.hide, add="+")
        widget.bind("<Button>", self.hide, add="+")

    def _enter(self, _event=None):
        self.hide(); self.job = self.widget.after(self.delay, self.show)

    def show(self):
        self.job = None
        if not self.widget.winfo_exists(): return
        self.popup = tk.Toplevel(self.widget.winfo_toplevel())
        self.popup.overrideredirect(True); self.popup.attributes("-topmost", True)
        x, y = self.widget.winfo_pointerxy()
        self.popup.geometry(f"+{x + 14}+{y + 18}")
        owner = self.widget.winfo_toplevel()
        palette = getattr(owner, "palette", {})
        text = self.text() if callable(self.text) else self.text
        if not text:
            self.popup.destroy(); self.popup = None; return
        tk.Label(self.popup, text=text, justify="left",
                 background=palette.get("tooltip", "#fffbd6"),
                 foreground=palette.get("tooltip_text", "#18232c"),
                 relief="solid", borderwidth=1, padx=7, pady=4).pack()

    def hide(self, _event=None):
        if self.job is not None:
            try: self.widget.after_cancel(self.job)
            except tk.TclError: pass
            self.job = None
        if self.popup is not None:
            try: self.popup.destroy()
            except tk.TclError: pass
            self.popup = None


class TreeItemToolTip:
    """Shows delayed text for the Treeview row currently under the pointer."""

    def __init__(self, tree, text_for_item, delay=3000):
        self.tree, self.text_for_item, self.delay = tree, text_for_item, delay
        self.job = self.popup = None
        self.item = ""
        tree.bind("<Motion>", self._motion, add="+")
        tree.bind("<Leave>", self.hide, add="+")
        tree.bind("<Button>", self.hide, add="+")

    def _motion(self, event):
        item = self.tree.identify_row(event.y)
        if item == self.item:
            return
        self.hide(); self.item = item
        if item and self.text_for_item(item):
            self.job = self.tree.after(self.delay, self.show)

    def show(self):
        self.job = None
        text = self.text_for_item(self.item) if self.item else ""
        if not text or not self.tree.winfo_exists():
            return
        self.popup = tk.Toplevel(self.tree.winfo_toplevel())
        self.popup.overrideredirect(True); self.popup.attributes("-topmost", True)
        x, y = self.tree.winfo_pointerxy()
        self.popup.geometry(f"+{x + 14}+{y + 18}")
        owner = self.tree.winfo_toplevel()
        palette = getattr(owner, "palette", {})
        tk.Label(self.popup, text=text, justify="left", wraplength=900,
                 background=palette.get("tooltip", "#fffbd6"),
                 foreground=palette.get("tooltip_text", "#18232c"),
                 relief="solid", borderwidth=1, padx=7, pady=4).pack()

    def hide(self, _event=None):
        if self.job is not None:
            try: self.tree.after_cancel(self.job)
            except tk.TclError: pass
            self.job = None
        if self.popup is not None:
            try: self.popup.destroy()
            except tk.TclError: pass
            self.popup = None
        self.item = ""


class MenuToolTip:
    def __init__(self, menu, descriptions, delay=5000):
        self.menu, self.descriptions, self.delay = menu, descriptions, delay
        self.job = self.popup = self.last_index = None
        menu.bind("<<MenuSelect>>", self._selected, add="+")
        menu.bind("<Unmap>", self.hide, add="+")

    def _selected(self, _event=None):
        try: index = self.menu.index("active")
        except tk.TclError: index = None
        if index == self.last_index: return
        self.hide(); self.last_index = index
        if index is not None and self.menu.type(index) != "separator":
            self.job = self.menu.after(self.delay, lambda: self.show(index))

    def show(self, index):
        self.job = None
        try: label = self.menu.entrycget(index, "label")
        except tk.TclError: return
        text = self.descriptions.get(label, label.replace("\t", " — "))
        self.popup = tk.Toplevel(self.menu.winfo_toplevel())
        self.popup.overrideredirect(True); self.popup.attributes("-topmost", True)
        x, y = self.menu.winfo_pointerxy(); self.popup.geometry(f"+{x + 14}+{y + 18}")
        owner = self.menu.winfo_toplevel()
        palette = getattr(owner, "palette", {})
        tk.Label(self.popup, text=text, justify="left",
                 background=palette.get("tooltip", "#fffbd6"),
                 foreground=palette.get("tooltip_text", "#18232c"),
                 relief="solid", borderwidth=1, padx=7, pady=4).pack()

    def hide(self, _event=None):
        if self.job is not None:
            try: self.menu.after_cancel(self.job)
            except tk.TclError: pass
            self.job = None
        if self.popup is not None:
            try: self.popup.destroy()
            except tk.TclError: pass
            self.popup = None


def install_button_tooltips(root) -> None:
    for widget in root.winfo_children():
        if isinstance(widget, (ttk.Button, tk.Button, tk.Menubutton)) and not hasattr(widget, "_pfc_tooltip"):
            text = str(widget.cget("text"))
            widget._pfc_tooltip = ToolTip(widget, BUTTON_HELP.get(text, f"Activate {text}."))
        install_button_tooltips(widget)


import csv
import difflib
import fnmatch
import hashlib
import os
import queue
import subprocess
import tempfile
import threading
import unicodedata
from datetime import datetime
from pathlib import Path
import tkinter as tk
from tkinter import font as tkfont, messagebox, ttk



TEXT_SUFFIXES = {".txt", ".md", ".py", ".json", ".xml", ".html", ".htm", ".css", ".js",
                 ".ini", ".cfg", ".log", ".yaml", ".yml", ".sql", ".bat", ".ps1", ".c", ".h",
                 ".cpp", ".hpp", ".java", ".csv", ".tsv"}
TABLE_SUFFIXES = {".csv", ".tsv"}
ARCHIVE_SUFFIXES = {".zip", ".7z"}


def is_compare_archive(path: Path) -> bool:
    return path.is_file() and path.suffix.casefold() in ARCHIVE_SUFFIXES


def is_compare_container(path: Path) -> bool:
    return path.is_dir() or is_compare_archive(path)


def nested_source_label(source: Path, relative: str) -> str:
    """Present extracted archive members using their logical source path."""
    relative = str(relative).strip("/\\")
    if not relative:
        return str(source)
    separator = " :: " if source.suffix.casefold() in ARCHIVE_SUFFIXES else os.sep
    return f"{source}{separator}{relative}"


def extract_compare_archive(path: Path):
    """Extract ZIP/7z into an isolated temporary folder for read-only comparison."""
    workspace = tempfile.TemporaryDirectory(prefix="pfc-compare-")
    destination = Path(workspace.name)
    try:
        extract_archive_to(path, destination)
        return workspace, destination
    except Exception:
        workspace.cleanup()
        raise


def detect_compare_type(left: Path, right: Path) -> str:
    if is_compare_container(left) and is_compare_container(right):
        return "Folder"
    if left.suffix.casefold() in TABLE_SUFFIXES and right.suffix.casefold() in TABLE_SUFFIXES:
        return "Table"
    if left.suffix.casefold() in TEXT_SUFFIXES or right.suffix.casefold() in TEXT_SUFFIXES:
        return "Text"
    try:
        for path in (left, right):
            sample = path.read_bytes()[:4096]
            if b"\0" in sample:
                return "Binary"
            sample.decode("utf-8")
        return "Text"
    except (OSError, UnicodeDecodeError):
        return "Binary"


def file_hash(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def text_files_equivalent(left: Path, right: Path) -> bool:
    """Compare visible text while ignoring non-printing representation details.

    This intentionally ignores BOMs, CRLF/LF choice, Unicode composition,
    zero-width/control characters, trailing spaces, and the final newline.  It
    does not ignore words, punctuation, indentation, or internal whitespace.
    """
    if left.suffix.casefold() not in TEXT_SUFFIXES or right.suffix.casefold() not in TEXT_SUFFIXES:
        return False
    try:
        if max(left.stat().st_size, right.stat().st_size) > 64 * 1024 * 1024:
            return False

        def normalized(path: Path) -> tuple[str, ...]:
            data = path.read_bytes()
            if data.startswith((b"\xff\xfe", b"\xfe\xff")):
                text = data.decode("utf-16")
            else:
                text = data.decode("utf-8-sig")
            text = unicodedata.normalize("NFC", text).replace("\u00a0", " ")
            text = "".join(character for character in text
                           if character in {"\n", "\r", "\t"} or
                           unicodedata.category(character) not in {"Cc", "Cf"})
            return tuple(line.rstrip(" \t") for line in text.splitlines())

        return normalized(left) == normalized(right)
    except (OSError, UnicodeDecodeError):
        return False


def aligned_text(left: str, right: str) -> tuple[list[tuple[int | None, str, int | None, str]], list[int]]:
    a, b = left.splitlines(), right.splitlines()
    rows: list[tuple[int | None, str, int | None, str]] = []
    differences: list[int] = []
    matcher = difflib.SequenceMatcher(None, a, b, autojunk=False)
    for tag, a0, a1, b0, b1 in matcher.get_opcodes():
        length = max(a1 - a0, b1 - b0)
        for offset in range(length):
            has_left, has_right = a0 + offset < a1, b0 + offset < b1
            rows.append((a0 + offset + 1 if has_left else None, a[a0 + offset] if has_left else "",
                         b0 + offset + 1 if has_right else None, b[b0 + offset] if has_right else ""))
            if tag != "equal":
                differences.append(len(rows))
    return rows, differences


def compare_row_height(linespace: int, scale: float) -> int:
    """Keep compare rows readable at every PFC font scale."""
    return max(24, int(linespace) + max(8, round(6 * scale)))


class DifferenceMap(tk.Canvas):
    """Compact overview of differences; clicking a marker jumps to that row."""
    def __init__(self, master, command):
        super().__init__(master, width=38, background="#dce6ed", highlightthickness=1,
                         highlightbackground="#50697b", cursor="hand2", takefocus=True)
        self.command = command
        self.rows, self.total_rows, self.current_row = [], 1, None
        self.viewport = (0.0, 1.0)
        self.bind("<Configure>", lambda _event: self.redraw())
        self.bind("<Button-1>", self._click)
        self.palette = color_scheme("light")

    def apply_color_scheme(self, palette):
        self.palette = palette
        self.configure(background=palette["gutter"], highlightbackground=palette["border"])
        self.redraw()

    def set_rows(self, rows, total_rows, current_row=None):
        self.rows = list(rows)
        self.total_rows = max(1, int(total_rows))
        self.current_row = current_row
        self.redraw()

    def set_current(self, row):
        self.current_row = row
        self.redraw()

    def apply_scale(self, scale):
        self.configure(width=max(38, round(38 * scale)))

    def set_viewport(self, first, last):
        self.viewport = (max(0.0, float(first)), min(1.0, float(last)))
        self.redraw()

    def _y(self, row):
        height = max(8, self.winfo_height())
        return 3 + ((max(1, row) - 1) / max(1, self.total_rows - 1)) * (height - 6)

    def redraw(self):
        self.delete("all")
        width, height = max(8, self.winfo_width()), max(8, self.winfo_height())
        self.create_rectangle(3, 3, width - 4, height - 4,
                              fill=self.palette["content"], outline=self.palette["border"])
        marker_width = max(2, width - 9)
        blocks = []
        for row in sorted(self.rows):
            if blocks and row <= blocks[-1][1] + 1:
                blocks[-1] = (blocks[-1][0], row)
            else:
                blocks.append((row, row))
        for start, end in blocks:
            top, bottom = self._y(start), self._y(end)
            self.create_rectangle(5, top - 1, 5 + marker_width, max(top + 2, bottom + 1),
                                  fill="#e45a52", outline="")
        view_top = 3 + self.viewport[0] * (height - 6)
        view_bottom = 3 + self.viewport[1] * (height - 6)
        self.create_rectangle(2, view_top, width - 3, max(view_top + 5, view_bottom),
                              outline=self.palette["selection"], width=2)
        if self.current_row is not None:
            y = self._y(self.current_row)
            self.create_rectangle(2, y - 3, width - 3, y + 3,
                                  outline=self.palette["text"], width=2)

    def _click(self, event):
        if not self.rows:
            return "break"
        target = 1 + (event.y / max(1, self.winfo_height())) * max(1, self.total_rows - 1)
        self.command(min(self.rows, key=lambda row: abs(row - target)))
        return "break"


class SideBySideText(ttk.Frame):
    def __init__(self, master, left_lines, right_lines, differences, status_text="", status_factory=None,
                 left_title="", right_title="", marker_position="middle", marker_changed=None):
        super().__init__(master)
        self.all_left_lines, self.all_right_lines = list(left_lines), list(right_lines)
        self.all_differences = list(differences)
        self.differences = list(differences)
        self.diff_index = -1
        self.matches, self.match_index = [], -1
        self.search_var, self.case_var = tk.StringVar(), tk.BooleanVar(value=False)
        self.view_mode_var = tk.StringVar(value="all")
        self.marker_position_var = tk.StringVar(
            value=marker_position if marker_position in {"left", "middle", "right"} else "middle")
        self.marker_changed = marker_changed
        self.left_title, self.right_title = str(left_title), str(right_title)
        toolbar = ttk.Frame(self); toolbar.pack(fill="x")
        diff_row = ttk.Frame(toolbar); diff_row.pack(fill="x")
        self.status_factory = status_factory or (lambda: status_text)
        self.previous_button = ttk.Button(diff_row, text=f"F7 {tr('Diff <<')}", command=self.previous)
        self.previous_button.pack(side="left")
        self.next_button = ttk.Button(diff_row, text=f"F8 {tr('Diff >>')}", command=self.next)
        self.next_button.pack(side="left", padx=3)
        self.view_button = ttk.Menubutton(diff_row)
        self.view_menu = tk.Menu(self.view_button, tearoff=False)
        self.view_button.configure(menu=self.view_menu)
        self.view_button.pack(side="left", padx=(8, 0))
        self._build_view_menu()
        self.diff_status = ttk.Label(diff_row, text=self.status_factory())
        self.diff_status.pack(side="left", padx=10)
        self.marker_button = ttk.Menubutton(diff_row)
        self.marker_menu = tk.Menu(self.marker_button, tearoff=False)
        self.marker_button.configure(menu=self.marker_menu)
        self.marker_button.pack(side="right")
        self._build_marker_menu(); self._update_marker_button()
        find_row = ttk.Frame(toolbar); find_row.pack(fill="x", pady=(3, 2))
        ttk.Label(find_row, text=tr("Find:")).pack(side="left")
        self.search = ttk.Entry(find_row, textvariable=self.search_var)
        self.search.pack(side="left", fill="x", expand=True, padx=(3, 4))
        self.search.bind("<Return>", lambda _event: self.find_next())
        self.search.bind("<Shift-Return>", lambda _event: self.find_previous())
        ttk.Button(find_row, text=tr("Find Prev"), command=self.find_previous).pack(side="left")
        ttk.Button(find_row, text=tr("Find Next"), command=self.find_next).pack(side="left", padx=(3, 0))
        self.case_button = ttk.Button(find_row, command=self._toggle_case)
        self.case_button.pack(side="left", padx=(8, 0))
        self.find_status = ttk.Label(find_row, width=12, anchor="e")
        self.find_status.pack(side="right", padx=(8, 3))
        self._update_case_button()
        body = ttk.Frame(self); self.body = body
        body.pack(fill="both", expand=True, pady=(3, 0))
        body.rowconfigure(1, weight=1)
        self.left_frame = tk.Frame(body, background="#f5f8fa", highlightthickness=2,
                                   highlightbackground="#2d668f")
        self.right_frame = tk.Frame(body, background="#f5f8fa", highlightthickness=2,
                                    highlightbackground="#9b5d2e")
        self.left_frame.columnconfigure(1, weight=1); self.left_frame.rowconfigure(0, weight=1)
        self.right_frame.columnconfigure(1, weight=1); self.right_frame.rowconfigure(0, weight=1)
        self.left_path_label = tk.Label(body, anchor="w", background="#2d668f",
                                        foreground="white", font="TkHeadingFont", padx=6, pady=3)
        self.right_path_label = tk.Label(body, anchor="w", background="#9b5d2e",
                                         foreground="white", font="TkHeadingFont", padx=6, pady=3)
        self.left_path_label.configure(text=f"{tr('Left')}: {self.left_title}")
        self.right_path_label.configure(text=f"{tr('Right')}: {self.right_title}")
        self.map_header = tk.Label(body, text="↔", background="#263d4c", foreground="white",
                                   font="TkHeadingFont", pady=3)
        self.left = tk.Text(self.left_frame, wrap="none", undo=False, borderwidth=0)
        self.right = tk.Text(self.right_frame, wrap="none", undo=False, borderwidth=0)
        self.left_numbers = tk.Text(self.left_frame, width=6, wrap="none", undo=False, borderwidth=0,
                                    padx=4, takefocus=False, background="#e5ebef", foreground="#526575")
        self.right_numbers = tk.Text(self.right_frame, width=6, wrap="none", undo=False, borderwidth=0,
                                     padx=4, takefocus=False, background="#e5ebef", foreground="#526575")
        self.left_numbers.grid(row=0, column=0, sticky="ns")
        self.right_numbers.grid(row=0, column=0, sticky="ns")
        self.left.grid(row=0, column=1, sticky="nsew"); self.right.grid(row=0, column=1, sticky="nsew")
        left_x = ttk.Scrollbar(self.left_frame, orient="horizontal", command=self.left.xview)
        right_x = ttk.Scrollbar(self.right_frame, orient="horizontal", command=self.right.xview)
        left_x.grid(row=1, column=1, sticky="ew"); right_x.grid(row=1, column=1, sticky="ew")
        self.left.configure(xscrollcommand=left_x.set); self.right.configure(xscrollcommand=right_x.set)
        self.difference_map = DifferenceMap(body, self._jump_to_row)
        self.scroll = ttk.Scrollbar(body, orient="vertical", command=self._scroll)
        self.left.configure(yscrollcommand=self._left_scrolled)
        self.right.configure(yscrollcommand=self._right_scrolled)
        for widget in (self.left, self.right):
            widget.tag_configure("diff", background="#ffe1a8")
            widget.tag_configure("current", background="#ffb347")
            widget.tag_configure("match", background="#fff0a6")
            widget.tag_configure("current_match", background="#ff9f43")
            widget.bind("<MouseWheel>", self._mousewheel)
            widget.bind("<Button-4>", lambda _event: self._wheel_units(-3))
            widget.bind("<Button-5>", lambda _event: self._wheel_units(3))
        for widget in (self.left_numbers, self.right_numbers):
            widget.tag_configure("diff", background="#f2c08d", foreground="#35434d")
            widget.tag_configure("current", background="#e8843b", foreground="white")
            widget.bind("<MouseWheel>", self._mousewheel)
            widget.bind("<Button-4>", lambda _event: self._wheel_units(-3))
            widget.bind("<Button-5>", lambda _event: self._wheel_units(3))
        self._layout_marker()
        self.apply_color_scheme(getattr(master.winfo_toplevel(), "palette", color_scheme("light")))
        self.populate()

    def apply_color_scheme(self, palette):
        menu_options = {
            "background": palette["content"], "foreground": palette["text"],
            "activebackground": palette["selection"], "activeforeground": "#ffffff",
        }
        self.view_menu.configure(**menu_options); self.marker_menu.configure(**menu_options)
        self.left_frame.configure(background=palette["content"],
                                  highlightbackground=palette["left_header"])
        self.right_frame.configure(background=palette["content"],
                                   highlightbackground=palette["right_header"])
        self.left_path_label.configure(background=palette["left_header"], foreground="#ffffff")
        self.right_path_label.configure(background=palette["right_header"], foreground="#ffffff")
        self.map_header.configure(background=palette["map_header"], foreground="#ffffff")
        for widget in (self.left, self.right):
            widget.configure(background=palette["content"], foreground=palette["text"],
                             insertbackground=palette["text"],
                             selectbackground=palette["selection"], selectforeground="#ffffff")
            widget.tag_configure("diff", background=palette["diff"], foreground=palette["text"])
            widget.tag_configure("current", background=palette["current_diff"], foreground="#ffffff")
            widget.tag_configure("match", background=palette["match"], foreground=palette["text"])
            widget.tag_configure("current_match", background=palette["current_diff"], foreground="#ffffff")
        for widget in (self.left_numbers, self.right_numbers):
            widget.configure(background=palette["gutter"], foreground=palette["gutter_text"],
                             selectbackground=palette["selection"], selectforeground="#ffffff")
            widget.tag_configure("diff", background=palette["diff"], foreground=palette["gutter_text"])
            widget.tag_configure("current", background=palette["current_diff"], foreground="#ffffff")
        self.difference_map.apply_color_scheme(palette)

    def populate(self):
        only_differences = self.view_mode_var.get() == "differences"
        visible_rows = (self.all_differences if only_differences else
                        list(range(1, len(self.all_left_lines) + 1)))
        self.differences = (list(range(1, len(visible_rows) + 1)) if only_differences else
                            list(self.all_differences))
        self.diff_index = -1
        for widget, number_widget, lines in (
                (self.left, self.left_numbers, self.all_left_lines),
                (self.right, self.right_numbers, self.all_right_lines)):
            widget.configure(state="normal"); widget.delete("1.0", "end")
            number_widget.configure(state="normal"); number_widget.delete("1.0", "end")
            for output_row, source_row in enumerate(visible_rows, 1):
                item = lines[source_row - 1]
                source_number, line = item if isinstance(item, tuple) else (source_row, item)
                number_text = "" if source_number is None else str(source_number)
                tag = "diff" if output_row in self.differences else ""
                number_widget.insert("end", f"{number_text:>5}\n", tag)
                widget.insert("end", f" {line}\n", tag)
            widget.configure(state="disabled"); number_widget.configure(state="disabled")
        self.difference_map.set_rows(self.differences, len(visible_rows))
        self._build_view_menu()
        self.find_all()

    def _select_view_mode(self, value):
        self.view_mode_var.set(value); self.populate()

    def _build_view_menu(self):
        self.view_menu.delete(0, "end")
        selected = self.view_mode_var.get()
        for value, label in (("all", "All"), ("differences", "Differences only")):
            prefix = "● " if value == selected else "   "
            self.view_menu.add_command(label=prefix + tr(label),
                                       command=lambda mode=value: self._select_view_mode(mode))
        label = "All" if selected == "all" else "Differences only"
        self.view_button.configure(text=tr(label))

    def _build_marker_menu(self):
        self.marker_menu.delete(0, "end")
        selected = self.marker_position_var.get()
        for value, label in (("left", "Left"), ("middle", "Middle"), ("right", "Right")):
            prefix = "● " if value == selected else "   "
            self.marker_menu.add_command(label=prefix + tr(label),
                                         command=lambda position=value:
                                         self.set_marker_position(position, notify=True))

    def _update_marker_button(self):
        labels = {"left": "Left", "middle": "Middle", "right": "Right"}
        self.marker_button.configure(
            text=f"{tr('Map:')} {tr(labels.get(self.marker_position_var.get(), 'Middle'))}")

    def _toggle_case(self):
        self.case_var.set(not self.case_var.get()); self._update_case_button(); self.find_all()
        return "break"

    def _update_case_button(self):
        self.case_button.configure(
            text=f"{'✓' if self.case_var.get() else '–'} {tr('Case sensitive')}")

    def apply_scale(self, scale: float) -> None:
        self.difference_map.apply_scale(scale)
        padding = max(3, round(3 * scale))
        self.left_path_label.configure(padx=padding * 2, pady=padding)
        self.right_path_label.configure(padx=padding * 2, pady=padding)

    def set_marker_position(self, position: str, notify: bool = False) -> None:
        if position not in {"left", "middle", "right"}:
            position = "middle"
        self.marker_position_var.set(position)
        self._layout_marker()
        self._build_marker_menu(); self._update_marker_button()
        if notify and self.marker_changed is not None:
            self.marker_changed(position)

    def _marker_position_changed(self) -> None:
        self.set_marker_position(self.marker_position_var.get(), notify=True)

    def _layout_marker(self) -> None:
        for column in range(4):
            self.body.columnconfigure(column, weight=0, uniform="")
        position = self.marker_position_var.get()
        if position == "left":
            map_column, left_column, right_column = 0, 1, 2
        elif position == "right":
            left_column, right_column, map_column = 0, 1, 2
        else:
            left_column, map_column, right_column = 0, 1, 2
        for column in (left_column, right_column):
            self.body.columnconfigure(column, weight=1, uniform="compare")
        self.left_path_label.grid(row=0, column=left_column, sticky="ew")
        self.left_frame.grid(row=1, column=left_column, sticky="nsew")
        self.right_path_label.grid(row=0, column=right_column, sticky="ew")
        self.right_frame.grid(row=1, column=right_column, sticky="nsew")
        self.map_header.grid(row=0, column=map_column, sticky="ew", padx=4)
        self.difference_map.grid(row=1, column=map_column, sticky="ns", padx=4)
        self.scroll.grid(row=1, column=3, sticky="ns")

    def apply_language(self, old_language: str) -> None:
        retranslate_widgets(self, old_language)
        self.left_path_label.configure(text=f"{tr('Left')}: {self.left_title}")
        self.right_path_label.configure(text=f"{tr('Right')}: {self.right_title}")
        self.previous_button.configure(text=f"F7 {tr('Diff <<')}")
        self.next_button.configure(text=f"F8 {tr('Diff >>')}")
        self.diff_status.configure(text=self.status_factory())
        self._build_view_menu(); self._build_marker_menu(); self._update_marker_button()
        self._update_case_button()
        self.find_all()

    def focus_search(self):
        self.search.focus_set(); self.search.selection_range(0, "end"); return "break"

    def find_all(self):
        self.matches, self.match_index = [], -1
        needle = self.search_var.get()
        for widget in (self.left, self.right):
            widget.tag_remove("match", "1.0", "end"); widget.tag_remove("current_match", "1.0", "end")
            if not needle: continue
            start = "1.0"
            while True:
                found = widget.search(needle, start, stopindex="end", nocase=not self.case_var.get())
                if not found: break
                end = f"{found}+{len(needle)}c"
                self.matches.append((widget, found, end)); widget.tag_add("match", found, end); start = end
        self.find_status.configure(text=tr("{count} match(es)", count=len(self.matches)) if needle else "")

    def _find(self, direction):
        previous = self.match_index; self.find_all()
        if not self.matches: return "break"
        self.match_index = (previous + direction) % len(self.matches)
        for widget in (self.left, self.right): widget.tag_remove("current_match", "1.0", "end")
        widget, start, end = self.matches[self.match_index]
        widget.tag_add("current_match", start, end); widget.see(start)
        other = self.right if widget is self.left else self.left; other.yview_moveto(widget.yview()[0])
        self.find_status.configure(text=f"{self.match_index + 1}/{len(self.matches)}")
        return "break"

    def find_next(self): return self._find(1)
    def find_previous(self): return self._find(-1)

    def _scroll(self, *args):
        for widget in (self.left, self.left_numbers, self.right, self.right_numbers):
            widget.yview(*args)

    def _left_scrolled(self, first, last):
        self.scroll.set(first, last)
        self.difference_map.set_viewport(first, last)
        self.left_numbers.yview_moveto(first)
        if abs(self.right.yview()[0] - float(first)) > 0.0001:
            self.right.yview_moveto(first)
        self.right_numbers.yview_moveto(first)

    def _right_scrolled(self, first, last):
        self.scroll.set(first, last)
        self.difference_map.set_viewport(first, last)
        self.right_numbers.yview_moveto(first)
        if abs(self.left.yview()[0] - float(first)) > 0.0001:
            self.left.yview_moveto(first)
        self.left_numbers.yview_moveto(first)

    def _wheel_units(self, units):
        for widget in (self.left, self.left_numbers, self.right, self.right_numbers):
            widget.yview_scroll(units, "units")
        return "break"

    def _mousewheel(self, event):
        units = -int(event.delta / 120) if event.delta else 0
        return self._wheel_units(units)

    def _jump_to_row(self, line):
        if line not in self.differences:
            return
        self.diff_index = self.differences.index(line)
        self._show()

    def next(self):
        if self.differences:
            self.diff_index = (self.diff_index + 1) % len(self.differences); self._show()

    def previous(self):
        if self.differences:
            self.diff_index = (self.diff_index - 1) % len(self.differences); self._show()

    def _show(self):
        line = self.differences[self.diff_index]
        for widget in (self.left, self.left_numbers, self.right, self.right_numbers):
            widget.see(f"{line}.0")
            widget.tag_remove("current", "1.0", "end")
            widget.tag_add("current", f"{line}.0", f"{line}.end")
        self.difference_map.set_current(line)
        self.diff_status.configure(text=f"{self.diff_index + 1}/{len(self.differences)}")


class TextCompare(ttk.Frame):
    def __init__(self, master, left: Path, right: Path, marker_position="middle", marker_changed=None,
                 left_title=None, right_title=None):
        super().__init__(master)
        a = left.read_text(encoding="utf-8", errors="replace")
        b = right.read_text(encoding="utf-8", errors="replace")
        rows, differences = aligned_text(a, b)
        self.view = SideBySideText(
            self, [(row[0], row[1]) for row in rows], [(row[2], row[3]) for row in rows], differences,
            status_factory=lambda count=len(differences): tr("{count} different line(s)", count=count),
            left_title=left_title or left, right_title=right_title or right,
            marker_position=marker_position,
            marker_changed=marker_changed)
        self.view.pack(fill="both", expand=True)

    def apply_language(self, old_language: str) -> None:
        self.view.apply_language(old_language)

    def apply_scale(self, scale: float) -> None:
        self.view.apply_scale(scale)


class BinaryCompare(ttk.Frame):
    LIMIT = 256 * 1024

    def __init__(self, master, left: Path, right: Path, marker_position="middle", marker_changed=None,
                 left_title=None, right_title=None):
        super().__init__(master)
        a, b = left.read_bytes()[:self.LIMIT], right.read_bytes()[:self.LIMIT]
        length = max(len(a), len(b)); different_offsets = []
        left_lines, right_lines, diff_lines = [], [], []
        for offset in range(0, length, 16):
            ca, cb = a[offset:offset + 16], b[offset:offset + 16]
            if ca != cb:
                different_offsets.extend(offset + index for index in range(max(len(ca), len(cb)))
                                         if (ca[index:index + 1] != cb[index:index + 1]))
                diff_lines.append(len(left_lines) + 1)
            def render(chunk):
                hexdump = " ".join(f"{byte:02X}" for byte in chunk)
                text = "".join(chr(byte) if 32 <= byte < 127 else "." for byte in chunk)
                return f"{offset:08X}  {hexdump:<47}  {text}"
            left_lines.append(render(ca)); right_lines.append(render(cb))
        identical = file_hash(left) == file_hash(right)
        first_offset = f"0x{different_offsets[0]:X}" if different_offsets else None
        status_factory = lambda: tr(
            "SHA-256: {result}; first offset: {offset}",
            result=tr("identical") if identical else tr("different"),
            offset=first_offset or tr("none"))
        self.view = SideBySideText(self, left_lines, right_lines, diff_lines,
                                   status_factory=status_factory,
                                   left_title=left_title or left, right_title=right_title or right,
                                   marker_position=marker_position, marker_changed=marker_changed)
        self.view.pack(fill="both", expand=True)

    def apply_language(self, old_language: str) -> None:
        self.view.apply_language(old_language)

    def apply_scale(self, scale: float) -> None:
        self.view.apply_scale(scale)


def folder_rows(left: Path, right: Path, recursive=True, masks="*", by_content=False,
                ignore_invisible_text=False, cancelled=lambda: False):
    patterns = [item.strip() for item in masks.split(";") if item.strip()] or ["*"]
    def collect(root):
        if recursive:
            def paths():
                for folder, directories, filenames in os.walk(root, topdown=True,
                                                                onerror=lambda _error: None):
                    directories[:] = [name for name in directories
                                      if name.casefold() not in {".git", ".svn"}]
                    base = Path(folder)
                    yield from (base / name for name in directories)
                    yield from (base / name for name in filenames)
            iterator = paths()
        else:
            iterator = root.iterdir()
        result = {}
        for path in iterator:
            if cancelled():
                break
            try:
                relative_path = path.relative_to(root)
            except ValueError:
                continue
            if any(part.casefold() in {".git", ".svn"} for part in relative_path.parts):
                continue
            relative = str(relative_path)
            if path.is_dir() or any(fnmatch.fnmatch(path.name.casefold(), pattern.casefold())
                                    for pattern in patterns):
                result[relative.casefold()] = path
        return result
    left_items, right_items = collect(left), collect(right)
    for key in sorted(left_items.keys() | right_items.keys()):
        if cancelled():
            return
        a, b = left_items.get(key), right_items.get(key)
        display = str((a.relative_to(left) if a else b.relative_to(right)))
        try:
            if a is None: status = "Right only"
            elif b is None: status = "Left only"
            elif a.is_dir() != b.is_dir(): status = "Type mismatch"
            elif a.is_dir(): status = "Identical"
            else:
                a_stat, b_stat = a.stat(), b.stat()
                if ignore_invisible_text and text_files_equivalent(a, b):
                    status = "Identical"
                elif a_stat.st_size != b_stat.st_size:
                    status = "Different"
                elif by_content and file_hash(a) == file_hash(b):
                    status = "Identical"
                elif by_content:
                    status = "Left newer" if a_stat.st_mtime_ns > b_stat.st_mtime_ns else (
                        "Right newer" if b_stat.st_mtime_ns > a_stat.st_mtime_ns else "Different")
                elif a_stat.st_mtime_ns == b_stat.st_mtime_ns:
                    status = "Identical"
                else:
                    status = "Left newer" if a_stat.st_mtime_ns > b_stat.st_mtime_ns else "Right newer"
        except OSError:
            status = "Unknown"
        yield status, display, a, b


class SyncPlanDialog(tk.Toplevel):
    def __init__(self, parent, plans):
        super().__init__(parent)
        self.result = False
        self.title(tr("Safe Sync — Dry Run"))
        self.geometry("1000x560"); self.minsize(680, 380); self.transient(parent)
        ttk.Label(self, text=tr("Review all {count} copy operation(s)", count=len(plans)),
                  font="TkHeadingFont", padding=(8, 8, 8, 2)).pack(anchor="w")
        ttk.Label(self, text=tr("Copy only — no files or folders will be deleted."),
                  padding=(8, 0, 8, 6)).pack(anchor="w")
        self.tree = ttk.Treeview(self, columns=("source", "destination"), show="headings")
        self.tree.heading("source", text=tr("Source")); self.tree.heading("destination", text=tr("Destination"))
        self.tree.column("source", width=470); self.tree.column("destination", width=470)
        for source, target in plans:
            self.tree.insert("", "end", values=(str(source), str(target)))
        scroll = ttk.Scrollbar(self, orient="vertical", command=self.tree.yview)
        self.tree.configure(yscrollcommand=scroll.set)
        scroll.pack(side="right", fill="y", padx=(0, 8)); self.tree.pack(fill="both", expand=True, padx=(8, 0))
        buttons = ttk.Frame(self, padding=8); buttons.pack(fill="x")
        ttk.Button(buttons, text=tr("Cancel"), command=self.cancel).pack(side="right")
        execute = ttk.Button(buttons, text=tr("Execute Copy Plan"), command=self.execute)
        execute.pack(side="right", padx=(0, 4))
        self.bind("<Escape>", lambda _event: self.cancel())
        self.bind("<Control-Return>", lambda _event: self.execute())
        self.protocol("WM_DELETE_WINDOW", self.cancel)
        self.grab_set(); self.lift(); self.focus_force(); execute.focus_set()

    def execute(self):
        self.result = True; self.destroy()

    def cancel(self):
        self.result = False; self.destroy()

    @classmethod
    def ask(cls, parent, plans):
        dialog = cls(parent, plans); parent.wait_window(dialog); return dialog.result


class _FolderCompareLogic(ttk.Frame):
    DIFF_FILTERS = {
        "all": None,
        "differences": {"Different", "Type mismatch", "Unknown", "Left newer", "Right newer",
                        "Left only", "Right only"},
        "no_orphans": {"Identical", "Different", "Type mismatch", "Unknown", "Left newer", "Right newer"},
        "differences_no_orphans": {"Different", "Type mismatch", "Unknown", "Left newer", "Right newer"},
        "orphans": {"Left only", "Right only"},
        "left_newer": {"Left newer"},
        "right_newer": {"Right newer"},
        "left_newer_orphans": {"Left newer", "Left only"},
        "right_newer_orphans": {"Right newer", "Right only"},
        "left_orphans": {"Left only"},
        "right_orphans": {"Right only"},
    }
    DIFF_LABELS = {
        "all": "Show All", "differences": "Show Differences",
        "no_orphans": "Show No Orphans",
        "differences_no_orphans": "Show Differences but No Orphans",
        "orphans": "Show Orphans", "left_newer": "Show Left Newer",
        "right_newer": "Show Right Newer",
        "left_newer_orphans": "Show Left Newer and Left Orphans",
        "right_newer_orphans": "Show Right Newer and Right Orphans",
        "left_orphans": "Show Left Orphans", "right_orphans": "Show Right Orphans",
    }

    def __init__(self, master, left: Path, right: Path, open_detail, sync_executor=None,
                 left_label=None, right_label=None, left_read_only=False, right_read_only=False):
        super().__init__(master)
        self.left_root, self.right_root = left, right
        self.left_base_root, self.right_base_root = left, right
        self.left_label = Path(left_label) if left_label is not None else left
        self.right_label = Path(right_label) if right_label is not None else right
        self.left_read_only, self.right_read_only = left_read_only, right_read_only
        self.open_detail, self.sync_executor = open_detail, sync_executor
        self.rows, self.actions, self.item_paths, self.item_keys = [], {}, {}, {}
        self._expand_state = True
        self.matches, self.match_index = [], -1
        self.difference_items, self.difference_index = [], -1
        self._scan_queue, self._cancel_event, self._scanning = queue.Queue(), threading.Event(), False
        self.sort_column, self.sort_reverse = "left_path", False
        paths = ttk.Frame(self); paths.pack(fill="x", pady=(2, 3))
        paths.columnconfigure(0, weight=1, uniform="folder-side")
        paths.columnconfigure(2, weight=1, uniform="folder-side")
        self.left_path_label = tk.Label(paths, text=f"{tr('Left')}: {self._base_label('left')}", anchor="w",
                                        background="#2d668f", foreground="white",
                                        font="TkHeadingFont", padx=6, pady=3)
        self.left_path_label.grid(row=0, column=0, sticky="ew")
        self.path_divider = tk.Label(paths, text="↔", background="#263d4c", foreground="white",
                                     font="TkHeadingFont", padx=10, pady=3)
        self.path_divider.grid(row=0, column=1, sticky="ns")
        self.right_path_label = tk.Label(paths, text=f"{tr('Right')}: {self._base_label('right')}", anchor="w",
                                         background="#9b5d2e", foreground="white",
                                         font="TkHeadingFont", padx=6, pady=3)
        self.right_path_label.grid(row=0, column=2, sticky="ew")
        bar = ttk.Frame(self); bar.pack(fill="x")
        ttk.Label(bar, text=tr("Mask:")).pack(side="left")
        self.mask_var = tk.StringVar(value="*")
        ttk.Entry(bar, textvariable=self.mask_var, width=20).pack(side="left", fill="x", expand=True, padx=(3, 8))
        ttk.Button(bar, text=tr("Compare"), command=self.start_scan).pack(side="left", padx=(0, 2))
        ttk.Button(bar, text=tr("Cancel"), command=self.cancel_scan).pack(side="left")
        options = ttk.Frame(self); options.pack(fill="x", pady=(2, 1))
        self.recursive_var = tk.BooleanVar(value=True)
        # Archive timestamps are often rounded or regenerated.  Compare archive
        # contents by bytes by default so a repacked folder is not reported as
        # different solely because of container metadata.
        self.content_var = tk.BooleanVar(value=self.left_read_only or self.right_read_only)
        self.text_equivalent_var = tk.BooleanVar(value=True)
        self.view_mode_var = tk.StringVar(value="all")
        ttk.Checkbutton(options, text=tr("Recursive"), variable=self.recursive_var).pack(side="left")
        ttk.Checkbutton(options, text=tr("By content"), variable=self.content_var).pack(side="left", padx=(5, 0))
        ttk.Checkbutton(options, text=tr("Text equivalent"),
                        variable=self.text_equivalent_var).pack(side="left", padx=(5, 0))
        self.diff_button = ttk.Menubutton(options, text=tr("All"))
        self.diff_menu = tk.Menu(self.diff_button, tearoff=False)
        self.diff_button.configure(menu=self.diff_menu)
        self.diff_button.pack(side="left", padx=(8, 0))
        self._build_diff_menu()
        folder_tools = ttk.Frame(self); folder_tools.pack(fill="x", pady=(1, 1))
        ttk.Button(folder_tools, text=tr("Expand All"), command=self.expand_all).pack(side="left")
        ttk.Button(folder_tools, text=tr("Collapse All"), command=self.collapse_all).pack(side="left", padx=(3, 0))
        ttk.Button(folder_tools, text=tr("Set Base Folder"), command=self.set_base_folder).pack(side="left", padx=(8, 0))
        ttk.Button(folder_tools, text=tr("Swap Sides"), command=self.swap_sides).pack(side="left", padx=(3, 0))
        navigation = ttk.Frame(self); navigation.pack(fill="x", pady=(1, 2))
        self.previous_button = ttk.Button(navigation, text=f"F7 {tr('Diff <<')}", command=self.previous)
        self.previous_button.pack(side="left")
        self.next_button = ttk.Button(navigation, text=f"F8 {tr('Diff >>')}", command=self.next)
        self.next_button.pack(side="left", padx=3)
        self.diff_status = ttk.Label(navigation); self.diff_status.pack(side="left", padx=5)
        self.search_var, self.case_var = tk.StringVar(), tk.BooleanVar(value=False)
        find_row = ttk.Frame(self); find_row.pack(fill="x", pady=(3, 2))
        ttk.Label(find_row, text=tr("Find:")).pack(side="left")
        self.search = ttk.Entry(find_row, textvariable=self.search_var)
        self.search.pack(side="left", fill="x", expand=True, padx=(3, 4))
        self.search.bind("<Return>", lambda _event: self.find_next())
        self.search.bind("<Shift-Return>", lambda _event: self.find_previous())
        self.find_status = ttk.Label(find_row, width=10, anchor="e"); self.find_status.pack(side="right", padx=4)
        find_actions = ttk.Frame(self); find_actions.pack(fill="x", pady=(0, 2))
        ttk.Button(find_actions, text=tr("Find Prev"), command=self.find_previous).pack(side="left")
        ttk.Button(find_actions, text=tr("Find Next"), command=self.find_next).pack(side="left", padx=(3, 0))
        ttk.Checkbutton(find_actions, text=tr("Case sensitive"), variable=self.case_var,
                        command=self.find_all).pack(side="left", padx=(8, 0))
        actions = ttk.Frame(self); actions.pack(fill="x", pady=(0, 3))
        ttk.Button(actions, text=f"Ctrl+→ {tr('Copy')} →", command=lambda: self.set_action("right")).pack(side="left")
        ttk.Button(actions, text=f"Ctrl+← ← {tr('Copy')}", command=lambda: self.set_action("left")).pack(side="left", padx=3)
        ttk.Button(actions, text=tr("Space Skip"), command=lambda: self.set_action("skip")).pack(side="left")
        sync_row = ttk.Frame(self); sync_row.pack(fill="x", pady=(0, 3))
        ttk.Button(sync_row, text=tr("Dry Run && Sync"), command=self.dry_run).pack(side="left")
        ttk.Label(sync_row, text=tr("Copy only — no automatic delete")).pack(side="left", padx=(8, 0))
        self.scan_status = ttk.Label(sync_row, text=tr("Ready"), anchor="e")
        self.scan_status.pack(side="right", fill="x", expand=True, padx=8)
        tree_area = ttk.Frame(self); tree_area.pack(fill="both", expand=True)
        tree_area.columnconfigure(0, weight=1); tree_area.rowconfigure(0, weight=1)
        self.tree = ttk.Treeview(tree_area, columns=("action", "left_path", "left_detail", "status",
                                                     "right_path", "right_detail"),
                                 show=("tree", "headings"), selectmode="extended",
                                 style="PFCCompare.Treeview")
        headings = {
            "action": tr("Action"), "left_path": tr("Left"),
            "left_detail": f"{tr('Size')} / {tr('Modified')}", "status": tr("Status"),
            "right_path": tr("Right"), "right_detail": f"{tr('Size')} / {tr('Modified')}",
        }
        self._column_widths = {"action": 65, "left_path": 300, "left_detail": 190,
                               "status": 130, "right_path": 300, "right_detail": 190}
        for col, width in self._column_widths.items():
            self.tree.heading(col, text=headings[col], command=lambda value=col: self.change_sort(value))
            self.tree.column(col, width=width, minwidth=50,
                             stretch=col in {"left_path", "right_path"},
                             anchor="center" if col in {"action", "status"} else "w")
        self.tree.heading("#0", text="")
        self.tree.column("#0", width=32, minwidth=24, stretch=False)
        self.tree.grid(row=0, column=0, sticky="nsew")
        self.tree_y_scroll = ttk.Scrollbar(tree_area, orient="vertical", command=self.tree.yview)
        self.tree_x_scroll = ttk.Scrollbar(tree_area, orient="horizontal", command=self.tree.xview)
        self.tree_y_scroll.grid(row=0, column=1, sticky="ns")
        self.tree_x_scroll.grid(row=1, column=0, sticky="ew")
        self.tree.configure(yscrollcommand=self.tree_y_scroll.set, xscrollcommand=self.tree_x_scroll.set)
        self.tree.tag_configure("find_match", background="#fff0a6")
        self.tree.tag_configure("current_match", background="#ff9f43")
        self.tree.tag_configure("different", foreground="#a00000")
        self.tree.tag_configure("left", foreground="#006c3b")
        self.tree.tag_configure("right", foreground="#005ca8")
        self.tree.tag_configure("identical", foreground="#555555")
        self.tree.bind("<Double-1>", self._open)
        self.tree.bind("<Return>", self._open)
        self.tree.bind("<Control-Right>", lambda _e: self.set_action("right"))
        self.tree.bind("<Control-Left>", lambda _e: self.set_action("left"))
        self.tree.bind("<space>", lambda _e: self.set_action("skip"))
        self.apply_scale(1.0)
        self.apply_color_scheme(getattr(master.winfo_toplevel(), "palette", color_scheme("light")))
        self.start_scan()

    def _base_label(self, side):
        root = self.left_root if side == "left" else self.right_root
        initial = self.left_base_root if side == "left" else self.right_base_root
        label = self.left_label if side == "left" else self.right_label
        try:
            relative = root.relative_to(initial)
        except ValueError:
            relative = Path()
        if relative == Path("."):
            return str(label)
        separator = " :: " if is_compare_archive(label) else os.sep
        return f"{label}{separator}{relative}"

    def _build_diff_menu(self):
        self.diff_menu.delete(0, "end")
        for key in self.DIFF_FILTERS:
            self.diff_menu.add_radiobutton(label=tr(self.DIFF_LABELS[key]), value=key,
                                           variable=self.view_mode_var,
                                           command=self._set_diff_filter)
        self._update_diff_button()

    def _update_diff_button(self):
        key = self.view_mode_var.get()
        self.diff_button.configure(text=f"{tr('Diffs')}: {tr(self.DIFF_LABELS.get(key, 'Show All'))}")

    def _set_diff_filter(self):
        self._update_diff_button()
        self.populate()

    def expand_all(self):
        self._expand_state = True
        for iid in self.tree.get_children(""):
            self._set_open_recursive(iid, True)
        return "break"

    def collapse_all(self):
        self._expand_state = False
        for iid in self.tree.get_children(""):
            self._set_open_recursive(iid, False)
        return "break"

    def _set_open_recursive(self, iid, opened):
        self.tree.item(iid, open=opened)
        for child in self.tree.get_children(iid):
            self._set_open_recursive(child, opened)

    def _all_tree_items(self, parent=""):
        for iid in self.tree.get_children(parent):
            yield iid
            yield from self._all_tree_items(iid)

    def set_base_folder(self):
        selected = self.tree.selection()
        if not selected:
            messagebox.showinfo(tr("Set Base Folder"), tr("Select a folder row first."), parent=self)
            return "break"
        left, right = self.item_paths.get(selected[0], (None, None))
        changed = False
        if left is not None and left.is_dir():
            self.left_root = left; changed = True
        if right is not None and right.is_dir():
            self.right_root = right; changed = True
        if not changed:
            messagebox.showinfo(tr("Set Base Folder"), tr("The selected row is not a folder."), parent=self)
            return "break"
        self._update_path_labels()
        self.start_scan()
        return "break"

    def swap_sides(self):
        if self._scanning:
            self.cancel_scan()
        self.left_root, self.right_root = self.right_root, self.left_root
        self.left_base_root, self.right_base_root = self.right_base_root, self.left_base_root
        self.left_label, self.right_label = self.right_label, self.left_label
        self.left_read_only, self.right_read_only = self.right_read_only, self.left_read_only
        self.actions = {}
        self._update_path_labels()
        self.start_scan()
        return "break"

    def _update_path_labels(self):
        self.left_path_label.configure(text=f"{tr('Left')}: {self._base_label('left')}")
        self.right_path_label.configure(text=f"{tr('Right')}: {self._base_label('right')}")

    def apply_color_scheme(self, palette):
        self.left_path_label.configure(background=palette["left_header"], foreground="#ffffff")
        self.right_path_label.configure(background=palette["right_header"], foreground="#ffffff")
        self.path_divider.configure(background=palette["map_header"], foreground="#ffffff")
        self.tree.tag_configure("find_match", background=palette["match"], foreground=palette["text"])
        self.tree.tag_configure("current_match", background=palette["current_diff"], foreground="#ffffff")
        self.tree.tag_configure("different", foreground="#ff7770" if palette["window"] == "#20262c" else "#a00000")
        self.tree.tag_configure("left", foreground="#73d6a1" if palette["window"] == "#20262c" else "#006c3b")
        self.tree.tag_configure("right", foreground="#73bfff" if palette["window"] == "#20262c" else "#005ca8")
        self.tree.tag_configure("identical", foreground=palette["muted"])
        self.diff_menu.configure(background=palette["menu"], foreground=palette["menu_text"],
                                 activebackground=palette["menu_active"],
                                 activeforeground=palette["menu_active_text"])
    def apply_scale(self, scale: float) -> None:
        style = ttk.Style(self)
        linespace = tkfont.nametofont("TkDefaultFont").metrics("linespace")
        style.configure("PFCCompare.Treeview", font="TkDefaultFont",
                        rowheight=compare_row_height(linespace, scale))
        style.configure("PFCCompare.Treeview.Heading", font="TkHeadingFont")
        for column, width in self._column_widths.items():
            self.tree.column(column, width=max(50, round(width * scale)))
        padding = max(3, round(3 * scale))
        for label in (self.left_path_label, self.right_path_label):
            label.configure(padx=padding * 2, pady=padding)
        self.path_divider.configure(padx=max(8, round(8 * scale)), pady=padding)

    def apply_language(self, old_language: str) -> None:
        selected_keys = {self.item_keys.get(iid) for iid in self.tree.selection()}
        retranslate_widgets(self, old_language)
        self.previous_button.configure(text=f"F7 {tr('Diff <<')}")
        self.next_button.configure(text=f"F8 {tr('Diff >>')}")
        self._update_path_labels()
        self._build_diff_menu()
        labels = {"action": tr("Action"), "left_path": tr("Left"),
                  "left_detail": f"{tr('Size')} / {tr('Modified')}", "status": tr("Status"),
                  "right_path": tr("Right"), "right_detail": f"{tr('Size')} / {tr('Modified')}"}
        for column in ("action", "left_path", "left_detail", "status", "right_path", "right_detail"):
            marker = (" ▲" if not self.sort_reverse else " ▼") if column == self.sort_column else ""
            self.tree.heading(column, text=labels[column] + marker)
        self.populate()
        for iid in self._all_tree_items():
            if self.item_keys.get(iid) in selected_keys:
                self.tree.selection_add(iid)
        if self._scanning:
            self.scan_status.configure(text=tr("Scanning…  Esc cancels"))
        elif self.rows:
            different = sum(1 for row in self.rows if row[0] != "Identical")
            self.scan_status.configure(text=tr("{count} item(s), {different} different",
                                                count=len(self.rows), different=different))

    @staticmethod
    def _detail(path):
        if path is None: return "—"
        try:
            if path.is_dir(): return "<DIR>"
            stat = path.stat()
            return f"{stat.st_size:,} B  {datetime.fromtimestamp(stat.st_mtime):%Y-%m-%d %H:%M}"
        except OSError:
            return "?"

    def start_scan(self):
        if self._scanning:
            self._cancel_event.set()
        self._cancel_event = threading.Event(); self._scanning = True
        self.scan_status.configure(text=tr("Scanning…  Esc cancels"))
        recursive, masks, by_content = self.recursive_var.get(), self.mask_var.get(), self.content_var.get()
        text_equivalent = self.text_equivalent_var.get()
        cancel = self._cancel_event
        def worker():
            try:
                rows = list(folder_rows(self.left_root, self.right_root, recursive, masks, by_content,
                                        text_equivalent, cancel.is_set))
                self._scan_queue.put((cancel, rows, None))
            except OSError as exc:
                self._scan_queue.put((cancel, [], str(exc)))
        threading.Thread(target=worker, daemon=True).start()
        self.after(60, self._poll_scan)
        return "break"

    def _poll_scan(self):
        try:
            cancel, rows, error = self._scan_queue.get_nowait()
        except queue.Empty:
            if self.winfo_exists() and self._scanning: self.after(60, self._poll_scan)
            return
        if cancel is not self._cancel_event:
            if self.winfo_exists() and self._scanning: self.after(60, self._poll_scan)
            return
        self._scanning = False
        if cancel.is_set():
            self.scan_status.configure(text=tr("Scan cancelled"))
            return
        if error:
            self.scan_status.configure(text=tr("Scan failed"))
            messagebox.showerror(tr("Folder Compare"), error, parent=self)
            return
        self.rows, self.actions = rows, {}
        different = sum(status != "Identical" for status, *_rest in rows)
        self.scan_status.configure(text=tr("{count} item(s), {different} different",
                                           count=len(rows), different=different))
        self.populate()
        children = tuple(self._all_tree_items())
        if children:
            self.tree.selection_set(children[0]); self.tree.focus(children[0]); self.tree.see(children[0])
        self.tree.focus_set()

    def cancel_scan(self):
        if not self._scanning:
            return False
        self._cancel_event.set(); self._scanning = False
        self.scan_status.configure(text=tr("Scan cancelled"))
        return True

    def change_sort(self, column):
        selected_keys = {self.item_keys.get(iid) for iid in self.tree.selection()}
        self.sort_reverse = not self.sort_reverse if column == self.sort_column else False
        self.sort_column = column
        labels = {"action": tr("Action"), "left_path": tr("Left"),
                  "left_detail": f"{tr('Size')} / {tr('Modified')}", "status": tr("Status"),
                  "right_path": tr("Right"), "right_detail": f"{tr('Size')} / {tr('Modified')}"}
        for value in ("action", "left_path", "left_detail", "status", "right_path", "right_detail"):
            marker = (" ▼" if self.sort_reverse else " ▲") if value == column else ""
            self.tree.heading(value, text=labels[value] + marker)
        self.populate()
        for iid in self._all_tree_items():
            if self.item_keys.get(iid) in selected_keys:
                self.tree.selection_add(iid); self.tree.focus(iid); self.tree.see(iid)
        self.tree.focus_set()

    def populate(self):
        self.tree.delete(*self.tree.get_children())
        self.item_paths, self.item_keys = {}, {}
        self.difference_items, self.difference_index = [], -1
        action_label = {"right": "→", "left": "←", "skip": tr("Skip")}
        allowed = self.DIFF_FILTERS.get(self.view_mode_var.get())
        initially_visible = list(self.rows) if allowed is None else [row for row in self.rows if row[0] in allowed]
        rows_by_key = {row[1].casefold(): row for row in self.rows}
        needed = {row[1].casefold() for row in initially_visible}
        for _status, relative, _left, _right in initially_visible:
            parent = Path(relative).parent
            while parent != Path("."):
                key = str(parent).casefold()
                if key in rows_by_key:
                    needed.add(key)
                parent = parent.parent
        visible = [row for row in self.rows if row[1].casefold() in needed]
        if self.sort_column == "action":
            visible.sort(key=lambda row: self.actions.get(row[1], ""), reverse=self.sort_reverse)
        elif self.sort_column in {"left_detail", "right_detail"}:
            path_index = 2 if self.sort_column == "left_detail" else 3
            def metadata_key(row):
                path = row[path_index]
                if path is None: return (0, 0, 0)
                try:
                    stat = path.stat(); return (2 if path.is_dir() else 1, stat.st_size, stat.st_mtime_ns)
                except OSError:
                    return (0, 0, 0)
            visible.sort(key=metadata_key, reverse=self.sort_reverse)
        elif self.sort_column == "status":
            visible.sort(key=lambda row: row[0].casefold(), reverse=self.sort_reverse)
        else:
            visible.sort(key=lambda row: row[1].casefold(), reverse=self.sort_reverse)
        visible.sort(key=lambda row: len(Path(row[1]).parts))
        item_ids = {}
        for status, path, left, right in visible:
            tag = "left" if status in {"Left only", "Left newer"} else (
                "right" if status in {"Right only", "Right newer"} else (
                    "identical" if status == "Identical" else "different"))
            parent_key = str(Path(path).parent).casefold()
            parent_iid = item_ids.get(parent_key, "")
            iid = self.tree.insert(parent_iid, "end", text="", open=self._expand_state,
                values=(action_label.get(self.actions.get(path), ""),
                path if left is not None else "", self._detail(left), tr(status),
                path if right is not None else "", self._detail(right)), tags=(tag,))
            item_ids[path.casefold()] = iid
            self.item_paths[iid] = (left, right)
            self.item_keys[iid] = path
            if status != "Identical":
                self.difference_items.append(iid)
        self.diff_status.configure(text=f"0/{len(self.difference_items)}")
        self.find_all()

    def _difference(self, direction):
        if not self.difference_items:
            return "break"
        self.difference_index = (self.difference_index + direction) % len(self.difference_items)
        iid = self.difference_items[self.difference_index]
        self.tree.selection_set(iid); self.tree.focus(iid); self.tree.see(iid); self.tree.focus_set()
        self.diff_status.configure(text=f"{self.difference_index + 1}/{len(self.difference_items)}")
        return "break"

    def next(self): return self._difference(1)
    def previous(self): return self._difference(-1)

    def set_action(self, action):
        selected = self.tree.selection()
        selected_keys = {self.item_keys.get(iid) for iid in selected}
        for iid in selected:
            left, right = self.item_paths.get(iid, (None, None)); key = self.item_keys.get(iid)
            if key is None: continue
            if action == "right" and left is not None and not self.right_read_only:
                self.actions[key] = action
            elif action == "left" and right is not None and not self.left_read_only:
                self.actions[key] = action
            elif action == "skip":
                self.actions[key] = action
        self.populate()
        for iid in self._all_tree_items():
            if self.item_keys.get(iid) in selected_keys:
                self.tree.selection_add(iid)
        return "break"

    def _plans(self):
        plans = []
        by_key = {path: (left, right) for _status, path, left, right in self.rows}
        for key, action in self.actions.items():
            left, right = by_key.get(key, (None, None))
            if action == "right" and left is not None:
                plans.append((left, self.right_root / key))
            elif action == "left" and right is not None:
                plans.append((right, self.left_root / key))
        plans.sort(key=lambda item: len(item[1].parts))
        filtered = []
        for source, target in plans:
            if any(parent_source.is_dir() and parent_target in target.parents
                   for parent_source, parent_target in filtered):
                continue
            filtered.append((source, target))
        return filtered

    def dry_run(self):
        plans = self._plans()
        if not plans:
            messagebox.showinfo(tr("Safe Sync"), tr("Select rows and assign Copy → or ← Copy first."), parent=self)
            return "break"
        if not SyncPlanDialog.ask(self, plans):
            return "break"
        if self.sync_executor is not None:
            self.sync_executor(plans)
            self.start_scan()
        return "break"

    def focus_search(self):
        self.search.focus_set(); self.search.selection_range(0, "end"); return "break"

    def find_all(self):
        self.matches, self.match_index = [], -1; needle = self.search_var.get()
        for iid in self._all_tree_items():
            base = next((tag for tag in self.tree.item(iid, "tags")
                         if tag in {"left", "right", "different", "identical"}), "different")
            haystack = " ".join(str(value) for value in self.tree.item(iid, "values"))
            matched = needle in haystack if self.case_var.get() else needle.casefold() in haystack.casefold()
            if needle and matched:
                self.matches.append(iid); self.tree.item(iid, tags=(base, "find_match"))
            else:
                self.tree.item(iid, tags=(base,))
        self.find_status.configure(text=tr("{count} match(es)", count=len(self.matches)) if needle else "")

    def _find(self, direction):
        previous = self.match_index; self.find_all()
        if not self.matches: return "break"
        self.match_index = (previous + direction) % len(self.matches); iid = self.matches[self.match_index]
        self.tree.item(iid, tags=(*self.tree.item(iid, "tags"), "current_match"))
        self.tree.selection_set(iid); self.tree.focus(iid); self.tree.see(iid)
        self.find_status.configure(text=f"{self.match_index + 1}/{len(self.matches)}"); return "break"

    def find_next(self): return self._find(1)
    def find_previous(self): return self._find(-1)

    def _open(self, _event=None):
        selected = self.tree.selection()
        if selected:
            left, right = self.item_paths.get(selected[0], (None, None))
            if left and right and left.is_file() and right.is_file(): self.open_detail(left, right)


class FolderCompare(_FolderCompareLogic):
    """Folder/archive comparison using the same two-pane + mapper layout as file compare."""

    def __init__(self, master, left: Path, right: Path, open_detail, sync_executor=None,
                 left_label=None, right_label=None, left_read_only=False, right_read_only=False,
                 marker_position="middle", marker_changed=None):
        ttk.Frame.__init__(self, master)
        self.view = self
        self.left_root, self.right_root = left, right
        self.left_base_root, self.right_base_root = left, right
        self.left_label = Path(left_label) if left_label is not None else left
        self.right_label = Path(right_label) if right_label is not None else right
        self.left_read_only, self.right_read_only = left_read_only, right_read_only
        self.open_detail, self.sync_executor = open_detail, sync_executor
        self.marker_position_var = tk.StringVar(
            value=marker_position if marker_position in {"left", "middle", "right"} else "middle")
        self.marker_changed = marker_changed
        self.rows, self.actions, self.item_paths, self.item_keys = [], {}, {}, {}
        self._expand_state = True
        self._syncing_selection = False
        self._syncing_scroll = False
        self._syncing_open = False
        self.matches, self.match_index = [], -1
        self.difference_items, self.difference_index = [], -1
        self._scan_queue, self._cancel_event, self._scanning = queue.Queue(), threading.Event(), False
        self.sort_column, self.sort_reverse = "path", False
        self.scale = 1.0
        self.palette = getattr(master.winfo_toplevel(), "palette", color_scheme("light"))
        self._diff_icons = {}
        self.nested_details = {}

        self.session_tabs = ChamferNotebook(self)
        self.session_tabs.pack(fill="both", expand=True)
        self.session_tabs.set_theme(self.palette)
        self.summary = ttk.Frame(self.session_tabs)
        self.session_tabs.add(self.summary, text=tr("Folder Overview"))

        self.recursive_var = tk.BooleanVar(value=True)
        self.content_var = tk.BooleanVar(value=self.left_read_only or self.right_read_only)
        self.text_equivalent_var = tk.BooleanVar(value=True)
        self.view_mode_var = tk.StringVar(value="all")

        bar = ttk.Frame(self.summary, padding=(3, 3, 3, 1)); bar.pack(fill="x")
        ttk.Label(bar, text=tr("Mask:")).pack(side="left", padx=(0, 3))
        self.mask_var = tk.StringVar(value="*")
        ttk.Entry(bar, textvariable=self.mask_var, width=32).pack(side="left", padx=(0, 6))
        ttk.Button(bar, text=tr("Compare"), command=self.start_scan).pack(side="left", padx=(0, 3))
        ttk.Button(bar, text=tr("Cancel"), command=self.cancel_scan).pack(side="left", padx=(0, 8))
        ttk.Separator(bar, orient="vertical").pack(side="left", fill="y", padx=(0, 7))
        self.recursive_button = ttk.Button(bar, command=lambda: self._toggle_option("recursive"))
        self.recursive_button.pack(side="left", padx=(0, 3))
        self.content_button = ttk.Button(bar, command=lambda: self._toggle_option("content"))
        self.content_button.pack(side="left", padx=(0, 3))
        self.text_equivalent_button = ttk.Button(
            bar, command=lambda: self._toggle_option("text_equivalent"))
        self.text_equivalent_button.pack(side="left")
        self.text_equivalent_button._pfc_tooltip = ToolTip(
            self.text_equivalent_button,
            lambda: tr("Ignore BOM, line-ending, trailing-space, Unicode-composition, and invisible-control differences in text files."))

        self.body = ttk.Frame(self.summary)
        self.center_header = ttk.Frame(self.body)
        options = ttk.Frame(self.summary, padding=(3, 1)); options.pack(fill="x")
        self.diff_button = ttk.Menubutton(self.center_header, text=tr("Diffs"))
        self.diff_menu = tk.Menu(self.diff_button, tearoff=False)
        self.diff_button.configure(menu=self.diff_menu, compound="left")
        self.diff_button.pack(side="top", fill="x")
        self._build_diff_menu()
        ttk.Button(options, text=tr("Expand All"), command=self.expand_all).pack(side="left", padx=(0, 3))
        ttk.Button(options, text=tr("Collapse All"), command=self.collapse_all).pack(side="left", padx=(0, 3))
        ttk.Button(options, text=tr("Set Base Folder"), command=self.set_base_folder).pack(side="left", padx=(0, 3))
        ttk.Separator(options, orient="vertical").pack(side="left", fill="y", padx=7)
        self.marker_button = ttk.Menubutton(options)
        self.marker_menu = tk.Menu(self.marker_button, tearoff=False)
        self.marker_button.configure(menu=self.marker_menu); self.marker_button.pack(side="left")
        self._build_marker_menu(); self._update_marker_button()

        navigation = ttk.Frame(self.summary, padding=(3, 1)); navigation.pack(fill="x")
        self.previous_button = ttk.Button(navigation, text=f"F7 {tr('Diff <<')}", command=self.previous)
        self.previous_button.pack(side="left", padx=(0, 3))
        self.next_button = ttk.Button(navigation, text=f"F8 {tr('Diff >>')}", command=self.next)
        self.next_button.pack(side="left", padx=(0, 3))
        self.diff_status = ttk.Label(navigation, width=18, anchor="w")
        self.diff_status.pack(side="left", padx=(0, 8))
        self.search_var, self.case_var = tk.StringVar(), tk.BooleanVar(value=False)
        ttk.Label(navigation, text=tr("Find:")).pack(side="left", padx=(0, 3))
        self.search = ttk.Entry(navigation, textvariable=self.search_var, width=32)
        self.search.pack(side="left", padx=(0, 4))
        self.search.bind("<Return>", lambda _event: self.find_next())
        self.search.bind("<Shift-Return>", lambda _event: self.find_previous())
        ttk.Button(navigation, text=tr("Find Prev"), command=self.find_previous).pack(side="left", padx=(0, 3))
        ttk.Button(navigation, text=tr("Find Next"), command=self.find_next).pack(side="left", padx=(0, 3))
        self.find_status = ttk.Label(navigation, anchor="w")
        self.find_status.pack(side="left", padx=(2, 6))
        self.case_button = ttk.Button(navigation, command=lambda: self._toggle_option("case"))
        self.case_button.pack(side="left")
        self._update_toggle_buttons()

        status_row = ttk.Frame(self.summary, padding=(5, 3)); status_row.pack(side="bottom", fill="x")
        self.scan_status = ttk.Label(status_row, text=tr("Ready"), anchor="w")
        self.scan_status.pack(side="left")
        ttk.Label(status_row, text=tr("Copy only — no automatic delete")).pack(side="left", padx=(12, 0))
        ttk.Button(status_row, text=tr("Dry Run && Sync"), command=self.dry_run).pack(side="right")

        self.body.pack(fill="both", expand=True, pady=(3, 0))
        self.body.rowconfigure(1, weight=1)
        self.left_path_label = tk.Label(self.body, anchor="w", background="#2d668f",
                                        foreground="white", font="TkHeadingFont", padx=6, pady=3)
        self.right_path_label = tk.Label(self.body, anchor="w", background="#9b5d2e",
                                         foreground="white", font="TkHeadingFont", padx=6, pady=3)
        self.map_header = tk.Button(self.center_header, text="⇄", command=self.swap_sides,
                                    background="#263d4c", foreground="white",
                                    activebackground="#36566b", activeforeground="white",
                                    font="TkHeadingFont", relief="flat", borderwidth=0,
                                    cursor="hand2", pady=3)
        self.map_header._pfc_tooltip = ToolTip(self.map_header, tr("Swap Sides"))
        self.map_header.pack(side="top", fill="x")
        self._update_path_labels()
        self.left_frame = ttk.Frame(self.body); self.right_frame = ttk.Frame(self.body)
        for frame in (self.left_frame, self.right_frame):
            frame.rowconfigure(0, weight=1); frame.columnconfigure(0, weight=1)
        self.left_tree = ttk.Treeview(self.left_frame, columns=("action", "detail"),
                                      show=("tree", "headings"), selectmode="extended",
                                      style="PFCCompare.Treeview")
        self.right_tree = ttk.Treeview(self.right_frame, columns=("detail", "action"),
                                       show=("tree", "headings"), selectmode="extended",
                                       style="PFCCompare.Treeview")
        self.tree = self.left_tree
        self.left_tree.heading("#0", text=tr("Name"), command=lambda: self.change_sort("path"))
        self.left_tree.heading("action", text=tr("Action"), command=lambda: self.change_sort("action"))
        self.left_tree.heading("detail", text=f"{tr('Size')} / {tr('Modified')}",
                               command=lambda: self.change_sort("left_detail"))
        self.right_tree.heading("#0", text=tr("Name"), command=lambda: self.change_sort("path"))
        self.right_tree.heading("detail", text=f"{tr('Size')} / {tr('Modified')}",
                                command=lambda: self.change_sort("right_detail"))
        self.right_tree.heading("action", text=tr("Action"), command=lambda: self.change_sort("action"))
        for tree in (self.left_tree, self.right_tree):
            tree.column("#0", width=340, minwidth=100, stretch=True)
            tree.column("action", width=70, minwidth=45, stretch=False, anchor="center")
            tree.column("detail", width=205, minwidth=95, stretch=False)
            tree.grid(row=0, column=0, sticky="nsew")
            tree.bind("<<TreeviewSelect>>", lambda event, source=tree: self._sync_selection(source))
            tree.bind("<<TreeviewOpen>>", lambda event, source=tree: self._sync_open(source, True))
            tree.bind("<<TreeviewClose>>", lambda event, source=tree: self._sync_open(source, False))
            tree.bind("<Double-1>", self._open); tree.bind("<Return>", self._open)
            tree.bind("<Control-Right>", lambda _e: self.set_action("right"))
            tree.bind("<Control-Left>", lambda _e: self.set_action("left"))
            tree.bind("<space>", lambda _e: self.set_action("skip"))
            tree.bind("<MouseWheel>", self._mousewheel)
            tree._pfc_sync_tooltip = ToolTip(
                tree, tr("Enter opens nested file compare • Ctrl+→ copy to right • "
                         "Ctrl+← copy to left • Space skip"), delay=5000)
        left_x = ttk.Scrollbar(self.left_frame, orient="horizontal", command=self.left_tree.xview)
        right_x = ttk.Scrollbar(self.right_frame, orient="horizontal", command=self.right_tree.xview)
        left_x.grid(row=1, column=0, sticky="ew"); right_x.grid(row=1, column=0, sticky="ew")
        self.left_tree.configure(xscrollcommand=left_x.set, yscrollcommand=self._left_scrolled)
        self.right_tree.configure(xscrollcommand=right_x.set, yscrollcommand=self._right_scrolled)
        self.difference_map = DifferenceMap(self.body, self._jump_to_row)
        self.center_divider = ttk.Separator(self.body, orient="vertical")
        self.scroll = ttk.Scrollbar(self.body, orient="vertical", command=self._scroll)
        self._layout_marker()
        self.apply_scale(1.0)
        self.apply_color_scheme(getattr(master.winfo_toplevel(), "palette", color_scheme("light")))
        self.start_scan()

    def _trees(self):
        return (self.left_tree, self.right_tree)

    def _toggle_option(self, option):
        if option == "recursive":
            self.recursive_var.set(not self.recursive_var.get())
        elif option == "content":
            self.content_var.set(not self.content_var.get())
        elif option == "text_equivalent":
            self.text_equivalent_var.set(not self.text_equivalent_var.get())
        elif option == "case":
            self.case_var.set(not self.case_var.get()); self.find_all()
        self._update_toggle_buttons()
        return "break"

    def _update_toggle_buttons(self):
        self.recursive_button.configure(
            text=f"{'✓' if self.recursive_var.get() else '–'} {tr('Recursive')}")
        self.content_button.configure(
            text=f"{'✓' if self.content_var.get() else '–'} {tr('By content')}")
        self.text_equivalent_button.configure(
            text=f"{'✓' if self.text_equivalent_var.get() else '–'} {tr('Text equivalent')}")
        self.case_button.configure(
            text=f"{'✓' if self.case_var.get() else '–'} {tr('Case sensitive')}")

    def _build_diff_menu(self):
        self.diff_menu.delete(0, "end")
        selected = self.view_mode_var.get()
        self._diff_icons = {value: self._make_diff_icon(value) for value in self.DIFF_FILTERS}
        separators_after = {"orphans", "right_newer"}
        for value in self.DIFF_FILTERS:
            prefix = "● " if value == selected else "   "
            self.diff_menu.add_command(
                label=prefix + tr(self.DIFF_LABELS[value]), image=self._diff_icons[value],
                compound="left", command=lambda mode=value: self._select_diff_filter(mode))
            if value in separators_after:
                self.diff_menu.add_separator()
        self._update_diff_button()

    def _make_diff_icon(self, value):
        """Two columns encode left/right; red means changed/newer, purple means orphan."""
        scale = max(1.0, self.scale)
        block, gap = max(5, round(6 * scale)), max(2, round(2 * scale))
        width, height = block * 2 + gap * 3, block * 2 + gap * 3
        icon = tk.PhotoImage(master=self, width=width, height=height)
        dark = self.palette.get("window") == "#20262c"
        colors = {
            "neutral": "#a9b3ba" if dark else "#7b858c",
            "difference": "#ff625d" if dark else "#d92f2f",
            "orphan": "#b985ff" if dark else "#7d42bd",
        }
        layouts = {
            "all": (("neutral", "neutral"), ("neutral", "neutral")),
            "differences": (("difference", "difference"), ("difference", "difference")),
            "no_orphans": (("difference", "difference"), ("neutral", "neutral")),
            "differences_no_orphans": (("difference", "difference"), (None, None)),
            "orphans": (("orphan", "orphan"), ("orphan", "orphan")),
            "left_newer": (("difference", None), ("difference", None)),
            "right_newer": ((None, "difference"), (None, "difference")),
            "left_newer_orphans": (("difference", None), ("orphan", None)),
            "right_newer_orphans": ((None, "difference"), (None, "orphan")),
            "left_orphans": (("orphan", None), ("orphan", None)),
            "right_orphans": ((None, "orphan"), (None, "orphan")),
        }
        for row, pair in enumerate(layouts[value]):
            for column, token in enumerate(pair):
                if token is None:
                    continue
                x = gap + column * (block + gap); y = gap + row * (block + gap)
                icon.put(colors[token], to=(x, y, x + block, y + block))
        return icon

    def _update_diff_button(self):
        key = self.view_mode_var.get()
        image = self._diff_icons.get(key)
        self.diff_button.configure(text=tr("Diffs"), image=image or "", compound="left")
        tooltip_text = tr(self.DIFF_LABELS.get(key, "Show All"))
        if hasattr(self, "_diff_tooltip"):
            self._diff_tooltip.text = tooltip_text
        else:
            self._diff_tooltip = ToolTip(self.diff_button, tooltip_text)

    def _select_diff_filter(self, value):
        self.view_mode_var.set(value); self._set_diff_filter()

    def _build_marker_menu(self):
        self.marker_menu.delete(0, "end")
        selected = self.marker_position_var.get()
        for value, label in (("left", "Left"), ("middle", "Middle"), ("right", "Right")):
            prefix = "● " if value == selected else "   "
            self.marker_menu.add_command(label=prefix + tr(label),
                                         command=lambda position=value:
                                         self.set_marker_position(position, notify=True))

    def _update_marker_button(self):
        labels = {"left": "Left", "middle": "Middle", "right": "Right"}
        self.marker_button.configure(
            text=f"{tr('Map:')} {tr(labels.get(self.marker_position_var.get(), 'Middle'))}")

    def _selected_items(self):
        return self.left_tree.selection() or self.right_tree.selection()

    def _sync_selection(self, source):
        if self._syncing_selection:
            return
        self._syncing_selection = True
        try:
            target = self.right_tree if source is self.left_tree else self.left_tree
            selected = source.selection()
            if tuple(target.selection()) != tuple(selected):
                target.selection_set(selected)
            focus = source.focus()
            if focus and target.focus() != focus:
                target.focus(focus); target.see(focus)
        finally:
            self._syncing_selection = False

    def _sync_open(self, source, opened):
        if self._syncing_open:
            return
        iid = source.focus()
        target = self.right_tree if source is self.left_tree else self.left_tree
        if iid and target.exists(iid) and bool(target.item(iid, "open")) != opened:
            self._syncing_open = True
            try:
                target.item(iid, open=opened)
            finally:
                self._syncing_open = False

    def _scroll(self, *args):
        for tree in self._trees(): tree.yview(*args)

    def _left_scrolled(self, first, last):
        self.scroll.set(first, last); self.difference_map.set_viewport(first, last)
        if self._syncing_scroll:
            return
        self._syncing_scroll = True
        try:
            self.right_tree.yview_moveto(first)
        finally:
            self._syncing_scroll = False

    def _right_scrolled(self, first, last):
        self.scroll.set(first, last); self.difference_map.set_viewport(first, last)
        if self._syncing_scroll:
            return
        self._syncing_scroll = True
        try:
            self.left_tree.yview_moveto(first)
        finally:
            self._syncing_scroll = False

    def _mousewheel(self, event):
        units = -int(event.delta / 120) if event.delta else 0
        for tree in self._trees(): tree.yview_scroll(units, "units")
        return "break"

    def set_marker_position(self, position: str, notify: bool = False):
        if position not in {"left", "middle", "right"}: position = "middle"
        self.marker_position_var.set(position); self._layout_marker()
        self._build_marker_menu(); self._update_marker_button()
        for details in self.nested_details.values():
            view = getattr(details["detail"], "view", details["detail"])
            if hasattr(view, "set_marker_position"):
                view.set_marker_position(position)
        if notify and self.marker_changed is not None: self.marker_changed(position)

    def _marker_position_changed(self):
        self.set_marker_position(self.marker_position_var.get(), notify=True)

    def _layout_marker(self):
        for column in range(6): self.body.columnconfigure(column, weight=0, uniform="")
        position = self.marker_position_var.get()
        map_column = 0 if position == "left" else (4 if position == "right" else 2)
        left_column, center_column, right_column = 1, 2, 3
        for column in (left_column, right_column):
            self.body.columnconfigure(column, weight=1, uniform="compare")
        self.left_path_label.grid(row=0, column=left_column, sticky="ew")
        self.left_frame.grid(row=1, column=left_column, sticky="nsew")
        self.right_path_label.grid(row=0, column=right_column, sticky="ew")
        self.right_frame.grid(row=1, column=right_column, sticky="nsew")
        self.center_header.grid(row=0, column=center_column, sticky="ew", padx=4)
        self.difference_map.grid(row=1, column=map_column, sticky="ns", padx=4)
        if position == "middle":
            self.center_divider.grid_forget()
        else:
            self.center_divider.grid(row=1, column=center_column, sticky="ns")
        self.scroll.grid(row=1, column=5, sticky="ns")

    def expand_all(self):
        self._expand_state = True
        for iid in self.left_tree.get_children(""): self._set_open_recursive(iid, True)
        return "break"

    def collapse_all(self):
        self._expand_state = False
        for iid in self.left_tree.get_children(""): self._set_open_recursive(iid, False)
        return "break"

    def _set_open_recursive(self, iid, opened):
        for tree in self._trees(): tree.item(iid, open=opened)
        for child in self.left_tree.get_children(iid): self._set_open_recursive(child, opened)

    def _all_tree_items(self, parent=""):
        for iid in self.left_tree.get_children(parent):
            yield iid
            yield from self._all_tree_items(iid)

    def apply_color_scheme(self, palette):
        self.palette = palette
        self.session_tabs.set_theme(palette)
        self.left_path_label.configure(background=palette["left_header"], foreground="#ffffff")
        self.right_path_label.configure(background=palette["right_header"], foreground="#ffffff")
        self.map_header.configure(background=palette["map_header"], foreground="#ffffff",
                                  activebackground=palette["menu_active"],
                                  activeforeground=palette["menu_active_text"])
        self.difference_map.apply_color_scheme(palette)
        dark = palette["window"] == "#20262c"
        for tree in self._trees():
            tree.tag_configure("find_match", background=palette["match"], foreground=palette["text"])
            tree.tag_configure("current_match", background=palette["current_diff"], foreground="#ffffff")
            tree.tag_configure("different", foreground="#ff7770" if dark else "#a00000")
            tree.tag_configure("newer_left", foreground="#ff7770" if dark else "#a00000")
            tree.tag_configure("newer_right", foreground="#ff7770" if dark else "#a00000")
            tree.tag_configure("orphan_left", foreground="#c391ff" if dark else "#7137a8")
            tree.tag_configure("orphan_right", foreground="#c391ff" if dark else "#7137a8")
            tree.tag_configure("identical", foreground=palette["muted"])
        self._build_diff_menu()
        self.diff_menu.configure(background=palette["menu"], foreground=palette["menu_text"],
                                 activebackground=palette["menu_active"],
                                 activeforeground=palette["menu_active_text"])
        self.marker_menu.configure(background=palette["menu"], foreground=palette["menu_text"],
                                   activebackground=palette["menu_active"],
                                   activeforeground=palette["menu_active_text"])
        for details in self.nested_details.values():
            view = getattr(details["detail"], "view", details["detail"])
            handler = getattr(view, "apply_color_scheme", None)
            if callable(handler):
                handler(palette)

    def apply_scale(self, scale: float):
        self.scale = scale
        self.session_tabs.redraw()
        style = ttk.Style(self)
        linespace = tkfont.nametofont("TkDefaultFont").metrics("linespace")
        style.configure("PFCCompare.Treeview", font="TkDefaultFont",
                        rowheight=compare_row_height(linespace, scale))
        style.configure("PFCCompare.Treeview.Heading", font="TkHeadingFont")
        for tree in self._trees():
            tree.column("#0", width=max(130, round(340 * scale)))
            tree.column("action", width=max(50, round(70 * scale)))
            tree.column("detail", width=max(110, round(205 * scale)))
        padding = max(3, round(3 * scale))
        for label in (self.left_path_label, self.right_path_label): label.configure(padx=padding * 2, pady=padding)
        self.map_header.configure(pady=padding); self.difference_map.apply_scale(scale)
        self._build_diff_menu()
        for details in self.nested_details.values():
            handler = getattr(details["detail"], "apply_scale", None)
            if callable(handler):
                handler(scale)

    def apply_language(self, old_language: str):
        selected_keys = {self.item_keys.get(iid) for iid in self._selected_items()}
        retranslate_widgets(self, old_language)
        self.previous_button.configure(text=f"F7 {tr('Diff <<')}")
        self.next_button.configure(text=f"F8 {tr('Diff >>')}")
        self._update_path_labels(); self._build_diff_menu(); self._build_marker_menu()
        self._update_marker_button(); self._update_toggle_buttons(); self._update_headings(); self.populate()
        selected = [iid for iid in self._all_tree_items() if self.item_keys.get(iid) in selected_keys]
        self._select_items(selected)
        self.session_tabs.tab(self.summary, text=tr("Folder Overview"))
        for page, details in self.nested_details.items():
            details["back"].configure(text=tr("← Folder Overview"))
            details["caption"].configure(text=tr("Nested file compare"))
            handler = getattr(details["detail"], "apply_language", None)
            if callable(handler):
                handler(old_language)
            self.session_tabs.tab(
                page, text=f"{tr(details['kind'])}: {details['left'].name} ↔ {details['right'].name}")
        self.session_tabs.redraw()

    def _update_headings(self):
        direction = " ▼" if self.sort_reverse else " ▲"
        path_mark = direction if self.sort_column == "path" else ""
        action_mark = direction if self.sort_column == "action" else ""
        self.left_tree.heading("#0", text=tr("Name") + path_mark)
        self.right_tree.heading("#0", text=tr("Name") + path_mark)
        self.left_tree.heading("action", text=tr("Action") + action_mark)
        self.right_tree.heading("action", text=tr("Action") + action_mark)
        self.left_tree.heading("detail", text=f"{tr('Size')} / {tr('Modified')}" +
                               (direction if self.sort_column == "left_detail" else ""))
        self.right_tree.heading("detail", text=f"{tr('Size')} / {tr('Modified')}" +
                                (direction if self.sort_column == "right_detail" else ""))

    def change_sort(self, column):
        selected_keys = {self.item_keys.get(iid) for iid in self._selected_items()}
        self.sort_reverse = not self.sort_reverse if column == self.sort_column else False
        self.sort_column = column; self._update_headings(); self.populate()
        self._select_items([iid for iid in self._all_tree_items()
                            if self.item_keys.get(iid) in selected_keys])

    def populate(self):
        for tree in self._trees(): tree.delete(*tree.get_children())
        self.item_paths, self.item_keys = {}, {}
        self.difference_items, self.difference_index = [], -1
        action_label = {"right": "→", "left": "←", "skip": tr("Skip")}
        allowed = self.DIFF_FILTERS.get(self.view_mode_var.get())
        initially_visible = list(self.rows) if allowed is None else [row for row in self.rows if row[0] in allowed]
        rows_by_key = {row[1].casefold(): row for row in self.rows}
        needed = {row[1].casefold() for row in initially_visible}
        for _status, relative, _left, _right in initially_visible:
            parent = Path(relative).parent
            while parent != Path("."):
                key = str(parent).casefold()
                if key in rows_by_key: needed.add(key)
                parent = parent.parent
        visible = [row for row in self.rows if row[1].casefold() in needed]
        if self.sort_column == "action":
            visible.sort(key=lambda row: self.actions.get(row[1], ""), reverse=self.sort_reverse)
        elif self.sort_column in {"left_detail", "right_detail"}:
            path_index = 2 if self.sort_column == "left_detail" else 3
            def metadata_key(row):
                path = row[path_index]
                if path is None: return (0, 0, 0)
                try:
                    stat = path.stat(); return (2 if path.is_dir() else 1, stat.st_size, stat.st_mtime_ns)
                except OSError: return (0, 0, 0)
            visible.sort(key=metadata_key, reverse=self.sort_reverse)
        else:
            visible.sort(key=lambda row: row[1].casefold(), reverse=self.sort_reverse)
        visible.sort(key=lambda row: len(Path(row[1]).parts))
        item_ids = {}
        for index, (status, path, left, right) in enumerate(visible):
            iid = f"folder-row-{index}"
            tag = ("orphan_left" if status == "Left only" else
                   "orphan_right" if status == "Right only" else
                   "newer_left" if status == "Left newer" else
                   "newer_right" if status == "Right newer" else
                   "identical" if status == "Identical" else "different")
            parent_iid = item_ids.get(str(Path(path).parent).casefold(), "")
            action = action_label.get(self.actions.get(path), "")
            self.left_tree.insert(parent_iid, "end", iid=iid, text=path if left is not None else "",
                                  open=self._expand_state,
                                  values=(action if self.actions.get(path) in {"right", "skip"} else "",
                                          self._detail(left)), tags=(tag,))
            self.right_tree.insert(parent_iid, "end", iid=iid, text=path if right is not None else "",
                                   open=self._expand_state,
                                   values=(self._detail(right),
                                           action if self.actions.get(path) in {"left", "skip"} else ""),
                                   tags=(tag,))
            item_ids[path.casefold()] = iid; self.item_paths[iid] = (left, right); self.item_keys[iid] = path
            if status != "Identical": self.difference_items.append(iid)
        ordered = list(self._all_tree_items())
        difference_rows = [ordered.index(iid) + 1 for iid in self.difference_items if iid in ordered]
        self.difference_map.set_rows(difference_rows, len(ordered))
        self._update_difference_status(0); self.find_all()

    def _select_items(self, items):
        items = tuple(items)
        self._syncing_selection = True
        try:
            for tree in self._trees():
                tree.selection_set(items)
                if items: tree.focus(items[0]); tree.see(items[0])
        finally:
            self._syncing_selection = False
        if items: self.left_tree.focus_set()

    def _difference(self, direction):
        if not self.difference_items: return "break"
        self.difference_index = (self.difference_index + direction) % len(self.difference_items)
        iid = self.difference_items[self.difference_index]; self._select_items((iid,))
        ordered = list(self._all_tree_items())
        if iid in ordered: self.difference_map.set_current(ordered.index(iid) + 1)
        self._update_difference_status(self.difference_index + 1)
        return "break"

    def _update_difference_status(self, current):
        self.diff_status.configure(text=tr("{current} of {count} differences",
                                           current=current, count=len(self.difference_items)))

    def _jump_to_row(self, row):
        ordered = list(self._all_tree_items())
        if 1 <= row <= len(ordered) and ordered[row - 1] in self.difference_items:
            self.difference_index = self.difference_items.index(ordered[row - 1])
            self._difference(0)

    def find_all(self):
        self.matches, self.match_index = [], -1; needle = self.search_var.get()
        for iid in self._all_tree_items():
            tags = self.left_tree.item(iid, "tags")
            semantic_tags = {"orphan_left", "orphan_right", "newer_left", "newer_right",
                             "different", "identical"}
            base = next((tag for tag in tags if tag in semantic_tags), "different")
            haystack = " ".join((self.left_tree.item(iid, "text"), self.right_tree.item(iid, "text"),
                                 *(str(v) for v in self.left_tree.item(iid, "values")),
                                 *(str(v) for v in self.right_tree.item(iid, "values"))))
            matched = needle in haystack if self.case_var.get() else needle.casefold() in haystack.casefold()
            row_tags = (base, "find_match") if needle and matched else (base,)
            for tree in self._trees(): tree.item(iid, tags=row_tags)
            if needle and matched: self.matches.append(iid)
        self.find_status.configure(text=tr("{count} match(es)", count=len(self.matches)) if needle else "")

    def _find(self, direction):
        previous = self.match_index; self.find_all()
        if not self.matches: return "break"
        self.match_index = (previous + direction) % len(self.matches); iid = self.matches[self.match_index]
        for tree in self._trees(): tree.item(iid, tags=(*tree.item(iid, "tags"), "current_match"))
        self._select_items((iid,))
        self.find_status.configure(text=tr("{current} of {count} matches",
                                           current=self.match_index + 1, count=len(self.matches)))
        return "break"

    def set_action(self, action):
        selected = self._selected_items(); selected_keys = {self.item_keys.get(iid) for iid in selected}
        for iid in selected:
            left, right = self.item_paths.get(iid, (None, None)); key = self.item_keys.get(iid)
            if key is None: continue
            if action == "right" and left is not None and not self.right_read_only: self.actions[key] = action
            elif action == "left" and right is not None and not self.left_read_only: self.actions[key] = action
            elif action == "skip": self.actions[key] = action
        self.populate(); self._select_items([iid for iid in self._all_tree_items()
                                             if self.item_keys.get(iid) in selected_keys])
        return "break"

    def set_base_folder(self):
        selected = self._selected_items()
        if not selected:
            messagebox.showinfo(tr("Set Base Folder"), tr("Select a folder row first."), parent=self)
            return "break"
        left, right = self.item_paths.get(selected[0], (None, None)); changed = False
        if left is not None and left.is_dir(): self.left_root = left; changed = True
        if right is not None and right.is_dir(): self.right_root = right; changed = True
        if not changed:
            messagebox.showinfo(tr("Set Base Folder"), tr("The selected row is not a folder."), parent=self)
            return "break"
        self._update_path_labels(); self.start_scan(); return "break"

    def _update_path_labels(self):
        self.left_path_label.configure(text=f"{tr('Left')}: {self._base_label('left')}")
        self.right_path_label.configure(text=f"{tr('Right')}: {self._base_label('right')}")

    def _active_detail_view(self):
        selected = self.session_tabs.select()
        if not selected:
            return None
        page = self.nametowidget(selected)
        details = self.nested_details.get(page)
        if details is None:
            return None
        return getattr(details["detail"], "view", details["detail"])

    def _show_summary(self):
        self.session_tabs.select(self.summary)
        self.after_idle(self.left_tree.focus_set)

    def open_nested_detail(self, left: Path, right: Path, relative: str):
        key = (str(left), str(right))
        for page, details in self.nested_details.items():
            if details["key"] == key:
                self.session_tabs.select(page)
                view = getattr(details["detail"], "view", details["detail"])
                self.after_idle(lambda target=getattr(view, "left", view): target.focus_set())
                return "break"

        page = ttk.Frame(self.session_tabs)
        breadcrumb = ttk.Frame(page, padding=(4, 3))
        breadcrumb.pack(fill="x")
        back = ttk.Button(breadcrumb, text=tr("← Folder Overview"), command=self._show_summary)
        back.pack(side="left", padx=(0, 8))
        caption = ttk.Label(breadcrumb, text=tr("Nested file compare"), style="Heading.TLabel")
        caption.pack(side="left")
        host = ttk.Frame(page)
        host.pack(fill="both", expand=True)
        left_title = nested_source_label(self.left_label, relative)
        right_title = nested_source_label(self.right_label, relative)
        kind, detail = self.open_detail(
            host, left, right, left_title=left_title, right_title=right_title)
        detail.pack(fill="both", expand=True)
        install_button_tooltips(page)
        details = {
            "key": key, "detail": detail, "kind": kind, "left": left, "right": right,
            "back": back, "caption": caption,
        }
        self.nested_details[page] = details
        self.session_tabs.add(page, text=f"{tr(kind)}: {left.name} ↔ {right.name}")
        view = getattr(detail, "view", detail)
        color_handler = getattr(view, "apply_color_scheme", None)
        if callable(color_handler):
            color_handler(self.palette)
        scale_handler = getattr(detail, "apply_scale", None)
        if callable(scale_handler):
            scale_handler(self.scale)
        self.after_idle(lambda: getattr(view, "left", view).focus_set())
        return "break"

    def close_nested_detail(self):
        selected = self.session_tabs.select()
        if not selected:
            return False
        page = self.nametowidget(selected)
        if page is self.summary:
            return False
        if page not in self.nested_details:
            return False
        self.session_tabs.forget(page)
        self.nested_details.pop(page, None)
        page.destroy()
        self._show_summary()
        return True

    def next(self):
        view = self._active_detail_view()
        if view is not None and hasattr(view, "next"):
            return view.next()
        return self._difference(1)

    def previous(self):
        view = self._active_detail_view()
        if view is not None and hasattr(view, "previous"):
            return view.previous()
        return self._difference(-1)

    def focus_search(self):
        view = self._active_detail_view()
        if view is not None and hasattr(view, "focus_search"):
            return view.focus_search()
        self.search.focus_set(); self.search.selection_range(0, "end")
        return "break"

    def _open(self, _event=None):
        selected = self._selected_items()
        if selected:
            left, right = self.item_paths.get(selected[0], (None, None))
            relative = self.item_keys.get(selected[0], "")
            if left and right and left.is_file() and right.is_file():
                return self.open_nested_detail(left, right, relative)
        return "break"


class TableCompare(TextCompare):
    def __init__(self, master, left: Path, right: Path, marker_position="middle", marker_changed=None,
                 left_title=None, right_title=None):
        def rows(path):
            delimiter = "\t" if path.suffix.casefold() == ".tsv" else ","
            with path.open("r", encoding="utf-8-sig", errors="replace", newline="") as stream:
                return [" | ".join(row) for row in csv.reader(stream, delimiter=delimiter)]
        ttk.Frame.__init__(self, master)
        a, b = "\n".join(rows(left)), "\n".join(rows(right))
        aligned, differences = aligned_text(a, b)
        self.view = SideBySideText(
            self, [(r[0], r[1]) for r in aligned], [(r[2], r[3]) for r in aligned], differences,
            status_factory=lambda count=len(differences): tr("{count} different row(s)", count=count),
            left_title=left_title or left, right_title=right_title or right,
            marker_position=marker_position,
            marker_changed=marker_changed)
        self.view.pack(fill="both", expand=True)


class CompareWindow(tk.Toplevel):
    def __init__(self, master, config, save_config, sync_executor=None):
        super().__init__(master)
        self.config_data, self.save_config = config, save_config
        self.palette = getattr(master, "palette", color_scheme("light"))
        self.sync_executor = sync_executor
        self.comparisons = {}
        self._archive_workspaces = []
        self.scale = 1.0
        self.marker_position = config.get("compare", "marker_position", fallback="middle")
        if self.marker_position not in {"left", "middle", "right"}:
            self.marker_position = "middle"
        self._refresh_job = None
        self.title(tr("PFC Compare"))
        self.geometry(config.get("compare", "geometry", fallback="1400x850"))
        self.protocol("WM_DELETE_WINDOW", self.close)
        self.notebook = ChamferNotebook(self); self.notebook.pack(fill="both", expand=True)
        self.notebook.set_theme(self.palette)
        self.configure(background=self.palette["window"])
        self.bind("<F7>", lambda _e: self._navigate("previous"))
        self.bind("<F8>", lambda _e: self._navigate("next"))
        self.bind("<Control-f>", lambda _e: self.focus_search())
        self.bind("<Escape>", lambda _e: self.close_active())
        install_button_tooltips(self)
        self._schedule_refresh()

    def apply_scale(self, scale: float) -> None:
        self.scale = scale
        self.notebook.redraw()
        for frame in self.comparisons:
            handler = getattr(frame, "apply_scale", None)
            if callable(handler):
                handler(scale)

    def apply_color_scheme(self, palette) -> None:
        self.palette = palette
        self.configure(background=palette["window"])
        self.notebook.set_theme(palette)
        for frame in self.comparisons:
            target = getattr(frame, "view", frame)
            handler = getattr(target, "apply_color_scheme", None)
            if callable(handler):
                handler(palette)

    def apply_language(self, old_language: str) -> None:
        retranslate_widgets(self, old_language)
        self.title(tr("PFC Compare"))
        for frame, (left, right, kind, _signature) in self.comparisons.items():
            if hasattr(frame, "apply_language"):
                frame.apply_language(old_language)
            self.notebook.tab(frame, text=f"{tr(kind)}: {left.name} ↔ {right.name}")
        self.notebook.redraw()

    @staticmethod
    def _signature(left: Path, right: Path):
        if left.is_dir() or right.is_dir():
            return None
        try:
            return tuple((path.stat().st_mtime_ns, path.stat().st_size) for path in (left, right))
        except OSError:
            return None

    def _make_frame(self, left: Path, right: Path, kind: str):
        if kind == "Folder":
            left_root, left_read_only = self._prepare_folder_source(left)
            right_root, right_read_only = self._prepare_folder_source(right)
            return FolderCompare(self.notebook, left_root, right_root, self._make_file_frame,
                                 self.sync_executor,
                                 left_label=left, right_label=right,
                                 left_read_only=left_read_only, right_read_only=right_read_only,
                                 marker_position=self.marker_position,
                                 marker_changed=self.set_marker_position)
        return self._make_file_frame(self.notebook, left, right, kind)[1]

    def _make_file_frame(self, master, left: Path, right: Path, kind=None,
                         left_title=None, right_title=None):
        kind = kind or detect_compare_type(left, right)
        options = {
            "marker_position": self.marker_position,
            "marker_changed": self.set_marker_position,
            "left_title": left_title,
            "right_title": right_title,
        }
        if kind == "Text":
            return kind, TextCompare(master, left, right, **options)
        if kind == "Table":
            return kind, TableCompare(master, left, right, **options)
        return "Binary", BinaryCompare(master, left, right, **options)

    def _prepare_folder_source(self, path: Path):
        if not is_compare_archive(path):
            return path, False
        workspace, root = extract_compare_archive(path)
        self._archive_workspaces.append(workspace)
        return root, True

    def set_marker_position(self, position: str) -> None:
        if position not in {"left", "middle", "right"}:
            return
        self.marker_position = position
        for frame in self.comparisons:
            view = getattr(frame, "view", None)
            if view is not None and hasattr(view, "set_marker_position"):
                view.set_marker_position(position)
        if not self.config_data.has_section("compare"):
            self.config_data.add_section("compare")
        self.config_data.set("compare", "marker_position", position)
        self.save_config()

    def add(self, left: Path, right: Path, requested="Auto"):
        left_container, right_container = is_compare_container(left), is_compare_container(right)
        kind = detect_compare_type(left, right) if requested == "Auto" else requested
        if left_container != right_container:
            messagebox.showerror(tr("Compare"), tr("Select two files or two folders."), parent=self); return
        if left_container and right_container:
            kind = "Folder"
        frame = self._make_frame(left, right, kind)
        install_button_tooltips(frame)
        self.notebook.add(frame, text=f"{tr(kind)}: {left.name} ↔ {right.name}")
        self.comparisons[frame] = (left, right, kind, self._signature(left, right))
        target = getattr(frame, "view", frame)
        handler = getattr(target, "apply_color_scheme", None)
        if callable(handler):
            handler(self.palette)
        handler = getattr(frame, "apply_scale", None)
        if callable(handler):
            handler(self.scale)
        self.notebook.select(frame); self.after_idle(self.activate)

    def activate(self):
        self.deiconify(); self.lift(); self.focus_force()

    def _schedule_refresh(self):
        self._refresh_job = self.after(2000, self._auto_refresh)

    def _auto_refresh(self):
        self._refresh_job = None
        if self.notebook.tabs():
            frame = self.nametowidget(self.notebook.select())
            details = self.comparisons.get(frame)
            if details:
                left, right, kind, previous = details
                current = self._signature(left, right)
                if current is not None and current != previous:
                    index = self.notebook.index(frame)
                    title = self.notebook.tab(frame)["text"]
                    self.notebook.forget(frame); self.comparisons.pop(frame, None); frame.destroy()
                    replacement = self._make_frame(left, right, kind)
                    install_button_tooltips(replacement)
                    self.notebook.add(replacement, text=title, position=index)
                    self.comparisons[replacement] = (left, right, kind, current)
                    target = getattr(replacement, "view", replacement)
                    theme_handler = getattr(target, "apply_color_scheme", None)
                    if callable(theme_handler):
                        theme_handler(self.palette)
                    handler = getattr(replacement, "apply_scale", None)
                    if callable(handler):
                        handler(self.scale)
        if self.winfo_exists(): self._schedule_refresh()

    def _navigate(self, method):
        frame = self.nametowidget(self.notebook.select())
        pending = [frame]
        while pending:
            widget = pending.pop(0)
            handler = getattr(widget, method, None)
            if callable(handler):
                handler(); return
            pending.extend(widget.winfo_children())

    def focus_search(self):
        frame = self.nametowidget(self.notebook.select())
        pending = [frame]
        while pending:
            widget = pending.pop(0)
            if hasattr(widget, "focus_search"): return widget.focus_search()
            pending.extend(widget.winfo_children())
        return "break"

    def close(self):
        if self._refresh_job is not None:
            self.after_cancel(self._refresh_job); self._refresh_job = None
        if not self.config_data.has_section("compare"): self.config_data.add_section("compare")
        self.config_data.set("compare", "geometry", self.geometry())
        for frame in list(self.comparisons):
            if hasattr(frame, "cancel_scan"): frame.cancel_scan()
        self.save_config(); self.destroy()
        for workspace in self._archive_workspaces:
            workspace.cleanup()
        self._archive_workspaces.clear()

    def close_active(self):
        tabs = self.notebook.tabs()
        current = self.notebook.select()
        widget = self.nametowidget(current)
        if hasattr(widget, "close_nested_detail") and widget.close_nested_detail():
            return
        if hasattr(widget, "cancel_scan") and widget.cancel_scan():
            return
        if len(tabs) <= 1:
            self.close()
            return
        self.notebook.forget(current)
        self.comparisons.pop(widget, None)
        widget.destroy()


import io
import keyword
import re
import tokenize
import tkinter as tk
import tkinter.font as tkfont
from pathlib import Path
from tkinter import ttk


TEXT_EXTENSIONS = {
    ".txt", ".md", ".csv", ".tsv", ".log", ".py", ".ini", ".json", ".xml",
    ".yaml", ".yml", ".html", ".htm", ".css", ".js", ".ps1", ".bat", ".cmd",
    ".sql", ".srt", ".cfg", ".conf",
}
TEXT_LIMIT = 8 * 1024 * 1024
HEX_LIMIT = 1024 * 1024
SYNTAX_BATCH_SIZE = 600

CODE_EXTENSIONS = {
    ".py": "Python", ".js": "JavaScript", ".jsx": "JavaScript",
    ".ts": "TypeScript", ".tsx": "TypeScript", ".java": "Java",
    ".c": "C", ".h": "C", ".cpp": "C++", ".cc": "C++", ".hpp": "C++",
    ".cs": "C#", ".go": "Go", ".rs": "Rust", ".php": "PHP",
    ".sql": "SQL", ".ps1": "PowerShell", ".sh": "Shell",
    ".bat": "Batch", ".cmd": "Batch", ".json": "JSON",
    ".xml": "XML", ".html": "HTML", ".htm": "HTML", ".xhtml": "HTML",
    ".svg": "SVG", ".css": "CSS", ".scss": "SCSS",
    ".yaml": "YAML", ".yml": "YAML", ".ini": "INI",
    ".cfg": "Config", ".conf": "Config", ".md": "Markdown",
}

COMMON_KEYWORDS = set("""
abstract as async await break case catch class const continue def default delete do
else enum except export extends false finally for from function if import in
interface lambda let match namespace new nil none null package pass private
protected public raise return self static struct super switch this throw true try
type typeof using var void while with yield select range where
""".split())


def _line_offsets(text: str) -> list[int]:
    offsets, total = [0], 0
    for line in text.splitlines(keepends=True):
        total += len(line); offsets.append(total)
    return offsets


def syntax_spans(text: str, suffix: str) -> list[tuple[int, int, str]]:
    """Return lightweight syntax spans without requiring third-party packages."""
    suffix = suffix.casefold()
    if suffix == ".py":
        offsets = _line_offsets(text)
        spans = []
        try:
            for token in tokenize.generate_tokens(io.StringIO(text).readline):
                if token.type not in (tokenize.COMMENT, tokenize.STRING, tokenize.NUMBER,
                                      tokenize.NAME, tokenize.OP):
                    continue
                tag = {
                    tokenize.COMMENT: "syntax_comment", tokenize.STRING: "syntax_string",
                    tokenize.NUMBER: "syntax_number", tokenize.OP: "syntax_operator",
                }.get(token.type)
                if token.type == tokenize.NAME and keyword.iskeyword(token.string):
                    tag = "syntax_keyword"
                if tag and token.start[0] <= len(offsets) and token.end[0] <= len(offsets):
                    start = offsets[token.start[0] - 1] + token.start[1]
                    end = offsets[token.end[0] - 1] + token.end[1]
                    spans.append((start, end, tag))
        except (tokenize.TokenError, IndentationError):
            pass
        return spans

    spans = []
    comment_pattern = (r"(?m)(?://|;|--).*?$|/\*[\s\S]*?\*/|<!--[\s\S]*?-->"
                       if suffix == ".md" else
                       r"(?m)(?://|#|;|--).*?$|/\*[\s\S]*?\*/|<!--[\s\S]*?-->")
    patterns = [
        ("syntax_comment", comment_pattern),
        ("syntax_string", r"""(?s:"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*')"""),
        ("syntax_number", r"\b(?:0x[0-9a-fA-F]+|\d+(?:\.\d+)?)\b"),
    ]
    if suffix in {".xml", ".html", ".htm", ".xhtml", ".svg"}:
        patterns.append(("syntax_keyword", r"</?[\w:-]+|/?>"))
    elif suffix == ".md":
        patterns.extend([
            ("syntax_heading", r"(?m)^#{1,6}\s+.*$"),
            ("syntax_keyword", r"(?m)^(?:\s*[-*+]\s+|\s*\d+\.\s+|>\s+)|`{1,3}"),
            ("syntax_link", r"\[[^\]]+\]\([^)]+\)"),
        ])
    else:
        words = COMMON_KEYWORDS
        patterns.append(("syntax_keyword", r"\b(?:" + "|".join(sorted(map(re.escape, words))) + r")\b"))
    occupied = [False] * len(text)
    for tag, pattern in patterns:
        for match in re.finditer(pattern, text, re.IGNORECASE):
            start, end = match.span()
            if start < end and not any(occupied[start:end]):
                spans.append((start, end, tag))
                occupied[start:end] = [True] * (end - start)
    return spans


def render_markdown(text: str) -> tuple[str, list[tuple[int, int, str]]]:
    """Render common Markdown structure into readable Tk text and style spans."""
    output, spans, in_code, length = [], [], False, 0

    def append(value: str, tag: str | None = None) -> None:
        nonlocal length
        start = length; output.append(value); length += len(value)
        if tag and value: spans.append((start, start + len(value), tag))

    def inline(value: str) -> None:
        pattern = re.compile(r"(\*\*.+?\*\*|__.+?__|`[^`]+`|\[[^\]]+\]\([^)]+\)|(?<!\*)\*[^*]+\*)")
        cursor = 0
        for match in pattern.finditer(value):
            append(value[cursor:match.start()])
            token = match.group()
            if token.startswith(("**", "__")):
                append(token[2:-2], "markdown_bold")
            elif token.startswith("`"):
                append(token[1:-1], "markdown_code")
            elif token.startswith("["):
                label, url = re.match(r"\[([^\]]+)\]\(([^)]+)\)", token).groups()
                append(label, "markdown_link"); append(f" ({url})", "markdown_url")
            else:
                append(token[1:-1], "markdown_italic")
            cursor = match.end()
        append(value[cursor:])

    for raw in text.splitlines():
        if raw.strip().startswith("```"):
            in_code = not in_code
            continue
        if in_code:
            append(raw + "\n", "markdown_code")
            continue
        heading = re.match(r"^(#{1,6})\s+(.*)$", raw)
        if heading:
            start = length; inline(heading.group(2)); append("\n")
            spans.append((start, length - 1,
                          f"markdown_h{min(3, len(heading.group(1)))}"))
        elif re.match(r"^\s*[-*+]\s+", raw):
            append("• ", "markdown_bullet"); inline(re.sub(r"^\s*[-*+]\s+", "", raw)); append("\n")
        elif raw.startswith(">"):
            append("│ ", "markdown_quote"); inline(raw[1:].lstrip()); append("\n")
        elif re.match(r"^\s*(?:---+|\*\*\*+)\s*$", raw):
            append("────────────────────────\n", "markdown_rule")
        else:
            inline(raw); append("\n")
    return "".join(output), spans


def looks_text(path: Path, sample: bytes) -> bool:
    if path.suffix.casefold() in TEXT_EXTENSIONS:
        return True
    if not sample:
        return True
    if sample.startswith((b"\xff\xfe", b"\xfe\xff", b"\xef\xbb\xbf")):
        return True
    return b"\x00" not in sample and sum(byte < 9 or 13 < byte < 32 for byte in sample) / len(sample) < 0.05


def decode_text(data: bytes) -> tuple[str, str]:
    if data.startswith((b"\xff\xfe", b"\xfe\xff")):
        return data.decode("utf-16", errors="replace"), "UTF-16"
    try:
        return data.decode("utf-8-sig"), "UTF-8"
    except UnicodeDecodeError:
        return data.decode("cp1252", errors="replace"), "Windows-1252"


def render_hex(data: bytes) -> str:
    lines = []
    for offset in range(0, len(data), 16):
        chunk = data[offset:offset + 16]
        hexadecimal = " ".join(f"{byte:02X}" for byte in chunk)
        printable = "".join(chr(byte) if 32 <= byte < 127 else "." for byte in chunk)
        lines.append(f"{offset:08X}  {hexadecimal:<47}  |{printable}|\n")
    return "".join(lines)


class PreviewWindow(tk.Toplevel):
    def __init__(self, master, config, save_config, files, selected,
                 extension_effect: bool = True) -> None:
        super().__init__(master)
        self.config_data, self.save_config = config, save_config
        self.files = list(files)
        self.index = self.files.index(selected) if selected in self.files else 0
        self.mode_values = {tr("Auto"): "Auto", tr("Text"): "Text", tr("Hex"): "Hex"}
        self.mode_var = tk.StringVar(value=tr("Auto"))
        self.wrap_var = tk.BooleanVar(value=config.getboolean("preview", "wrap", fallback=False))
        self.case_var = tk.BooleanVar(value=False)
        self.search_var = tk.StringVar()
        self.extension_effect = bool(extension_effect)
        self.markdown_values = {tr("Markdown Source"): "source", tr("Rendered"): "rendered"}
        self.markdown_var = tk.StringVar(value=tr("Rendered"))
        self.matches = []
        self.match_index = -1
        self._signature = None
        self._refresh_job = None
        self._span_job = None
        self._pending_spans = []
        self.title(tr("PFC Preview"))
        self.geometry(config.get("preview", "geometry", fallback="1100x720"))
        self.minsize(640, 400)
        self.protocol("WM_DELETE_WINDOW", self.close)
        self.bind("<Escape>", lambda _event: self.close())
        self.bind("<Control-f>", lambda _event: self.focus_search())
        self.bind("<Alt-Left>", lambda _event: self.previous_file())
        self.bind("<Alt-Right>", lambda _event: self.next_file())

        toolbar = ttk.Frame(self, padding=(6, 5)); toolbar.pack(fill="x")
        file_row = ttk.Frame(toolbar); file_row.pack(fill="x")
        ttk.Button(file_row, text=tr("File <<"), command=self.previous_file).pack(side="left")
        ttk.Button(file_row, text=tr("File >>"), command=self.next_file).pack(side="left", padx=(3, 10))
        ttk.Label(file_row, text=tr("View:")).pack(side="left", padx=(4, 3))
        self.mode_combo = ttk.Combobox(file_row, width=7, state="readonly", textvariable=self.mode_var,
                                       values=tuple(self.mode_values))
        self.mode_combo.pack(side="left")
        self.mode_combo.bind("<<ComboboxSelected>>", lambda _event: self.load())
        ttk.Checkbutton(file_row, text=tr("Wrap"), variable=self.wrap_var,
                        command=self.set_wrap).pack(side="left", padx=10)
        self.markdown_frame = ttk.Frame(file_row)
        ttk.Label(self.markdown_frame, text="Markdown:").pack(side="left", padx=(2, 3))
        self.markdown_combo = ttk.Combobox(self.markdown_frame, width=10, state="readonly",
                                           textvariable=self.markdown_var,
                                           values=tuple(self.markdown_values))
        self.markdown_combo.pack(side="left")
        self.markdown_combo.bind("<<ComboboxSelected>>", lambda _event: self.load())
        find_row = ttk.Frame(toolbar); find_row.pack(fill="x", pady=(4, 0))
        ttk.Label(find_row, text=tr("Find:")).pack(side="left", padx=(0, 3))
        self.search = ttk.Entry(find_row, textvariable=self.search_var, width=24)
        self.search.pack(side="left", fill="x", expand=True)
        self.search.bind("<Return>", lambda _event: self.find_next())
        self.search.bind("<Shift-Return>", lambda _event: self.find_previous())
        find_actions = ttk.Frame(toolbar); find_actions.pack(fill="x", pady=(3, 0))
        ttk.Button(find_actions, text=tr("Find Prev"), command=self.find_previous).pack(side="left")
        ttk.Button(find_actions, text=tr("Find Next"), command=self.find_next).pack(side="left", padx=(3, 0))
        ttk.Checkbutton(find_actions, text=tr("Case sensitive"), variable=self.case_var,
                        command=self.find_all).pack(side="left", padx=(8, 0))

        frame = ttk.Frame(self); frame.pack(fill="both", expand=True)
        self.text = tk.Text(frame, wrap="word" if self.wrap_var.get() else "none", undo=False,
                            font=tkfont.nametofont("TkFixedFont"), padx=8, pady=6)
        vertical = ttk.Scrollbar(frame, orient="vertical", command=self.text.yview)
        horizontal = ttk.Scrollbar(frame, orient="horizontal", command=self.text.xview)
        self.text.configure(yscrollcommand=vertical.set, xscrollcommand=horizontal.set)
        horizontal.pack(side="bottom", fill="x")
        self.text.pack(side="left", fill="both", expand=True); vertical.pack(side="right", fill="y")
        self.text.tag_configure("match", background="#fff0a6")
        self.text.tag_configure("current_match", background="#ffb347")
        self._configure_effect_fonts()
        self.status = ttk.Label(self, anchor="w", padding=(7, 4)); self.status.pack(fill="x")
        self.apply_color_scheme(getattr(master, "palette", color_scheme("light")))
        install_button_tooltips(self)
        self.load()
        self._schedule_refresh()
        self.after_idle(self.activate)

    def apply_language(self, old_language: str) -> None:
        mode = self.mode_values.get(self.mode_var.get(), self.mode_var.get())
        retranslate_widgets(self, old_language)
        self.mode_values = {tr("Auto"): "Auto", tr("Text"): "Text", tr("Hex"): "Hex"}
        self.mode_combo.configure(values=tuple(self.mode_values))
        self.mode_var.set(next(label for label, value in self.mode_values.items() if value == mode))
        markdown_mode = self.markdown_values.get(self.markdown_var.get(), "rendered")
        self.markdown_values = {tr("Markdown Source"): "source", tr("Rendered"): "rendered"}
        self.markdown_combo.configure(values=tuple(self.markdown_values))
        self.markdown_var.set(next(label for label, value in self.markdown_values.items()
                                   if value == markdown_mode))
        self.load()

    def _configure_effect_fonts(self) -> None:
        base = tkfont.nametofont("TkFixedFont")
        family, size = base.cget("family"), base.cget("size")
        self.effect_fonts = {
            "bold": tkfont.Font(self, family=family, size=size, weight="bold"),
            "italic": tkfont.Font(self, family=family, size=size, slant="italic"),
            "h1": tkfont.Font(self, family=family, size=max(size + 6, round(size * 1.55)), weight="bold"),
            "h2": tkfont.Font(self, family=family, size=max(size + 4, round(size * 1.35)), weight="bold"),
            "h3": tkfont.Font(self, family=family, size=max(size + 2, round(size * 1.18)), weight="bold"),
        }

    def apply_scale(self, _scale: float) -> None:
        self._configure_effect_fonts()
        self.apply_color_scheme(self.palette)

    def apply_color_scheme(self, palette) -> None:
        self.palette = palette
        self.configure(background=palette["window"])
        self.text.configure(background=palette["content"], foreground=palette["text"],
                            insertbackground=palette["text"], selectbackground=palette["selection"],
                            selectforeground="#ffffff")
        self.text.tag_configure("match", background=palette["match"], foreground=palette["text"])
        self.text.tag_configure("current_match", background=palette["current_diff"], foreground="#ffffff")
        dark = sum(int(palette["content"][i:i + 2], 16) for i in (1, 3, 5)) < 330
        colors = {
            "syntax_keyword": "#6cb6ff" if dark else "#005cc5",
            "syntax_string": "#a5d6a7" if dark else "#116329",
            "syntax_comment": "#9aa7b0" if dark else "#66737d",
            "syntax_number": "#f2a65a" if dark else "#b35900",
            "syntax_operator": "#d2a8ff" if dark else "#7a3e9d",
            "syntax_heading": "#79c0ff" if dark else "#174f86",
            "syntax_link": "#58a6ff" if dark else "#0969da",
        }
        for tag, foreground in colors.items():
            self.text.tag_configure(tag, foreground=foreground)
        self.text.tag_configure("markdown_bold", font=self.effect_fonts["bold"])
        self.text.tag_configure("markdown_italic", font=self.effect_fonts["italic"])
        self.text.tag_configure("markdown_code", background=palette["surface_alt"],
                                foreground=colors["syntax_string"])
        self.text.tag_configure("markdown_link", foreground=colors["syntax_link"], underline=True)
        self.text.tag_configure("markdown_url", foreground=palette["muted"])
        self.text.tag_configure("markdown_quote", foreground=palette["muted"])
        self.text.tag_configure("markdown_bullet", foreground=colors["syntax_keyword"])
        self.text.tag_configure("markdown_rule", foreground=palette["border"])
        for level in (1, 2, 3):
            self.text.tag_configure(f"markdown_h{level}", font=self.effect_fonts[f"h{level}"],
                                    foreground=colors["syntax_heading"], spacing1=8, spacing3=4)

    @property
    def path(self) -> Path:
        return self.files[self.index]

    def show(self, files, selected) -> None:
        self.files = list(files)
        self.index = self.files.index(selected) if selected in self.files else 0
        self.load(); self.activate()

    def set_extension_effect(self, enabled: bool) -> None:
        self.extension_effect = bool(enabled)
        self.load()

    def _apply_spans(self, spans: list[tuple[int, int, str]]) -> None:
        self._pending_spans = list(spans)
        self._apply_span_batch()

    def _apply_span_batch(self) -> None:
        self._span_job = None
        batch, self._pending_spans = (
            self._pending_spans[:SYNTAX_BATCH_SIZE],
            self._pending_spans[SYNTAX_BATCH_SIZE:])
        grouped: dict[str, list[str]] = {}
        for start, end, tag in batch:
            grouped.setdefault(tag, []).extend((f"1.0+{start}c", f"1.0+{end}c"))
        for tag, ranges in grouped.items():
            self.text.tag_add(tag, *ranges)
        if self._pending_spans and self.winfo_exists():
            self._span_job = self.after(8, self._apply_span_batch)

    def activate(self) -> None:
        self.deiconify(); self.lift(); self.focus_force(); self.text.focus_set()

    def _path_signature(self):
        try:
            path = self.path
            if path.is_dir():
                return tuple(sorted((item.name, item.stat().st_mtime_ns, item.stat().st_size)
                                    for item in path.iterdir()))
            stat = path.stat(); return stat.st_mtime_ns, stat.st_size
        except OSError:
            return None

    def _schedule_refresh(self) -> None:
        self._refresh_job = self.after(2000, self._auto_refresh)

    def _auto_refresh(self) -> None:
        self._refresh_job = None
        signature = self._path_signature()
        if signature != self._signature:
            self.load()
        if self.winfo_exists(): self._schedule_refresh()

    def load(self) -> None:
        path = self.path
        if self._span_job is not None:
            self.after_cancel(self._span_job); self._span_job = None
        self._pending_spans = []
        self.title(f"{tr('PFC Preview')} — {path.name}")
        self.text.configure(state="normal"); self.text.delete("1.0", "end")
        mode = self.mode_values.get(self.mode_var.get(), self.mode_var.get())
        encoding, truncated, spans = "", False, []
        try:
            if path.is_dir():
                entries = sorted(path.iterdir(), key=lambda item: (not item.is_dir(), item.name.casefold()))
                content = f"{tr('Folder')}: {path}\n\n" + "\n".join(
                    ("[DIR]  " if item.is_dir() else "       ") + item.name for item in entries)
                shown_mode = tr("Folder view")
            else:
                size = path.stat().st_size
                with path.open("rb") as stream:
                    sample = stream.read(4096); stream.seek(0)
                    chosen = "Text" if mode == "Text" or (mode == "Auto" and looks_text(path, sample)) else "Hex"
                    limit = TEXT_LIMIT if chosen == "Text" else HEX_LIMIT
                    data = stream.read(limit + 1)
                truncated = len(data) > limit; data = data[:limit]
                if chosen == "Text":
                    content, encoding = decode_text(data); shown_mode = tr("Text")
                    suffix = path.suffix.casefold()
                    markdown_mode = self.markdown_values.get(self.markdown_var.get(), "rendered")
                    if self.extension_effect and suffix == ".md" and markdown_mode == "rendered":
                        content, spans = render_markdown(content)
                        shown_mode = tr("Markdown rendered")
                    elif self.extension_effect and suffix in CODE_EXTENSIONS:
                        spans = syntax_spans(content, suffix)
                        shown_mode = tr("{language} syntax", language=CODE_EXTENSIONS[suffix])
                else:
                    content = render_hex(data); shown_mode = tr("Hex")
                size = path.stat().st_size
            self.text.insert("1.0", content)
            self._apply_spans(spans)
            show_markdown = (path.is_file() and path.suffix.casefold() == ".md"
                             and chosen == "Text" and self.extension_effect)
            if show_markdown:
                self.markdown_frame.pack(side="left", padx=(4, 0))
            else:
                self.markdown_frame.pack_forget()
            size = path.stat().st_size if path.is_file() else 0
            detail = f"{shown_mode}   {size:,} bytes"
            if encoding: detail += f"   {encoding}"
            if truncated: detail += "   Preview truncated"
            self.status.configure(text=f"{detail}   {path}")
        except OSError as exc:
            self.text.insert("1.0", f"{tr('Cannot preview file')}:\n{exc}")
            self.status.configure(text=str(path))
        self.text.configure(state="disabled")
        self.text.tag_raise("match"); self.text.tag_raise("current_match")
        self._signature = self._path_signature()
        self.find_all()

    def set_wrap(self) -> None:
        self.text.configure(wrap="word" if self.wrap_var.get() else "none")

    def focus_search(self) -> str:
        self.search.focus_set(); self.search.selection_range(0, "end"); return "break"

    def find_all(self) -> None:
        self.text.tag_remove("match", "1.0", "end"); self.text.tag_remove("current_match", "1.0", "end")
        self.matches, self.match_index = [], -1
        needle = self.search_var.get()
        if not needle: return
        start = "1.0"
        while True:
            found = self.text.search(needle, start, stopindex="end", nocase=not self.case_var.get())
            if not found: break
            end = f"{found}+{len(needle)}c"; self.matches.append((found, end))
            self.text.tag_add("match", found, end); start = end

    def _find(self, direction: int) -> str:
        previous_index = self.match_index
        self.find_all()
        if not self.matches:
            self.status.configure(text=f"{tr('No matches')}   {self.path}"); return "break"
        self.match_index = (previous_index + direction) % len(self.matches)
        start, end = self.matches[self.match_index]
        self.text.tag_remove("current_match", "1.0", "end")
        self.text.tag_add("current_match", start, end); self.text.see(start)
        self.status.configure(text=f"{tr('Match {current} of {total}', current=self.match_index + 1, total=len(self.matches))}   {self.path}")
        return "break"

    def find_next(self) -> str: return self._find(1)
    def find_previous(self) -> str: return self._find(-1)

    def previous_file(self) -> None:
        if self.files: self.index = (self.index - 1) % len(self.files); self.load()

    def next_file(self) -> None:
        if self.files: self.index = (self.index + 1) % len(self.files); self.load()

    def close(self) -> None:
        if self._refresh_job is not None:
            self.after_cancel(self._refresh_job); self._refresh_job = None
        if self._span_job is not None:
            self.after_cancel(self._span_job); self._span_job = None
        if not self.config_data.has_section("preview"): self.config_data.add_section("preview")
        self.config_data.set("preview", "geometry", self.geometry())
        self.config_data.set("preview", "wrap", str(self.wrap_var.get()).lower())
        self.save_config(); self.destroy()


import fnmatch
import os
import queue
import threading
import time
import zipfile
from datetime import datetime, timedelta
from pathlib import Path
import tkinter as tk
import tkinter.font as tkfont
from tkinter import messagebox, ttk



OFFICE_XML = {".docx", ".xlsx", ".pptx", ".odt", ".ods", ".odp"}
CONTENT_LIMIT = 32 * 1024 * 1024
RESULT_LIMIT = 10000


def search_row_height(linespace: int, scale: float) -> int:
    """Leave enough vertical padding for scaled Search result text."""
    return max(24, int(linespace) + max(8, round(6 * float(scale))))


def search_column_widths(available: int, desired: dict[str, int]) -> dict[str, int]:
    """Fit result columns while reserving useful space for both name and folder."""
    available = max(520, int(available))
    fixed = {
        "size": min(max(desired.get("size", 80), 72), 125),
        "modified": min(max(desired.get("modified", 150), 148), 200),
        "ext": min(max(desired.get("ext", 54), 48), 105),
    }
    flexible = max(280, available - sum(fixed.values()) - 8)
    wanted_name = min(max(desired.get("name", 160), 130), int(available * .48))
    wanted_folder = min(max(desired.get("folder", 220), 150), int(available * .52))
    wanted_total = wanted_name + wanted_folder
    if wanted_total <= flexible:
        name = wanted_name
        folder = flexible - name
    else:
        name = max(130, round(flexible * wanted_name / wanted_total))
        folder = max(150, flexible - name)
        if name + folder > flexible:
            name = max(130, flexible - folder)
    return {"name": name, "folder": folder, **fixed}


def name_matches(name: str, masks: str, case_sensitive: bool) -> bool:
    patterns = [part.strip() for part in masks.split(";") if part.strip()] or ["*"]
    patterns = [pattern if any(char in pattern for char in "*?[]") else f"*{pattern}*" for pattern in patterns]
    if not case_sensitive:
        name, patterns = name.casefold(), [pattern.casefold() for pattern in patterns]
    return any(fnmatch.fnmatchcase(name, pattern) for pattern in patterns)


def content_matches(path: Path, needle: str, case_sensitive: bool) -> bool:
    if not needle: return True
    target = needle if case_sensitive else needle.casefold()
    try:
        if path.suffix.casefold() in OFFICE_XML and zipfile.is_zipfile(path):
            with zipfile.ZipFile(path) as archive:
                chunks = []
                for info in archive.infolist():
                    if info.filename.endswith(".xml") and sum(map(len, chunks)) < CONTENT_LIMIT:
                        chunks.append(archive.read(info)[:CONTENT_LIMIT])
                data = b" ".join(chunks)[:CONTENT_LIMIT]
        else:
            with path.open("rb") as stream: data = stream.read(CONTENT_LIMIT)
        if b"\x00" in data[:4096] and not data.startswith((b"\xff\xfe", b"\xfe\xff")): return False
        if data.startswith((b"\xff\xfe", b"\xfe\xff")): text = data.decode("utf-16", errors="replace")
        else:
            try: text = data.decode("utf-8-sig")
            except UnicodeDecodeError: text = data.decode("cp1252", errors="replace")
        return target in (text if case_sensitive else text.casefold())
    except (OSError, zipfile.BadZipFile):
        return False


class SearchWindow(tk.Toplevel):
    def __init__(self, master, config, save_config, start_path, on_go, on_preview,
                 on_compare=None, on_send_listing=None):
        super().__init__(master)
        self.config_data, self.save_config = config, save_config
        self.on_go, self.on_preview = on_go, on_preview
        self.on_compare, self.on_send_listing = on_compare, on_send_listing
        self.results, self.worker = [], None
        self.item_data = {}
        self.sort_column, self.sort_reverse = "name", False
        self.cancel_event = threading.Event(); self.messages = queue.Queue(); self.poll_job = None
        self._column_resize_job = None
        self._column_desired = {}
        self._progress_started = 0.0
        self._progress_target = 0.0
        self._progress_displayed = 0.0
        self.path_var = tk.StringVar(value=str(start_path))
        self.mask_var = tk.StringVar(value=config.get("search", "mask", fallback="*"))
        self.content_var = tk.StringVar(value=config.get("search", "content", fallback=""))
        self.case_var = tk.BooleanVar(value=config.getboolean("search", "case_sensitive", fallback=False))
        saved_depth = config.get("search", "depth", fallback="All")
        self.depth_values = {tr("Current"): "Current", "1": "1", "2": "2", "3": "3", "5": "5", tr("All"): "All"}
        self.depth_var = tk.StringVar(value=next((label for label, value in self.depth_values.items()
                                                  if value == saved_depth), tr("All")))
        self.files_var = tk.BooleanVar(value=config.getboolean("search", "files", fallback=True))
        self.folders_var = tk.BooleanVar(value=config.getboolean("search", "folders", fallback=True))
        self.min_size_var = tk.StringVar(value=config.get("search", "min_size_kb", fallback=""))
        self.max_size_var = tk.StringVar(value=config.get("search", "max_size_kb", fallback=""))
        self.days_var = tk.StringVar(value=config.get("search", "modified_days", fallback=""))
        self.title(tr("PFC Search")); self.geometry(config.get("search", "geometry", fallback="1100x720")); self.minsize(720, 480)
        self.protocol("WM_DELETE_WINDOW", self.close); self.bind("<Escape>", lambda _e: self.escape())
        self.bind("<F3>", lambda _e: self.preview_selected())
        self.bind("<F9>", lambda _e: self.compare_selected())

        form = ttk.Frame(self, padding=7); form.pack(fill="x")
        self.mask_entry = None
        for row, (label, variable) in enumerate((("Start in:", self.path_var), ("Name/mask:", self.mask_var),
                                                 ("Containing text:", self.content_var))):
            ttk.Label(form, text=tr(label)).grid(row=row, column=0, sticky="w", padx=(0, 5), pady=2)
            entry = ttk.Entry(form, textvariable=variable); entry.grid(row=row, column=1, columnspan=7, sticky="ew", pady=2)
            entry.bind("<Return>", lambda _event: self.start())
            if row == 1: self.mask_entry = entry
        options = ttk.Frame(form); options.grid(row=3, column=0, columnspan=8, sticky="ew", pady=(5, 2))
        ttk.Label(options, text=tr("Depth:")).pack(side="left")
        self.depth_combo = ttk.Combobox(options, textvariable=self.depth_var, state="readonly", width=8,
                                        values=tuple(self.depth_values))
        self.depth_combo.pack(side="left", padx=(3, 10))
        ttk.Checkbutton(options, text=tr("Files"), variable=self.files_var).pack(side="left")
        ttk.Checkbutton(options, text=tr("Folders"), variable=self.folders_var).pack(side="left", padx=(3, 10))
        ttk.Checkbutton(options, text=tr("Case sensitive"), variable=self.case_var).pack(side="left")
        advanced = ttk.Frame(form); advanced.grid(row=4, column=0, columnspan=8, sticky="ew", pady=2)
        ttk.Label(advanced, text=tr("Size KB min:")).pack(side="left")
        ttk.Entry(advanced, textvariable=self.min_size_var, width=9).pack(side="left", padx=(3, 8))
        ttk.Label(advanced, text=tr("max:")).pack(side="left")
        ttk.Entry(advanced, textvariable=self.max_size_var, width=9).pack(side="left", padx=(3, 12))
        ttk.Label(advanced, text=tr("Modified within days:")).pack(side="left")
        ttk.Entry(advanced, textvariable=self.days_var, width=7).pack(side="left", padx=3)
        self.criteria_label = ttk.Label(form, anchor="w")
        self.criteria_label.grid(row=5, column=0, columnspan=8, sticky="ew", pady=(4, 0))
        actions = ttk.Frame(form); actions.grid(row=6, column=0, columnspan=8, sticky="ew", pady=(5, 0))
        self.find_button = ttk.Button(actions, text=tr("Find"), command=self.start); self.find_button.pack(side="left")
        self.cancel_button = ttk.Button(actions, text=tr("Cancel"), command=self.cancel, state="disabled"); self.cancel_button.pack(side="left", padx=3)
        ttk.Button(actions, text=tr("Clear Filters"), command=self.clear_filters).pack(side="left", padx=(3, 9))
        ttk.Button(actions, text=tr("Go to File"), command=self.go_selected).pack(side="left", padx=(12, 3))
        ttk.Button(actions, text=tr("Preview"), command=self.preview_selected).pack(side="left")
        ttk.Button(actions, text=tr("Compare"), command=self.compare_selected).pack(side="left", padx=3)
        ttk.Button(actions, text=tr("Send Listing to New Tab"),
                   command=self.send_listing).pack(side="left", padx=(0, 3))
        ttk.Button(actions, text=tr("Copy Path"), command=self.copy_paths).pack(side="left", padx=3)
        self.status = ttk.Label(actions, anchor="e"); self.status.pack(side="right", fill="x", expand=True)
        self.progress = ttk.Progressbar(form, mode="determinate", value=0)
        self.progress.grid(row=7, column=0, columnspan=8, sticky="ew", pady=(5, 0))
        self.progress_eta = ttk.Label(form, text=tr("Estimated time remaining: calculating…"), anchor="w")
        self.progress_eta.grid(row=8, column=0, columnspan=8, sticky="ew", pady=(3, 0))
        form.columnconfigure(1, weight=1)

        body = ttk.Frame(self); body.pack(fill="both", expand=True)
        columns = ("folder", "size", "modified", "ext")
        self.tree = ttk.Treeview(body, columns=columns, show="tree headings", selectmode="extended",
                                 style="PFCSearch.Treeview")
        self.tree.heading("#0", text=tr("Name") + " ▲", command=lambda: self.change_sort("name")); self.tree.column("#0", width=260, stretch=False)
        for col, width in (("folder", 460), ("size", 90), ("modified", 140), ("ext", 60)):
            self.tree.heading(col, text=tr(col.title()), command=lambda c=col: self.change_sort(c))
            self.tree.column(col, width=width, anchor="e" if col == "size" else "w", stretch=False)
        scroll = ttk.Scrollbar(body, orient="vertical", command=self.tree.yview); self.tree.configure(yscrollcommand=scroll.set)
        self.tree.pack(side="left", fill="both", expand=True); scroll.pack(side="right", fill="y")
        self.tree.bind("<Double-1>", lambda _e: self.go_selected())
        self.tree.bind("<Return>", lambda _e: self.go_selected())
        self.tree.bind("<Configure>", self._schedule_column_resize)
        for variable in (self.mask_var, self.content_var, self.case_var, self.depth_var,
                         self.files_var, self.folders_var, self.min_size_var,
                         self.max_size_var, self.days_var):
            variable.trace_add("write", self._update_criteria_summary)
        self._update_criteria_summary()
        self.apply_color_scheme(getattr(master, "palette", color_scheme("light")))
        install_button_tooltips(self); self.after_idle(self.activate)

    def _reset_column_measurements(self) -> None:
        font = tkfont.nametofont("TkDefaultFont")
        heading = tkfont.nametofont("TkHeadingFont")
        self._column_desired = {
            "name": heading.measure(tr("Name") + " ▲") + 32,
            "folder": heading.measure(tr("Folder")) + 32,
            "size": heading.measure(tr("Size")) + 28,
            "modified": heading.measure(tr("Modified")) + 28,
            "ext": heading.measure(tr("Ext")) + 28,
        }
        for iid in self.tree.get_children():
            values = self.tree.item(iid, "values")
            if len(values) >= 4:
                self._measure_result(str(self.tree.item(iid, "text")), *map(str, values[:4]),
                                     schedule=False)
        self._schedule_column_resize()

    def _measure_result(self, name: str, folder: str, size: str, modified: str, ext: str,
                        schedule: bool = True) -> None:
        font = tkfont.nametofont("TkDefaultFont")
        for key, value in (("name", name), ("folder", folder), ("size", size),
                           ("modified", modified), ("ext", ext)):
            self._column_desired[key] = max(self._column_desired.get(key, 0),
                                            font.measure(value) + (38 if key == "name" else 24))
        if schedule:
            self._schedule_column_resize()

    def _schedule_column_resize(self, _event=None) -> None:
        if self._column_resize_job is not None:
            self.after_cancel(self._column_resize_job)
        self._column_resize_job = self.after(90, self._resize_columns)

    def _resize_columns(self) -> None:
        self._column_resize_job = None
        widths = search_column_widths(self.tree.winfo_width(), self._column_desired)
        self.tree.column("#0", width=widths["name"])
        for column in ("folder", "size", "modified", "ext"):
            self.tree.column(column, width=widths[column])

    def apply_color_scheme(self, palette) -> None:
        self.palette = palette
        self.configure(background=palette["window"])

    def apply_scale(self, scale: float) -> None:
        style = ttk.Style(self)
        default_font = tkfont.nametofont("TkDefaultFont")
        style.configure("PFCSearch.Treeview", font=default_font,
                        rowheight=search_row_height(default_font.metrics("linespace"), scale))
        style.configure("PFCSearch.Treeview.Heading", font=tkfont.nametofont("TkHeadingFont"))
        self._reset_column_measurements()

    def apply_language(self, old_language: str) -> None:
        depth = self.depth_values.get(self.depth_var.get(), self.depth_var.get())
        retranslate_widgets(self, old_language)
        self.depth_values = {tr("Current"): "Current", "1": "1", "2": "2", "3": "3",
                             "5": "5", tr("All"): "All"}
        self.depth_combo.configure(values=tuple(self.depth_values))
        self.depth_var.set(next(label for label, value in self.depth_values.items() if value == depth))
        self.title(tr("PFC Search"))
        self._apply_sort()
        self._reset_column_measurements()
        self._update_criteria_summary()
        if self.worker is not None and self.worker.is_alive():
            self.status.configure(text=tr("Searching…"))
        elif self.results:
            self.status.configure(text=tr("{count} found", count=len(self.results)))

    def activate(self):
        self.deiconify(); self.lift(); self.focus_force()
        self._update_criteria_summary()
        if self.mask_entry is not None:
            self.mask_entry.focus_set(); self.mask_entry.selection_range(0, "end"); self.mask_entry.icursor("end")

    def _update_criteria_summary(self, *_args) -> None:
        if not hasattr(self, "criteria_label"):
            return
        mask = self.mask_var.get().strip() or "*"
        scope = "/".join(label for label, enabled in (
            (tr("Files"), self.files_var.get()), (tr("Folders"), self.folders_var.get())) if enabled) or "—"
        parts = [f"{tr('Name/mask:')} {mask}", scope,
                 f"{tr('Depth:')} {self.depth_var.get()}"]
        if self.content_var.get().strip():
            parts.append(f"{tr('Containing text:')} {self.content_var.get().strip()}")
        if self.min_size_var.get().strip() or self.max_size_var.get().strip():
            parts.append(f"{tr('Size')}: {self.min_size_var.get().strip() or '0'}–{self.max_size_var.get().strip() or '∞'} KB")
        if self.days_var.get().strip():
            parts.append(f"{tr('Modified within days:')} {self.days_var.get().strip()}")
        if self.case_var.get():
            parts.append(tr("Case sensitive"))
        self.criteria_label.configure(text=f"{tr('Filters:')} " + " · ".join(parts))

    def clear_filters(self) -> None:
        self.mask_var.set("*")
        self.content_var.set("")
        self.case_var.set(False)
        self.depth_var.set(tr("All"))
        self.files_var.set(True)
        self.folders_var.set(True)
        self.min_size_var.set("")
        self.max_size_var.set("")
        self.days_var.set("")
        self.status.configure(text=tr("Filters cleared"))
        self.mask_entry.focus_set()
        self.mask_entry.selection_range(0, "end")

    def change_sort(self, column):
        self.sort_reverse = not self.sort_reverse if self.sort_column == column else False
        self.sort_column = column
        self._apply_sort()

    def _apply_sort(self):
        column = self.sort_column
        labels = {"name": tr("Name"), "folder": tr("Folder"), "size": tr("Size"),
                  "modified": tr("Modified"), "ext": tr("Ext")}
        for name, label in labels.items():
            marker = (" ▲" if not self.sort_reverse else " ▼") if name == column else ""
            self.tree.heading("#0" if name == "name" else name, text=label + marker)
        for index, iid in enumerate(sorted(self.tree.get_children(),
                                            key=lambda item: self.item_data[item][column],
                                            reverse=self.sort_reverse)):
            self.tree.move(iid, "", index)

    def criteria(self):
        def number(value, factor=1):
            try: return float(value) * factor if value.strip() else None
            except ValueError: return None
        depth = self.depth_values.get(self.depth_var.get(), self.depth_var.get())
        max_depth = None if depth == "All" else (0 if depth == "Current" else int(depth))
        days = number(self.days_var.get())
        return dict(root=Path(self.path_var.get().strip().strip('"')), masks=self.mask_var.get(), content=self.content_var.get(),
                    case=self.case_var.get(), max_depth=max_depth, files=self.files_var.get(), folders=self.folders_var.get(),
                    min_size=number(self.min_size_var.get(), 1024), max_size=number(self.max_size_var.get(), 1024),
                    since=datetime.now() - timedelta(days=days) if days is not None else None)

    def start(self):
        if self.worker and self.worker.is_alive(): return
        criteria = self.criteria()
        if not criteria["root"].is_dir(): messagebox.showerror(tr("Search"), tr("Start path is not a folder."), parent=self); return
        self.tree.delete(*self.tree.get_children()); self.results=[]; self.item_data.clear(); self.cancel_event.clear()
        self._reset_column_measurements()
        self.find_button.configure(state="disabled"); self.cancel_button.configure(state="normal"); self.status.configure(text=tr("Searching…"))
        self._progress_started = time.monotonic(); self._progress_target = 0.0; self._progress_displayed = 0.0
        self.progress.stop(); self.progress.configure(mode="determinate", maximum=100, value=0)
        self.progress_eta.configure(text=tr("Estimated time remaining: calculating…"))
        self.worker = threading.Thread(target=self._search, args=(criteria,), daemon=True); self.worker.start(); self._poll()

    def _search(self, c):
        count = 0; processed_folders = 0; discovered_folders = 1
        try:
            for current, dirs, files in os.walk(c["root"]):
                if self.cancel_event.is_set(): break
                depth = len(Path(current).relative_to(c["root"]).parts)
                folder_names = list(dirs)
                if c["max_depth"] is not None and depth >= c["max_depth"]: dirs[:] = []
                discovered_folders += len(dirs)
                processed_folders += 1
                self.messages.put(("progress", processed_folders, discovered_folders))
                candidates = ([Path(current) / name for name in folder_names] if c["folders"] else []) + ([Path(current) / name for name in files] if c["files"] else [])
                for path in candidates:
                    if self.cancel_event.is_set() or count >= RESULT_LIMIT: break
                    try:
                        stat = path.stat()
                        if not name_matches(path.name, c["masks"], c["case"]): continue
                        if path.is_file() and c["min_size"] is not None and stat.st_size < c["min_size"]: continue
                        if path.is_file() and c["max_size"] is not None and stat.st_size > c["max_size"]: continue
                        if c["since"] is not None and datetime.fromtimestamp(stat.st_mtime) < c["since"]: continue
                        if path.is_file() and not content_matches(path, c["content"], c["case"]): continue
                        if path.is_dir() and c["content"]: continue
                        self.messages.put(("item", path, stat)); count += 1
                    except OSError: continue
            self.messages.put(("done", count, self.cancel_event.is_set(), count >= RESULT_LIMIT))
        except BaseException as exc:
            self.messages.put(("error", str(exc)))

    def _poll(self):
        processed = 0
        while processed < 250:
            try: message = self.messages.get_nowait()
            except queue.Empty: break
            processed += 1
            if message[0] == "item":
                _, path, stat = message; self.results.append(path)
                folder = str(path.parent)
                size_text = "<DIR>" if path.is_dir() else f"{stat.st_size:,}"
                modified = datetime.fromtimestamp(stat.st_mtime).strftime("%Y-%m-%d %H:%M")
                extension = "" if path.is_dir() else path.suffix[1:].upper()
                iid = self.tree.insert("", "end", text=path.name, tags=(str(path),),
                                       values=(folder, size_text, modified, extension))
                self._measure_result(path.name, folder, size_text, modified, extension)
                self.item_data[iid] = {"name": path.name.casefold(), "folder": str(path.parent).casefold(),
                                       "size": stat.st_size, "modified": stat.st_mtime,
                                       "ext": ("" if path.is_dir() else path.suffix[1:]).casefold()}
                self.status.configure(text=tr("{count} found", count=len(self.results)))
            elif message[0] == "done":
                _, count, cancelled, limited = message
                suffix = tr(" — cancelled") if cancelled else (tr(" — limit reached") if limited else "")
                self.status.configure(text=tr("{count} found", count=count) + suffix); self.find_button.configure(state="normal"); self.cancel_button.configure(state="disabled")
                self.progress.stop(); self.progress.configure(mode="determinate", value=100)
                self._progress_target = self._progress_displayed = 100
                self.progress_eta.configure(text=tr("Estimated time remaining: 00 minutes 00 seconds"))
                self.worker = None
                self._apply_sort()
            elif message[0] == "error":
                self.find_button.configure(state="normal"); self.cancel_button.configure(state="disabled")
                self.progress.stop(); self.progress.configure(mode="determinate", value=0)
                self.worker = None
                messagebox.showerror(tr("Search failed"), message[1], parent=self)
            elif message[0] == "progress":
                _, completed, total = message
                if total:
                    self._progress_target = max(self._progress_target,
                                                min(95.0, completed * 100 / total))
        if self._progress_displayed < self._progress_target:
            delta = min(5, max(1, self._progress_target - self._progress_displayed))
            self._progress_displayed = min(self._progress_target, self._progress_displayed + delta)
            self.progress.configure(value=self._progress_displayed)
            elapsed = max(.001, time.monotonic() - self._progress_started)
            remaining = max(0, round(elapsed * (100 - self._progress_displayed) /
                                     max(1, self._progress_displayed)))
            self.progress_eta.configure(text=tr(
                "Estimated time remaining: {minutes:02d} minutes {seconds:02d} seconds",
                minutes=remaining // 60, seconds=remaining % 60))
        if not self.messages.empty() or (self.worker and self.worker.is_alive()):
            self.poll_job = self.after(40, self._poll)

    def selected_paths(self):
        return [Path(self.tree.item(iid, "tags")[0]) for iid in self.tree.selection()
                if self.tree.item(iid, "tags")]
    def go_selected(self):
        paths=self.selected_paths()
        if paths:
            self.on_go(paths[0])
            try: self.lower(self.master)
            except tk.TclError: pass
    def preview_selected(self):
        paths=self.selected_paths()
        if paths:
            ordered = [Path(self.tree.item(iid, "tags")[0]) for iid in self.tree.get_children()
                       if self.tree.item(iid, "tags")]
            self.on_preview(ordered, paths[0])
    def compare_selected(self):
        paths = self.selected_paths()
        if len(paths) < 2:
            messagebox.showinfo(tr("Compare"), tr("Select two search results first."), parent=self)
            return
        if self.on_compare is not None:
            self.on_compare(paths[0], paths[1])
    def send_listing(self):
        paths = [Path(self.tree.item(iid, "tags")[0]) for iid in self.tree.get_children()
                 if self.tree.item(iid, "tags")]
        if paths and self.on_send_listing is not None:
            self.on_send_listing(paths)
    def copy_paths(self):
        paths=self.selected_paths()
        if paths: self.clipboard_clear(); self.clipboard_append("\n".join(map(str, paths))); self.update_idletasks()
    def cancel(self): self.cancel_event.set(); self.status.configure(text=tr("Cancelling…"))
    def escape(self): self.cancel() if self.worker and self.worker.is_alive() else self.close()
    def close(self):
        self.cancel_event.set()
        if self.poll_job is not None:
            try: self.after_cancel(self.poll_job)
            except tk.TclError: pass
        if self._column_resize_job is not None:
            try: self.after_cancel(self._column_resize_job)
            except tk.TclError: pass
        if not self.config_data.has_section("search"): self.config_data.add_section("search")
        for key, value in (("geometry", self.geometry()), ("mask", self.mask_var.get()), ("content", self.content_var.get()),
                           ("case_sensitive", str(self.case_var.get()).lower()),
                           ("depth", self.depth_values.get(self.depth_var.get(), self.depth_var.get())),
                           ("files", str(self.files_var.get()).lower()), ("folders", str(self.folders_var.get()).lower()),
                           ("min_size_kb", self.min_size_var.get()), ("max_size_kb", self.max_size_var.get()),
                           ("modified_days", self.days_var.get())):
            self.config_data.set("search", key, value)
        self.save_config(); self.destroy()


import re
import uuid
from pathlib import Path
import tkinter as tk
import tkinter.font as tkfont
from tkinter import messagebox, ttk


INVALID_NAME_CHARS = set('<>:"/\\|?*')


def render_rename(path: Path, mask: str, find: str = "", replace: str = "",
                  counter: int = 1, digits: int = 2, case_sensitive: bool = False,
                  keep_extension: bool = True) -> str:
    is_folder = path.is_dir()
    stem = path.name if is_folder else path.stem
    extension = "" if is_folder else path.suffix[1:]
    name = mask.replace("[N]", stem).replace("[E]", extension).replace(
        "[C]", str(counter).zfill(max(1, digits)))
    if find:
        if case_sensitive:
            name = name.replace(find, replace)
        else:
            name = re.sub(re.escape(find), lambda _match: replace, name, flags=re.IGNORECASE)
    if keep_extension and not is_folder and "[E]" not in mask:
        name += path.suffix
    return name


def validate_rename_plan(paths: list[Path], names: list[str]):
    selected = {str(path).casefold() for path in paths}
    duplicate_counts = {}
    for path, name in zip(paths, names):
        key = str(path.with_name(name)).casefold()
        duplicate_counts[key] = duplicate_counts.get(key, 0) + 1
    result = []
    for path, name in zip(paths, names):
        target = path.with_name(name) if name else path
        error = ""
        if not name:
            error = "Empty name"
        elif name in {".", ".."} or any(char in INVALID_NAME_CHARS for char in name):
            error = "Invalid name"
        elif name.endswith((" ", ".")):
            error = "Trailing space/dot"
        elif duplicate_counts.get(str(target).casefold(), 0) > 1:
            error = "Duplicate target"
        elif target.exists() and str(target).casefold() not in selected and target != path:
            error = "Target exists"
        elif target == path:
            error = "Unchanged"
        result.append((path, target, error))
    return result


def execute_rename_pairs(pairs: list[tuple[Path, Path]]) -> list[tuple[Path, Path]]:
    """Rename as one batch via temporary names; restore originals if any step fails."""
    records = []
    try:
        for source, target in pairs:
            temporary = source.with_name(f".{source.name}.pfc-rename-{uuid.uuid4().hex}")
            source.rename(temporary)
            records.append({"source": source, "target": target, "current": temporary})
        for record in records:
            record["current"].rename(record["target"])
            record["current"] = record["target"]
    except OSError:
        rollback = []
        for record in records:
            current = record["current"]
            if current.exists():
                temporary = current.with_name(f".{current.name}.pfc-rollback-{uuid.uuid4().hex}")
                try:
                    current.rename(temporary); rollback.append((temporary, record["source"]))
                except OSError:
                    pass
        for temporary, original in rollback:
            try:
                temporary.rename(original)
            except OSError:
                pass
        raise
    return [(target, source) for source, target in pairs]


class MultiRenameWindow(tk.Toplevel):
    def __init__(self, master, paths, undo_stack, on_changed):
        super().__init__(master)
        self.paths = list(paths); self.undo_stack = undo_stack; self.on_changed = on_changed
        self.title(tr("PFC Multi-Rename"))
        self.geometry("980x650"); self.minsize(700, 470); self.transient(master)
        self.protocol("WM_DELETE_WINDOW", self.destroy)
        self.mask_var = tk.StringVar(value="[N]")
        self.find_var, self.replace_var = tk.StringVar(), tk.StringVar()
        self.start_var, self.digits_var = tk.IntVar(value=1), tk.IntVar(value=2)
        self.case_var, self.extension_var = tk.BooleanVar(value=False), tk.BooleanVar(value=True)
        controls = ttk.Frame(self, padding=8); controls.pack(fill="x")
        ttk.Label(controls, text=tr("Name mask:")).grid(row=0, column=0, sticky="w")
        self.mask_entry = ttk.Entry(controls, textvariable=self.mask_var)
        self.mask_entry.grid(row=0, column=1, columnspan=5, sticky="ew", padx=(4, 8))
        ttk.Label(controls, text=tr("[N] original   [C] counter   [E] extension")).grid(
            row=0, column=6, columnspan=3, sticky="w")
        ttk.Label(controls, text=tr("Find:")).grid(row=1, column=0, sticky="w", pady=(6, 0))
        ttk.Entry(controls, textvariable=self.find_var).grid(row=1, column=1, sticky="ew", padx=(4, 8), pady=(6, 0))
        ttk.Label(controls, text=tr("Replace:")).grid(row=1, column=2, sticky="w", pady=(6, 0))
        ttk.Entry(controls, textvariable=self.replace_var).grid(row=1, column=3, sticky="ew", padx=(4, 8), pady=(6, 0))
        ttk.Checkbutton(controls, text=tr("Case sensitive"), variable=self.case_var,
                        command=self.update_preview).grid(row=1, column=4, sticky="w", pady=(6, 0))
        ttk.Checkbutton(controls, text=tr("Keep extension"), variable=self.extension_var,
                        command=self.update_preview).grid(row=1, column=5, sticky="w", pady=(6, 0))
        ttk.Label(controls, text=tr("Start:")).grid(row=2, column=0, sticky="w", pady=(6, 0))
        ttk.Spinbox(controls, from_=0, to=999999, textvariable=self.start_var, width=7,
                    command=self.update_preview).grid(row=2, column=1, sticky="w", padx=(4, 8), pady=(6, 0))
        ttk.Label(controls, text=tr("Digits:")).grid(row=2, column=2, sticky="w", pady=(6, 0))
        ttk.Spinbox(controls, from_=1, to=12, textvariable=self.digits_var, width=5,
                    command=self.update_preview).grid(row=2, column=3, sticky="w", padx=(4, 8), pady=(6, 0))
        controls.columnconfigure(1, weight=1); controls.columnconfigure(3, weight=1)
        self.tree = ttk.Treeview(self, columns=("old", "new", "status"), show="headings")
        for column, width in (("old", 360), ("new", 360), ("status", 150)):
            self.tree.heading(column, text=tr(column.title())); self.tree.column(column, width=width)
        self.tree.tag_configure("error", foreground="#a00000")
        self.tree.tag_configure("ok", foreground="#006c3b")
        self.tree.pack(fill="both", expand=True, padx=8)
        bottom = ttk.Frame(self, padding=8); bottom.pack(fill="x")
        self.status = ttk.Label(bottom, anchor="w"); self.status.pack(side="left", fill="x", expand=True)
        self.undo_button = ttk.Button(bottom, text=tr("Ctrl+Z Undo"), command=self.undo)
        self.undo_button.pack(side="right")
        ttk.Button(bottom, text=tr("Close"), command=self.destroy).pack(side="right", padx=4)
        self.apply_button = ttk.Button(bottom, text=tr("Ctrl+Enter Rename"), command=self.apply)
        self.apply_button.pack(side="right")
        for variable in (self.mask_var, self.find_var, self.replace_var, self.start_var, self.digits_var):
            variable.trace_add("write", lambda *_args: self.after_idle(self.update_preview))
        self.bind("<Escape>", lambda _event: self.destroy())
        self.bind("<Control-Return>", lambda _event: self.apply())
        self.bind("<Control-z>", lambda _event: self.undo())
        self.apply_color_scheme(getattr(master, "palette", color_scheme("light")))
        self.update_preview(); self.after_idle(self._activate)

    def apply_color_scheme(self, palette) -> None:
        self.palette = palette
        self.configure(background=palette["window"])
        dark = palette["window"] == "#20262c"
        self.tree.tag_configure("error", foreground="#ff7770" if dark else "#a00000")
        self.tree.tag_configure("ok", foreground="#73d6a1" if dark else "#006c3b")

    def _activate(self):
        self.deiconify(); self.lift(); self.focus_force(); self.mask_entry.focus_set(); self.mask_entry.selection_range(0, "end")

    def apply_language(self, old_language: str) -> None:
        retranslate_widgets(self, old_language)
        self.title(tr("PFC Multi-Rename"))
        for column in ("old", "new", "status"):
            self.tree.heading(column, text=tr(column.title()))
        self.update_preview()

    def _plan(self):
        try:
            start, digits = self.start_var.get(), self.digits_var.get()
        except tk.TclError:
            start, digits = 1, 2
        names = [render_rename(path, self.mask_var.get(), self.find_var.get(), self.replace_var.get(),
                               start + index, digits, self.case_var.get(), self.extension_var.get())
                 for index, path in enumerate(self.paths)]
        return validate_rename_plan(self.paths, names)

    def update_preview(self):
        if not self.winfo_exists(): return
        plan = self._plan(); self.tree.delete(*self.tree.get_children())
        errors = changed = 0
        for source, target, problem in plan:
            if problem and problem != "Unchanged": errors += 1
            if not problem: changed += 1
            self.tree.insert("", "end", values=(source.name, target.name, tr(problem or "Ready")),
                             tags=("error" if problem and problem != "Unchanged" else "ok",))
        self.status.configure(text=tr("{changed} rename(s), {errors} error(s)", changed=changed, errors=errors))
        self.apply_button.state(["disabled"] if errors or not changed else ["!disabled"])
        self.undo_button.state(["!disabled"] if self.undo_stack else ["disabled"])

    def apply(self):
        plan = self._plan()
        pairs = [(source, target) for source, target, problem in plan if not problem]
        errors = [problem for _source, _target, problem in plan if problem and problem != "Unchanged"]
        if errors or not pairs: return "break"
        preview = "\n".join(f"{source.name}  →  {target.name}" for source, target in pairs[:30])
        if len(pairs) > 30: preview += f"\n… and {len(pairs) - 30} more"
        if not messagebox.askyesno(tr("Multi-Rename"),
                                   tr("Rename {count} item(s)?", count=len(pairs)) + f"\n\n{preview}", parent=self):
            return "break"
        try:
            undo = execute_rename_pairs(pairs)
        except OSError as exc:
            messagebox.showerror(tr("Multi-Rename failed"), str(exc), parent=self); return "break"
        self.undo_stack.append(undo); self.paths = [target for _source, target in pairs]
        self.on_changed(); self.update_preview()
        messagebox.showinfo(tr("Multi-Rename"), tr("Renamed {count} item(s).", count=len(pairs)), parent=self)
        return "break"

    def undo(self):
        if not self.undo_stack: return "break"
        pairs = self.undo_stack[-1]
        problems = validate_rename_plan([source for source, _target in pairs],
                                        [target.name for _source, target in pairs])
        if any(problem and problem != "Unchanged" for _source, _target, problem in problems):
            messagebox.showerror(tr("Undo Multi-Rename"), tr("Undo target is no longer available."), parent=self)
            return "break"
        try:
            execute_rename_pairs(pairs)
        except OSError as exc:
            messagebox.showerror(tr("Undo Multi-Rename"), str(exc), parent=self); return "break"
        self.undo_stack.pop(); self.paths = [target for _source, target in pairs]
        self.on_changed(); self.update_preview()
        messagebox.showinfo(tr("Undo Multi-Rename"), tr("Restored {count} item(s).", count=len(pairs)), parent=self)
        return "break"


import os
import shutil
import subprocess
import tempfile
import threading
import zipfile
from pathlib import Path, PurePosixPath
from typing import Callable


ARCHIVE_SUFFIXES = {".zip", ".7z"}
ProgressCallback = Callable[[int, int, str], None]


class ArchiveCancelled(OSError):
    pass


def filesystem_path(path: Path) -> str:
    """Return a Windows extended-length path without changing its logical value."""
    raw = str(Path(path).absolute())
    if os.name != "nt" or raw.startswith("\\\\?\\"):
        return raw
    if raw.startswith("\\\\"):
        return "\\\\?\\UNC\\" + raw[2:]
    return "\\\\?\\" + raw


def _mkdir(path: Path) -> None:
    os.makedirs(filesystem_path(path), exist_ok=True)


def is_browsable_archive(path: Path) -> bool:
    return path.is_file() and path.suffix.casefold() in ARCHIVE_SUFFIXES


def archive_item_counts(path: Path) -> tuple[int, int]:
    """Return distinct contained folder and file counts without extracting."""
    path = Path(path).expanduser().resolve()
    folders: set[str] = set()
    files = 0

    def add_member(raw_name: str, is_folder: bool) -> None:
        nonlocal files
        member = PurePosixPath(raw_name.replace("\\", "/"))
        parts = [part for part in member.parts if part not in {"", "."}]
        if not parts:
            return
        parent_limit = len(parts) if is_folder else len(parts) - 1
        for index in range(1, parent_limit + 1):
            folders.add("/".join(parts[:index]).casefold())
        if not is_folder:
            files += 1

    if path.suffix.casefold() == ".zip":
        with zipfile.ZipFile(path) as archive:
            for info in archive.infolist():
                add_member(info.filename, info.is_dir())
        return len(folders), files

    executable = _seven_zip_executable()
    if executable is None:
        raise OSError("7z listing requires the 7-Zip command-line tool (7z or 7zz).")
    listing = subprocess.run([executable, "l", "-slt", str(path)], capture_output=True,
                             text=True, errors="replace", **_hidden_process_options())
    if listing.returncode:
        raise OSError(listing.stderr.strip() or listing.stdout.strip() or
                      "Unable to read 7z archive.")
    blocks = listing.stdout.replace("\r\n", "\n").split("\n\n")[1:]
    for block in blocks:
        fields = dict(line.split(" = ", 1) for line in block.splitlines() if " = " in line)
        name = fields.get("Path")
        if name:
            add_member(name, fields.get("Folder") == "+" or "D" in fields.get("Attributes", ""))
    return len(folders), files


def _hidden_process_options() -> dict:
    return ({"creationflags": getattr(subprocess, "CREATE_NO_WINDOW", 0)}
            if os.name == "nt" else {})


def create_zip_archive(items, target: Path,
                       progress: ProgressCallback | None = None) -> Path:
    """Create a ZIP containing each selected item under its own display name."""
    paths = [Path(item) for item in items]
    if not paths:
        raise OSError("No items are selected for compression.")
    target.parent.mkdir(parents=True, exist_ok=True)
    files = [child for item in paths for child in
             ([item] if item.is_file() else [p for p in item.rglob("*") if p.is_file()])]
    total = max(1, sum(path.stat().st_size for path in files))
    completed = 0
    with zipfile.ZipFile(target, "w", compression=zipfile.ZIP_DEFLATED) as archive:
        for item in paths:
            if item.is_dir():
                descendants = sorted(item.rglob("*"))
                if not descendants:
                    archive.writestr(item.name.rstrip("/") + "/", b"")
                for child in descendants:
                    relative = Path(item.name) / child.relative_to(item)
                    if child.is_dir():
                        if not any(child.iterdir()):
                            archive.writestr(relative.as_posix().rstrip("/") + "/", b"")
                    else:
                        archive.write(child, relative.as_posix())
                        completed += child.stat().st_size
                        if progress:
                            progress(completed, total, child.name)
            else:
                archive.write(item, item.name)
                completed += item.stat().st_size
                if progress:
                    progress(completed, total, item.name)
    if progress:
        progress(total, total, target.name)
    return target


def extract_archive_to(archive_path: Path, destination: Path,
                       progress: ProgressCallback | None = None) -> Path:
    """Safely extract ZIP/7z directly, avoiding long temporary copy paths."""
    archive_path = archive_path.expanduser().resolve()
    _mkdir(destination)
    if archive_path.suffix.casefold() == ".zip":
        with zipfile.ZipFile(archive_path) as archive:
            members = archive.infolist()
            total = max(1, sum(info.file_size for info in members if not info.is_dir()))
            completed = 0
            for info in members:
                target = _safe_destination(destination.resolve(), info.filename)
                if info.is_dir():
                    _mkdir(target)
                    continue
                _mkdir(target.parent)
                with archive.open(info) as source, open(filesystem_path(target), "wb") as output:
                    while True:
                        chunk = source.read(1024 * 1024)
                        if not chunk:
                            break
                        output.write(chunk)
                        completed += len(chunk)
                        if progress:
                            progress(completed, total, Path(info.filename).name)
        if progress:
            progress(total, total, archive_path.name)
        return destination
    executable = _seven_zip_executable()
    if executable is None:
        raise OSError("7z extraction requires the 7-Zip command-line tool (7z or 7zz).")
    listing = subprocess.run([executable, "l", "-slt", str(archive_path)],
                             capture_output=True, text=True, errors="replace",
                             **_hidden_process_options())
    if listing.returncode:
        raise OSError(listing.stderr.strip() or listing.stdout.strip() or "Unable to read 7z archive.")
    members = [line[7:] for line in listing.stdout.splitlines() if line.startswith("Path = ")][1:]
    for member in members:
        _safe_destination(destination.resolve(), member)
    process = subprocess.Popen(
        [executable, "x", "-y", "-bso0", "-bse1", "-bsp1",
         f"-o{filesystem_path(destination)}", str(archive_path)],
        stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, errors="replace",
        **_hidden_process_options())
    output = ""
    assert process.stdout is not None
    while True:
        character = process.stdout.read(1)
        if not character:
            break
        output = (output + character)[-200:]
        if character in {"%", "\r", "\n"}:
            import re
            matches = re.findall(r"(\d{1,3})%", output)
            if matches and progress:
                percent = min(100, int(matches[-1]))
                progress(percent, 100, archive_path.name)
    _stdout, stderr = process.communicate()
    if process.returncode:
        raise OSError(stderr.strip() or output.strip() or "7z extraction failed.")
    if progress:
        progress(100, 100, archive_path.name)
    return destination


def _seven_zip_executable() -> str | None:
    candidates = ("7z", "7zz", "7za")
    for name in candidates:
        executable = shutil.which(name)
        if executable:
            return executable
    if os.name == "nt":
        for raw in (r"C:\Program Files\7-Zip\7z.exe",
                    r"C:\Program Files (x86)\7-Zip\7z.exe"):
            if Path(raw).is_file():
                return raw
    return None


def _safe_destination(root: Path, member_name: str) -> Path:
    member = PurePosixPath(member_name.replace("\\", "/"))
    if member.is_absolute() or ".." in member.parts:
        raise OSError(f"Unsafe archive item: {member_name}")
    destination = root.joinpath(*member.parts).resolve()
    if destination != root and root not in destination.parents:
        raise OSError(f"Unsafe archive item: {member_name}")
    return destination


class ArchiveSession:
    """Editable extracted workspace backed by one ZIP or 7z file."""

    def __init__(self, archive_path: Path,
                 cancel_event: threading.Event | None = None,
                 progress: ProgressCallback | None = None) -> None:
        self.archive_path = archive_path.expanduser().resolve()
        self.cancel_event = cancel_event
        self.progress = progress
        if not is_browsable_archive(self.archive_path):
            raise OSError(f"Unsupported archive: {self.archive_path.name}")
        self._temporary = tempfile.TemporaryDirectory(prefix="pfc-archive-")
        self.root = Path(self._temporary.name).resolve()
        try:
            self._extract()
        except Exception:
            self._temporary.cleanup()
            raise

    @property
    def kind(self) -> str:
        return self.archive_path.suffix.casefold()

    def contains(self, path: Path) -> bool:
        try:
            resolved = path.resolve()
        except OSError:
            resolved = Path(os.path.abspath(path))
        return resolved == self.root or self.root in resolved.parents

    def relative_path(self, path: Path) -> Path:
        return path.resolve().relative_to(self.root)

    def display_path(self, path: Path) -> str:
        relative = self.relative_path(path)
        return str(self.archive_path) if not relative.parts else f"{self.archive_path}{os.sep}{relative}"

    def _extract(self) -> None:
        if self.kind == ".zip":
            with zipfile.ZipFile(self.archive_path) as archive:
                members = archive.infolist()
                total = max(1, sum(info.file_size for info in members if not info.is_dir()))
                completed = 0
                for info in members:
                    self._check_cancelled()
                    destination = _safe_destination(self.root, info.filename)
                    if info.is_dir():
                        _mkdir(destination)
                        continue
                    _mkdir(destination.parent)
                    with archive.open(info) as source, open(filesystem_path(destination), "wb") as target:
                        while True:
                            self._check_cancelled()
                            chunk = source.read(1024 * 1024)
                            if not chunk:
                                break
                            target.write(chunk)
                            completed += len(chunk)
                            if self.progress:
                                self.progress(completed, total, Path(info.filename).name)
            if self.progress:
                self.progress(total, total, self.archive_path.name)
            return
        executable = _seven_zip_executable()
        if executable is None:
            raise OSError("7z browsing requires the 7-Zip command-line tool (7z or 7zz).")
        process = subprocess.Popen(
            [executable, "x", "-y", "-bso0", "-bsp0", "-bse1",
             f"-o{filesystem_path(self.root)}", str(self.archive_path)],
            stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, errors="replace",
            **_hidden_process_options())
        started = __import__("time").monotonic()
        last_percent = 0
        if self.progress:
            self.progress(1, 100, self.archive_path.name)
        while True:
            try:
                stdout, stderr = process.communicate(timeout=0.15)
                break
            except subprocess.TimeoutExpired:
                if self.progress:
                    elapsed = __import__("time").monotonic() - started
                    percent = min(90, 1 + int(elapsed * 2))
                    if percent > last_percent:
                        last_percent = percent
                        self.progress(percent, 100, self.archive_path.name)
                if self.cancel_event is not None and self.cancel_event.is_set():
                    process.terminate()
                    try:
                        process.communicate(timeout=2)
                    except subprocess.TimeoutExpired:
                        process.kill()
                        process.communicate()
                    raise ArchiveCancelled("Archive opening cancelled.")
        if process.returncode:
            raise OSError(stderr.strip() or stdout.strip() or "7z extraction failed.")
        if self.progress:
            self.progress(100, 100, self.archive_path.name)

    def _check_cancelled(self) -> None:
        if self.cancel_event is not None and self.cancel_event.is_set():
            raise ArchiveCancelled("Archive opening cancelled.")

    def commit(self) -> None:
        suffix = self.archive_path.suffix
        descriptor, raw_temporary = tempfile.mkstemp(
            prefix=f".{self.archive_path.stem}.pfc-", suffix=suffix,
            dir=self.archive_path.parent)
        os.close(descriptor)
        temporary = Path(raw_temporary)
        temporary.unlink(missing_ok=True)
        try:
            if self.kind == ".zip":
                with zipfile.ZipFile(temporary, "w", compression=zipfile.ZIP_DEFLATED) as archive:
                    for path in sorted(self.root.rglob("*")):
                        relative = path.relative_to(self.root).as_posix()
                        if path.is_dir():
                            if not any(path.iterdir()):
                                archive.writestr(relative.rstrip("/") + "/", b"")
                        else:
                            archive.write(path, relative)
            else:
                executable = _seven_zip_executable()
                if executable is None:
                    raise OSError("7z writing requires the 7-Zip command-line tool (7z or 7zz).")
                result = subprocess.run(
                    [executable, "a", "-t7z", "-mx=5", str(temporary), "."],
                    cwd=self.root, capture_output=True, text=True, errors="replace")
                if result.returncode:
                    raise OSError(result.stderr.strip() or result.stdout.strip() or "7z update failed.")
            os.replace(temporary, self.archive_path)
        finally:
            temporary.unlink(missing_ok=True)

    def close(self) -> None:
        self._temporary.cleanup()


import os
import queue
import threading
import tkinter as tk
import tkinter.font as tkfont
from dataclasses import dataclass, field
from pathlib import Path
from tkinter import messagebox, ttk



@dataclass
class SpaceNode:
    path: Path
    size: int
    is_dir: bool
    children: list["SpaceNode"] = field(default_factory=list)


def scan_space(path: Path, cancel_event: threading.Event | None = None) -> SpaceNode:
    """Return a best-effort, symlink-safe disk usage tree."""
    cancel_event = cancel_event or threading.Event()
    path = path.expanduser().resolve()
    if cancel_event.is_set():
        raise InterruptedError
    try:
        is_dir = path.is_dir()
    except OSError:
        return SpaceNode(path, 0, False)
    if not is_dir:
        try:
            return SpaceNode(path, path.stat().st_size, False)
        except OSError:
            return SpaceNode(path, 0, False)
    children = []
    try:
        entries = list(os.scandir(path))
    except OSError:
        return SpaceNode(path, 0, True)
    for entry in entries:
        if cancel_event.is_set():
            raise InterruptedError
        child = Path(entry.path)
        try:
            if entry.is_symlink():
                size = entry.stat(follow_symlinks=False).st_size
                children.append(SpaceNode(child, size, False))
            elif entry.is_dir(follow_symlinks=False):
                children.append(scan_space(child, cancel_event))
            else:
                children.append(SpaceNode(
                    child, entry.stat(follow_symlinks=False).st_size, False))
        except OSError:
            children.append(SpaceNode(child, 0, False))
    children.sort(key=lambda node: node.size, reverse=True)
    return SpaceNode(path, sum(child.size for child in children), True, children)


def partition_rectangles(nodes: list[SpaceNode], x: float, y: float,
                         width: float, height: float) -> list[tuple[SpaceNode, tuple[float, float, float, float]]]:
    """Balanced slice-and-dice layout with area proportional to byte size."""
    nodes = [node for node in nodes if node.size > 0]
    if not nodes or width <= 0 or height <= 0:
        return []
    if len(nodes) == 1:
        return [(nodes[0], (x, y, x + width, y + height))]
    total = sum(node.size for node in nodes)
    halfway, running, split = total / 2, 0, 1
    for index, node in enumerate(nodes[:-1], 1):
        running += node.size
        split = index
        if running >= halfway:
            break
    first, second = nodes[:split], nodes[split:]
    first_total = sum(node.size for node in first)
    ratio = first_total / total
    if width >= height:
        first_box = (x, y, width * ratio, height)
        second_box = (x + width * ratio, y, width * (1 - ratio), height)
    else:
        first_box = (x, y, width, height * ratio)
        second_box = (x, y + height * ratio, width, height * (1 - ratio))
    return (partition_rectangles(first, *first_box) +
            partition_rectangles(second, *second_box))


class SpaceAnalyzerWindow(tk.Toplevel):
    COLORS = ("#4f8fc9", "#66a65c", "#e29b45", "#9b72cf", "#d85d67",
              "#4fb5ad", "#c8885d", "#7d92a8", "#d3b94f")

    def __init__(self, parent, start_path: Path, on_locate, on_remove,
                 palette: dict) -> None:
        super().__init__(parent)
        self.withdraw()
        self.title(tr("Folder Space Analyzer"))
        self.transient(parent)
        self.on_locate = on_locate
        self.on_remove = on_remove
        self.palette = palette
        self.path_var = tk.StringVar(value=str(start_path))
        self.status_var = tk.StringVar(value=tr("Ready"))
        self.history: list[Path] = []
        self.root_node: SpaceNode | None = None
        self.selected_node: SpaceNode | None = None
        self._rectangles: list[tuple[int, SpaceNode]] = []
        self._messages: queue.Queue = queue.Queue()
        self._cancel_event = threading.Event()
        self._worker = None
        self._poll_job = None
        self._resize_job = None
        self._click_job = None
        self._build()
        parent.update_idletasks()
        width = max(840, int(parent.winfo_width() * 0.78))
        height = max(560, int(parent.winfo_height() * 0.80))
        screen_width, screen_height = self.winfo_screenwidth(), self.winfo_screenheight()
        width, height = min(width, screen_width - 50), min(height, screen_height - 80)
        x = parent.winfo_rootx() + max(0, (parent.winfo_width() - width) // 2)
        y = parent.winfo_rooty() + max(0, (parent.winfo_height() - height) // 2)
        self.geometry(f"{width}x{height}+{x}+{y}")
        self.minsize(min(840, width), min(560, height))
        self.protocol("WM_DELETE_WINDOW", self.close)
        self.bind("<Escape>", lambda _event: self.close())
        self.bind("<F5>", lambda _event: self.scan())
        self.deiconify()
        self.lift()
        self.focus_force()
        self.scan(start_path, remember=False)

    def _build(self) -> None:
        toolbar = ttk.Frame(self, padding=(8, 7, 8, 3))
        toolbar.pack(fill="x")
        ttk.Button(toolbar, text=tr("Back"), command=self.back).pack(side="left")
        ttk.Button(toolbar, text=tr("Parent Folder"), command=self.parent_folder).pack(side="left", padx=4)
        self.scan_button = ttk.Button(toolbar, text=tr("Analyze"), command=self.scan)
        self.scan_button.pack(side="left", padx=(6, 3))
        self.stop_button = ttk.Button(toolbar, text=tr("Stop"), command=self.stop)
        self.stop_button.pack(side="left")
        ttk.Button(toolbar, text=tr("Locate in PFC"),
                   command=self.locate_selected).pack(side="right")

        path_row = ttk.Frame(self, padding=(8, 3, 8, 5))
        path_row.pack(fill="x")
        ttk.Label(path_row, text=tr("Folder:")).pack(side="left", padx=(0, 5))
        self.path_entry = ttk.Entry(path_row, textvariable=self.path_var)
        self.path_entry.pack(side="left", fill="x", expand=True)
        self.path_entry.bind("<Return>", lambda _event: self.scan())

        info = ttk.Frame(self, padding=(8, 0, 8, 6))
        info.pack(fill="x")
        ttk.Label(
            info,
            text=tr("Block area is proportional to size. Click for Go to, double-click a folder to analyze, or right-click for delete options."),
            anchor="w").pack(fill="x")

        self.canvas = tk.Canvas(self, highlightthickness=1, relief="sunken",
                                background=palette_color(self.palette, "background", "#f2f2f2"))
        self.canvas.pack(fill="both", expand=True, padx=8)
        self.canvas.bind("<Button-1>", self._click)
        self.canvas.bind("<Double-Button-1>", self._double_click)
        self.canvas.bind("<Button-3>", self._right_click)
        self.canvas.bind("<Configure>", self._schedule_redraw)

        legend = ttk.Frame(self, padding=(8, 5, 8, 2))
        legend.pack(fill="x")
        for label, color in ((tr("Folders"), self.COLORS[0]),
                             (tr("Files"), self.COLORS[2]),
                             (tr("Selected"), "#ffcf45")):
            swatch = tk.Label(legend, width=2, background=color, relief="solid", borderwidth=1)
            swatch.pack(side="left", padx=(0, 3))
            ttk.Label(legend, text=label).pack(side="left", padx=(0, 12))
        ttk.Label(self, textvariable=self.status_var, anchor="w",
                  padding=(8, 4)).pack(fill="x")

    def apply_scale(self, _scale: float) -> None:
        self.after_idle(self._redraw)

    def apply_color_scheme(self, palette: dict) -> None:
        self.palette = palette
        self.canvas.configure(
            background=palette_color(palette, "content", "#f2f2f2"),
            highlightbackground=palette_color(palette, "border", "#808080"))
        self._redraw()

    def apply_language(self, old_language: str) -> None:
        self.title(tr("Folder Space Analyzer"))
        retranslate_widgets(self, old_language)

    def show(self, path: Path) -> None:
        self.deiconify()
        self.lift()
        self.focus_force()
        target = path if path.is_dir() else path.parent
        if str(target) != self.path_var.get():
            self.scan(target)

    def scan(self, path: Path | None = None, remember: bool = True) -> None:
        target = Path(path or self.path_var.get().strip().strip('"')).expanduser()
        if not target.is_dir():
            messagebox.showerror(tr("Folder Space Analyzer"),
                                 tr("Select a folder to analyze."), parent=self)
            self.path_var.set(str(self.root_node.path if self.root_node else target.parent))
            return
        target = target.resolve()
        if self._worker is not None and self._worker.is_alive():
            self.stop()
        if remember and self.root_node is not None and self.root_node.path != target:
            self.history.append(self.root_node.path)
        self.path_var.set(str(target))
        self.root_node = None
        self.selected_node = None
        self.canvas.delete("all")
        self._cancel_event = threading.Event()
        self.status_var.set(tr("Scanning…  Esc closes"))
        self.stop_button.state(["!disabled"])
        self.scan_button.state(["disabled"])

        def worker():
            try:
                self._messages.put(("done", scan_space(target, self._cancel_event)))
            except InterruptedError:
                self._messages.put(("cancelled", None))
            except Exception as exc:
                self._messages.put(("error", exc))

        self._worker = threading.Thread(target=worker, daemon=True)
        self._worker.start()
        if self._poll_job is None:
            self._poll()

    def _poll(self) -> None:
        self._poll_job = None
        try:
            kind, value = self._messages.get_nowait()
        except queue.Empty:
            if self.winfo_exists():
                self._poll_job = self.after(80, self._poll)
            return
        self.scan_button.state(["!disabled"])
        self.stop_button.state(["disabled"])
        if kind == "done":
            self.root_node = value
            self.status_var.set(tr("{count} top-level items   {size}",
                                   count=len(value.children), size=format_size(value.size)))
            self._redraw()
        elif kind == "cancelled":
            self.status_var.set(tr("Scan cancelled"))
        else:
            self.status_var.set(tr("Scan failed"))
            messagebox.showerror(tr("Folder Space Analyzer"), str(value), parent=self)

    def stop(self) -> None:
        self._cancel_event.set()
        self.status_var.set(tr("Cancelling…"))

    def back(self) -> None:
        if self.history:
            self.scan(self.history.pop(), remember=False)

    def parent_folder(self) -> None:
        current = Path(self.path_var.get())
        if current.parent != current:
            self.scan(current.parent)

    def _schedule_redraw(self, _event=None) -> None:
        if self._resize_job is not None:
            self.after_cancel(self._resize_job)
        self._resize_job = self.after(100, self._redraw)

    def _redraw(self) -> None:
        self._resize_job = None
        self.canvas.delete("all")
        self._rectangles.clear()
        if self.root_node is None:
            return
        width, height = max(1, self.canvas.winfo_width()), max(1, self.canvas.winfo_height())
        boxes = partition_rectangles(self.root_node.children, 2, 2, width - 4, height - 4)
        font = tkfont.nametofont("TkDefaultFont")
        for index, (node, box) in enumerate(boxes):
            self._draw_node(node, box, font, depth=0, color_index=index)

    def _draw_node(self, node: SpaceNode, box, font, depth: int,
                   color_index: int) -> None:
        x1, y1, x2, y2 = box
        width, height = x2 - x1, y2 - y1
        if width < 2 or height < 2:
            return
        if node.is_dir:
            color = self.COLORS[depth % 2]
        else:
            suffix_value = sum(ord(char) for char in node.path.suffix.casefold())
            color = self.COLORS[2 + suffix_value % (len(self.COLORS) - 2)]
        if node is self.selected_node:
            color = "#ffcf45"
        item = self.canvas.create_rectangle(
            x1, y1, x2, y2, fill=color, outline="#ffffff",
            width=max(1, 2 - min(depth, 1)))
        self._rectangles.append((item, node))
        line = font.metrics("linespace")
        label_height = line + 5 if node.is_dir and node.children else 0
        if width > font.measure("MMMM") and height > line * 1.25:
            max_width = max(1, int(width - 8))
            label = node.path.name
            while label and font.measure(label) > max_width:
                label = label[:-1]
            if label != node.path.name:
                label = label[:-1] + "…" if label else ""
            detail = label if label_height else f"{label}\n{format_size(node.size)}"
            self.canvas.create_text(
                x1 + 5, y1 + 3, text=detail, anchor="nw",
                width=max_width, fill="#101820", font=font)
        inner_height = height - label_height - 3
        if (node.is_dir and node.children and depth < 7 and
                width >= 34 and inner_height >= 24):
            inner = partition_rectangles(
                node.children, x1 + 2, y1 + label_height,
                width - 4, inner_height)
            for index, (child, child_box) in enumerate(inner):
                self._draw_node(child, child_box, font, depth + 1,
                                color_index + index)

    def _node_at(self, x: int, y: int) -> SpaceNode | None:
        overlapping = set(self.canvas.find_overlapping(x, y, x, y))
        for item, node in reversed(self._rectangles):
            if item in overlapping:
                return node
        return None

    def _click(self, event) -> None:
        node = self._node_at(event.x, event.y)
        if node is None:
            return
        self._select_node(node)
        if self._click_job is not None:
            self.after_cancel(self._click_job)
        self._click_job = self.after(
            250, lambda target=node: self._confirm_go_to(target))

    def _double_click(self, event) -> None:
        if self._click_job is not None:
            self.after_cancel(self._click_job)
            self._click_job = None
        node = self._node_at(event.x, event.y)
        if node is not None and node.is_dir:
            self.scan(node.path)

    def _right_click(self, event) -> None:
        if self._click_job is not None:
            self.after_cancel(self._click_job)
            self._click_job = None
        node = self._node_at(event.x, event.y)
        if node is None:
            return
        self._select_node(node)
        menu = tk.Menu(
            self, tearoff=False, font=tkfont.nametofont("TkMenuFont"))
        menu.add_command(
            label=tr("Move to Recycle Bin"),
            command=lambda target=node: self._confirm_remove(
                target, permanent=False))
        menu.add_command(
            label=tr("Permanently Delete"),
            command=lambda target=node: self._confirm_remove(
                target, permanent=True))
        try:
            menu.tk_popup(event.x_root, event.y_root)
        finally:
            menu.grab_release()

    def _select_node(self, node: SpaceNode) -> None:
        self.selected_node = node
        self.status_var.set(f"{node.path}   {format_size(node.size)}")
        self._redraw()

    def _confirm_go_to(self, node: SpaceNode) -> None:
        self._click_job = None
        if messagebox.askyesno(
                tr("Go to"),
                tr("Go to this item in PFC?\n\n{path}", path=node.path),
                parent=self):
            self.on_locate(node.path)

    def _confirm_remove(self, node: SpaceNode, permanent: bool) -> None:
        if permanent:
            title = tr("Permanent delete warning")
            prompt = tr(
                "This cannot be undone.\n\nPermanently delete this item?\n\n{path}",
                path=node.path)
        else:
            title = tr("Recycle Bin")
            prompt = tr(
                "Move this item to the Recycle Bin?\n\n{path}", path=node.path)
        if not messagebox.askyesno(
                title, prompt, icon="warning" if permanent else "question",
                parent=self):
            return
        if self.on_remove(node.path, permanent):
            self.scan(Path(self.path_var.get()), remember=False)

    def locate_selected(self) -> None:
        if self.selected_node is not None:
            self._confirm_go_to(self.selected_node)

    def close(self) -> None:
        self._cancel_event.set()
        if self._poll_job is not None:
            self.after_cancel(self._poll_job)
            self._poll_job = None
        if self._click_job is not None:
            self.after_cancel(self._click_job)
            self._click_job = None
        self.destroy()


def palette_color(palette: dict, key: str, fallback: str) -> str:
    return palette.get(key, fallback)


import ctypes
import os
import queue
import shutil
import tempfile
import threading
from pathlib import Path



DROPEFFECT_NONE = 0
DROPEFFECT_COPY = 1
DROPEFFECT_MOVE = 2
WM_DROPFILES = 0x0233
GWL_WNDPROC = -4
UINT_MAX = 0xFFFFFFFF
VK_SHIFT = 0x10
MK_SHIFT = 0x0004
S_OK = 0
E_NOINTERFACE = -2147467262
COINIT_APARTMENTTHREADED = 0x2


class _GUID(ctypes.Structure):
    _fields_ = [("Data1", ctypes.c_uint32), ("Data2", ctypes.c_uint16),
                ("Data3", ctypes.c_uint16), ("Data4", ctypes.c_ubyte * 8)]


class _POINT(ctypes.Structure):
    _fields_ = [("x", ctypes.c_long), ("y", ctypes.c_long)]


IID_IDATAOBJECT = _GUID(
    0x0000010E, 0x0000, 0x0000,
    (ctypes.c_ubyte * 8)(0xC0, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x46),
)
IID_IUNKNOWN = _GUID(
    0x00000000, 0x0000, 0x0000,
    (ctypes.c_ubyte * 8)(0xC0, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x46),
)
IID_IDROPTARGET = _GUID(
    0x00000122, 0x0000, 0x0000,
    (ctypes.c_ubyte * 8)(0xC0, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x46),
)


def _failed(status: int) -> bool:
    return status < 0


def _status_text(status: int) -> str:
    return f"0x{status & 0xFFFFFFFF:08X}"


def _release_interface(pointer: int) -> None:
    if not pointer:
        return
    table = ctypes.cast(pointer, ctypes.POINTER(ctypes.POINTER(ctypes.c_void_p))).contents
    release = ctypes.WINFUNCTYPE(ctypes.c_ulong, ctypes.c_void_p)(table[2])
    release(pointer)


def _marshal_data_object(data_object: int) -> int:
    """Marshal IDataObject so Office attachment download can leave the UI thread."""
    ole32 = ctypes.windll.ole32
    ole32.CoMarshalInterThreadInterfaceInStream.argtypes = [
        ctypes.POINTER(_GUID), ctypes.c_void_p, ctypes.POINTER(ctypes.c_void_p)]
    ole32.CoMarshalInterThreadInterfaceInStream.restype = ctypes.c_long
    stream = ctypes.c_void_p()
    status = ole32.CoMarshalInterThreadInterfaceInStream(
        ctypes.byref(IID_IDATAOBJECT), ctypes.c_void_p(data_object), ctypes.byref(stream))
    if _failed(status) or not stream.value:
        raise OSError(f"Cannot prepare Office attachment transfer ({_status_text(status)}).")
    return stream.value


def _unmarshal_data_object(stream: int) -> int:
    ole32 = ctypes.windll.ole32
    ole32.CoGetInterfaceAndReleaseStream.argtypes = [
        ctypes.c_void_p, ctypes.POINTER(_GUID), ctypes.POINTER(ctypes.c_void_p)]
    ole32.CoGetInterfaceAndReleaseStream.restype = ctypes.c_long
    data_object = ctypes.c_void_p()
    status = ole32.CoGetInterfaceAndReleaseStream(
        ctypes.c_void_p(stream), ctypes.byref(IID_IDATAOBJECT), ctypes.byref(data_object))
    if _failed(status) or not data_object.value:
        raise OSError(f"Cannot open Office attachment transfer ({_status_text(status)}).")
    return data_object.value


class ShellDataObject:
    """Shell IDataObject for direct children selected in one PFC panel."""

    def __init__(self, paths) -> None:
        if os.name != "nt":
            raise OSError("Windows Shell drag-and-drop is available only on Windows.")
        self.paths = [Path(value).resolve() for value in paths]
        if not self.paths:
            raise OSError("No files are selected for dragging.")
        parents = {os.path.normcase(str(path.parent)) for path in self.paths}
        if len(parents) != 1:
            raise OSError("Shell drag items must come from the same folder.")
        if any(not path.exists() for path in self.paths):
            raise OSError("A selected drag item no longer exists.")
        self.pointer = 0
        self._pidls: list[int] = []
        self._ole_initialized = False
        self._create()

    def _create(self) -> None:
        ole32, shell32 = ctypes.windll.ole32, ctypes.windll.shell32
        ole32.OleInitialize.argtypes = [ctypes.c_void_p]
        ole32.OleInitialize.restype = ctypes.c_long
        initialized = ole32.OleInitialize(None)
        if _failed(initialized):
            raise OSError(f"Cannot initialize Windows drag-and-drop ({_status_text(initialized)}).")
        self._ole_initialized = True
        shell32.SHParseDisplayName.argtypes = [ctypes.c_wchar_p, ctypes.c_void_p,
                                               ctypes.POINTER(ctypes.c_void_p), ctypes.c_uint32,
                                               ctypes.POINTER(ctypes.c_uint32)]
        shell32.SHParseDisplayName.restype = ctypes.c_long
        shell32.ILFindLastID.argtypes = [ctypes.c_void_p]
        shell32.ILFindLastID.restype = ctypes.c_void_p
        shell32.SHCreateDataObject.argtypes = [ctypes.c_void_p, ctypes.c_uint,
                                               ctypes.POINTER(ctypes.c_void_p), ctypes.c_void_p,
                                               ctypes.POINTER(_GUID), ctypes.POINTER(ctypes.c_void_p)]
        shell32.SHCreateDataObject.restype = ctypes.c_long
        try:
            parent = self._parse(str(self.paths[0].parent))
            self._pidls.append(parent)
            children = []
            for path in self.paths:
                absolute = self._parse(str(path))
                self._pidls.append(absolute)
                children.append(shell32.ILFindLastID(absolute))
            child_array = (ctypes.c_void_p * len(children))(*children)
            result = ctypes.c_void_p()
            status = shell32.SHCreateDataObject(parent, len(children), child_array, None,
                                                ctypes.byref(IID_IDATAOBJECT), ctypes.byref(result))
            if _failed(status) or not result.value:
                raise OSError(f"Windows could not create drag data ({_status_text(status)}).")
            self.pointer = result.value
        except Exception:
            self.close()
            raise

    def _parse(self, path: str) -> int:
        pointer, attributes = ctypes.c_void_p(), ctypes.c_uint32()
        status = ctypes.windll.shell32.SHParseDisplayName(
            path, None, ctypes.byref(pointer), 0, ctypes.byref(attributes))
        if _failed(status) or not pointer.value:
            raise OSError(f"Windows could not identify drag item: {path} ({_status_text(status)}).")
        return pointer.value

    def close(self) -> None:
        if os.name != "nt":
            return
        if self.pointer:
            _release_interface(self.pointer)
            self.pointer = 0
        for pidl in self._pidls:
            ctypes.windll.ole32.CoTaskMemFree(ctypes.c_void_p(pidl))
        self._pidls.clear()
        if self._ole_initialized:
            ctypes.windll.ole32.OleUninitialize()
            self._ole_initialized = False

    def __enter__(self):
        return self

    def __exit__(self, _type, _value, _traceback):
        self.close()


def start_shell_drag(hwnd: int, paths) -> int:
    """Run the native Shell drag loop and return its DROPEFFECT value."""
    if os.name != "nt":
        raise OSError("Windows Shell drag-and-drop is available only on Windows.")
    shell32 = ctypes.windll.shell32
    shell32.SHDoDragDrop.argtypes = [ctypes.c_void_p, ctypes.c_void_p, ctypes.c_void_p,
                                     ctypes.c_uint32, ctypes.POINTER(ctypes.c_uint32)]
    shell32.SHDoDragDrop.restype = ctypes.c_long
    effect = ctypes.c_uint32(DROPEFFECT_NONE)
    with ShellDataObject(paths) as data:
        status = shell32.SHDoDragDrop(ctypes.c_void_p(hwnd), ctypes.c_void_p(data.pointer), None,
                                     DROPEFFECT_COPY | DROPEFFECT_MOVE, ctypes.byref(effect))
        if _failed(status):
            raise OSError(f"Windows drag-and-drop failed ({_status_text(status)}).")
    return effect.value


def point_belongs_to_process(x: int, y: int, process_id: int | None = None) -> bool:
    """Return whether the top window under a screen point belongs to this process."""
    if os.name != "nt":
        return True
    user32 = ctypes.windll.user32
    user32.WindowFromPoint.argtypes = [_POINT]
    user32.WindowFromPoint.restype = ctypes.c_void_p
    user32.GetWindowThreadProcessId.argtypes = [ctypes.c_void_p, ctypes.POINTER(ctypes.c_uint32)]
    user32.GetWindowThreadProcessId.restype = ctypes.c_uint32
    hwnd = user32.WindowFromPoint(_POINT(int(x), int(y)))
    if not hwnd:
        return False
    owner = ctypes.c_uint32()
    user32.GetWindowThreadProcessId(hwnd, ctypes.byref(owner))
    return owner.value == (process_id or os.getpid())


if os.name == "nt":
    _WNDPROC = ctypes.WINFUNCTYPE(ctypes.c_ssize_t, ctypes.c_void_p, ctypes.c_uint,
                                  ctypes.c_size_t, ctypes.c_ssize_t)
else:
    _WNDPROC = None


def _guid_equal(first, second: _GUID) -> bool:
    return bool(first) and ctypes.string_at(first, ctypes.sizeof(_GUID)) == bytes(second)


def _drop_effect(kind: str | None, key_state: int, allowed: int) -> int:
    if kind == "virtual":
        return DROPEFFECT_COPY if allowed & DROPEFFECT_COPY else DROPEFFECT_NONE
    if kind == "files":
        preferred = DROPEFFECT_MOVE if key_state & MK_SHIFT else DROPEFFECT_COPY
        if allowed & preferred:
            return preferred
        fallback = DROPEFFECT_COPY if preferred == DROPEFFECT_MOVE else DROPEFFECT_MOVE
        return fallback if allowed & fallback else DROPEFFECT_NONE
    return DROPEFFECT_NONE


def _hdrop_paths_from_data_object(data_object: int) -> list[Path]:
    medium = _get_medium(data_object, CF_HDROP, -1, TYMED_HGLOBAL)
    try:
        shell32 = ctypes.windll.shell32
        shell32.DragQueryFileW.argtypes = [ctypes.c_void_p, ctypes.c_uint,
                                           ctypes.c_wchar_p, ctypes.c_uint]
        shell32.DragQueryFileW.restype = ctypes.c_uint
        count = shell32.DragQueryFileW(medium.data, UINT_MAX, None, 0)
        paths = []
        for index in range(count):
            length = shell32.DragQueryFileW(medium.data, index, None, 0)
            buffer = ctypes.create_unicode_buffer(length + 1)
            shell32.DragQueryFileW(medium.data, index, buffer, len(buffer))
            paths.append(Path(buffer.value))
        return paths
    finally:
        _release_medium(medium)


if os.name == "nt":
    _QUERY_INTERFACE = ctypes.WINFUNCTYPE(ctypes.c_long, ctypes.c_void_p,
                                          ctypes.POINTER(_GUID), ctypes.POINTER(ctypes.c_void_p))
    _ADD_REF = ctypes.WINFUNCTYPE(ctypes.c_ulong, ctypes.c_void_p)
    _RELEASE = ctypes.WINFUNCTYPE(ctypes.c_ulong, ctypes.c_void_p)
    _DRAG_ENTER = ctypes.WINFUNCTYPE(ctypes.c_long, ctypes.c_void_p, ctypes.c_void_p,
                                     ctypes.c_uint32, _POINT, ctypes.POINTER(ctypes.c_uint32))
    _DRAG_OVER = ctypes.WINFUNCTYPE(ctypes.c_long, ctypes.c_void_p, ctypes.c_uint32,
                                    _POINT, ctypes.POINTER(ctypes.c_uint32))
    _DRAG_LEAVE = ctypes.WINFUNCTYPE(ctypes.c_long, ctypes.c_void_p)
    _DROP = ctypes.WINFUNCTYPE(ctypes.c_long, ctypes.c_void_p, ctypes.c_void_p,
                               ctypes.c_uint32, _POINT, ctypes.POINTER(ctypes.c_uint32))

    class _IDropTargetVTable(ctypes.Structure):
        _fields_ = [("QueryInterface", _QUERY_INTERFACE), ("AddRef", _ADD_REF),
                    ("Release", _RELEASE), ("DragEnter", _DRAG_ENTER),
                    ("DragOver", _DRAG_OVER), ("DragLeave", _DRAG_LEAVE), ("Drop", _DROP)]

    class _IDropTargetInstance(ctypes.Structure):
        _fields_ = [("lpVtbl", ctypes.POINTER(_IDropTargetVTable))]


class _OleDropTarget:
    """Small COM IDropTarget that accepts Shell paths and Office virtual files."""

    def __init__(self, owner) -> None:
        self.owner = owner
        self.references = 1
        self.kind = None
        self.callbacks = (
            _QUERY_INTERFACE(self._query_interface), _ADD_REF(self._add_ref),
            _RELEASE(self._release), _DRAG_ENTER(self._drag_enter),
            _DRAG_OVER(self._drag_over), _DRAG_LEAVE(self._drag_leave), _DROP(self._drop),
        )
        self.vtable = _IDropTargetVTable(*self.callbacks)
        self.instance = _IDropTargetInstance(ctypes.pointer(self.vtable))
        self.pointer = ctypes.addressof(self.instance)

    def _query_interface(self, this, iid, result):
        if _guid_equal(iid, IID_IUNKNOWN) or _guid_equal(iid, IID_IDROPTARGET):
            result[0] = this
            self._add_ref(this)
            return S_OK
        result[0] = None
        return E_NOINTERFACE

    def _add_ref(self, _this):
        self.references += 1
        return self.references

    def _release(self, _this):
        self.references = max(0, self.references - 1)
        return self.references

    def _detect_kind(self, data_object: int) -> str | None:
        try:
            # Explorer may advertise virtual formats too; prefer durable paths
            # so its normal copy/Shift-move behavior remains intact.
            if data_object_has_format(data_object, CF_HDROP, -1, TYMED_HGLOBAL):
                return "files"
            if self.owner.virtual_callback and data_object_has_format(
                    data_object, virtual_file_format_id(), -1, TYMED_HGLOBAL):
                return "virtual"
        except (OSError, ValueError):
            pass
        return None

    def _drag_enter(self, _this, data_object, key_state, _point, effect):
        self.kind = self._detect_kind(data_object)
        effect[0] = _drop_effect(self.kind, key_state, effect[0])
        return S_OK

    def _drag_over(self, _this, key_state, _point, effect):
        effect[0] = _drop_effect(self.kind, key_state, effect[0])
        return S_OK

    def _drag_leave(self, _this):
        self.kind = None
        return S_OK

    def _drop(self, _this, data_object, key_state, point, effect):
        kind = self.kind or self._detect_kind(data_object)
        accepted = _drop_effect(kind, key_state, effect[0])
        try:
            if kind == "files":
                paths = _hdrop_paths_from_data_object(data_object)
                self.owner._queue_file_drop(paths, point.x, point.y,
                                            accepted == DROPEFFECT_MOVE)
            elif kind == "virtual":
                self.owner._queue_virtual_drop(data_object, point.x, point.y)
            else:
                accepted = DROPEFFECT_NONE
        except (OSError, MemoryError):
            accepted = DROPEFFECT_NONE
        self.kind = None
        effect[0] = accepted
        return S_OK


class ShellFileDropTarget:
    """Explorer and Office virtual-file drop target attached to a Tk widget HWND."""

    def __init__(self, widget, callback, virtual_callback=None) -> None:
        self.widget = widget
        self.callback = callback
        self.virtual_callback = virtual_callback
        self.hwnd = 0
        self.old_proc = 0
        self._window_proc = None
        self._ole_target = None
        self._ole_initialized = False
        self._ole_registered = False
        self._virtual_results = queue.Queue()
        self._virtual_workers = 0
        self._virtual_poll_job = None
        if os.name == "nt":
            self.install()

    @property
    def active(self) -> bool:
        return bool(self.hwnd and self.old_proc and self._window_proc)

    def install(self) -> None:
        if self.active or os.name != "nt":
            return
        user32, shell32 = ctypes.windll.user32, ctypes.windll.shell32
        self.hwnd = int(self.widget.winfo_id())
        self._window_proc = _WNDPROC(self._dispatch)
        user32.SetWindowLongPtrW.argtypes = [ctypes.c_void_p, ctypes.c_int, ctypes.c_void_p]
        user32.SetWindowLongPtrW.restype = ctypes.c_void_p
        ctypes.set_last_error(0)
        previous = user32.SetWindowLongPtrW(
            ctypes.c_void_p(self.hwnd), GWL_WNDPROC,
            ctypes.cast(self._window_proc, ctypes.c_void_p))
        if not previous:
            error = ctypes.get_last_error()
            self._window_proc = None
            self.hwnd = 0
            raise OSError(error, "Cannot enable Windows Explorer file drop.")
        self.old_proc = int(previous)
        shell32.DragAcceptFiles.argtypes = [ctypes.c_void_p, ctypes.c_int]
        shell32.DragAcceptFiles(ctypes.c_void_p(self.hwnd), True)
        self._install_ole_target()
        self.widget.bind("<Destroy>", lambda _event: self.close(), add="+")

    def _install_ole_target(self) -> None:
        ole32 = ctypes.windll.ole32
        ole32.OleInitialize.argtypes = [ctypes.c_void_p]
        ole32.OleInitialize.restype = ctypes.c_long
        status = ole32.OleInitialize(None)
        if _failed(status):
            return
        self._ole_initialized = True
        self._ole_target = _OleDropTarget(self)
        ole32.RegisterDragDrop.argtypes = [ctypes.c_void_p, ctypes.c_void_p]
        ole32.RegisterDragDrop.restype = ctypes.c_long
        status = ole32.RegisterDragDrop(ctypes.c_void_p(self.hwnd),
                                        ctypes.c_void_p(self._ole_target.pointer))
        if _failed(status):
            self._ole_target = None
            ole32.OleUninitialize()
            self._ole_initialized = False
            return
        self._ole_registered = True

    def _queue_file_drop(self, paths, x_root: int, y_root: int, move: bool) -> None:
        self.widget.after_idle(lambda: self.callback(list(paths), x_root, y_root, move))

    def _queue_virtual_drop(self, data_object: int, x_root: int, y_root: int) -> None:
        raw = tempfile.mkdtemp(prefix="pfc-office-drop-")
        try:
            stream = _marshal_data_object(data_object)
        except Exception:
            shutil.rmtree(raw, ignore_errors=True)
            raise

        self._virtual_workers += 1
        if self._virtual_poll_job is None:
            self._virtual_poll_job = self.widget.after(40, self._poll_virtual_results)

        def extract():
            initialized = False; marshalled = None
            try:
                ole32 = ctypes.windll.ole32
                status = ole32.CoInitializeEx(None, COINIT_APARTMENTTHREADED)
                initialized = not _failed(status)
                marshalled = _unmarshal_data_object(stream)
                items, failures = extract_virtual_files_from_data_object(
                    marshalled, Path(raw))
                self._virtual_results.put((raw, items, failures, x_root, y_root))
            except Exception as exc:
                self._virtual_results.put((raw, [], [("Office attachment", str(exc))],
                                           x_root, y_root))
            finally:
                if marshalled: _release_interface(marshalled)
                if initialized: ctypes.windll.ole32.CoUninitialize()
        threading.Thread(target=extract, daemon=True,
                         name="PFC-Office-Drop").start()

    def _poll_virtual_results(self) -> None:
        self._virtual_poll_job = None
        while True:
            try:
                raw, items, failures, x_root, y_root = self._virtual_results.get_nowait()
            except queue.Empty:
                break
            self._virtual_workers = max(0, self._virtual_workers - 1)
            try:
                self.virtual_callback(items, failures, x_root, y_root)
            finally:
                shutil.rmtree(raw, ignore_errors=True)
        if self._virtual_workers:
            self._virtual_poll_job = self.widget.after(40, self._poll_virtual_results)

    def _dispatch(self, hwnd, message, wparam, lparam):
        if message == WM_DROPFILES:
            try:
                paths, x_root, y_root, move = self._read_drop(wparam)
                self._queue_file_drop(paths, x_root, y_root, move)
            except Exception:
                pass
            return 0
        user32 = ctypes.windll.user32
        user32.CallWindowProcW.argtypes = [ctypes.c_void_p, ctypes.c_void_p, ctypes.c_uint,
                                           ctypes.c_size_t, ctypes.c_ssize_t]
        user32.CallWindowProcW.restype = ctypes.c_ssize_t
        return user32.CallWindowProcW(ctypes.c_void_p(self.old_proc), hwnd, message, wparam, lparam)

    def _read_drop(self, handle: int):
        shell32, user32 = ctypes.windll.shell32, ctypes.windll.user32
        shell32.DragQueryFileW.argtypes = [ctypes.c_void_p, ctypes.c_uint,
                                           ctypes.c_wchar_p, ctypes.c_uint]
        shell32.DragQueryFileW.restype = ctypes.c_uint
        shell32.DragQueryPoint.argtypes = [ctypes.c_void_p, ctypes.POINTER(_POINT)]
        shell32.DragQueryPoint.restype = ctypes.c_int
        shell32.DragFinish.argtypes = [ctypes.c_void_p]
        try:
            count = shell32.DragQueryFileW(ctypes.c_void_p(handle), UINT_MAX, None, 0)
            paths = []
            for index in range(count):
                length = shell32.DragQueryFileW(ctypes.c_void_p(handle), index, None, 0)
                buffer = ctypes.create_unicode_buffer(length + 1)
                shell32.DragQueryFileW(ctypes.c_void_p(handle), index, buffer, len(buffer))
                paths.append(Path(buffer.value))
            point = _POINT()
            shell32.DragQueryPoint(ctypes.c_void_p(handle), ctypes.byref(point))
            user32.ClientToScreen.argtypes = [ctypes.c_void_p, ctypes.POINTER(_POINT)]
            user32.ClientToScreen(ctypes.c_void_p(self.hwnd), ctypes.byref(point))
            user32.GetKeyState.argtypes = [ctypes.c_int]
            move = bool(user32.GetKeyState(VK_SHIFT) & 0x8000)
            return paths, point.x, point.y, move
        finally:
            shell32.DragFinish(ctypes.c_void_p(handle))

    def close(self) -> None:
        if not self.active or os.name != "nt":
            return
        user32, shell32 = ctypes.windll.user32, ctypes.windll.shell32
        if self._ole_registered:
            ctypes.windll.ole32.RevokeDragDrop(ctypes.c_void_p(self.hwnd))
            self._ole_registered = False
        if self._virtual_poll_job is not None:
            try: self.widget.after_cancel(self._virtual_poll_job)
            except Exception: pass
            self._virtual_poll_job = None
        self._ole_target = None
        if self._ole_initialized:
            ctypes.windll.ole32.OleUninitialize()
            self._ole_initialized = False
        shell32.DragAcceptFiles(ctypes.c_void_p(self.hwnd), False)
        user32.IsWindow.argtypes = [ctypes.c_void_p]
        if user32.IsWindow(ctypes.c_void_p(self.hwnd)):
            user32.SetWindowLongPtrW(ctypes.c_void_p(self.hwnd), GWL_WNDPROC,
                                     ctypes.c_void_p(self.old_proc))
        self.hwnd = 0
        self.old_proc = 0
        self._window_proc = None


